INSERT INTO categories (id, name, icon, description) VALUES
  ('adventure', 'Приключения', '🧗', 'Активные маршруты с драйвом: каньоны, дюны, горные дороги, рафтинг и необычный транспорт.'),
  ('trek', 'Треккинг и горы', '🥾', 'Пешие переходы с ночёвками в приютах, чайных домиках и палатках. Разная сложность, от прогулочной до высокогорной.'),
  ('gastro', 'Гастрономия', '🍷', 'Путешествия через вкус: рынки, винодельни, кухни местных семей и мастер-классы.'),
  ('culture', 'Культура и история', '🏛️', 'Города, храмы, ремёсла и живые традиции. Мало автобусных экскурсий, много общения с местными.'),
  ('beach', 'Пляжи и острова', '🏝️', 'Море, лагуны и острова с активностями на воде: снорклинг, каяки, переходы на лодках.'),
  ('expedition', 'Экспедиции', '🧭', 'Дальние маршруты вне привычной инфраструктуры: кемпинги, джипы, вулканы и сафари.'),
  ('retreat', 'Ретриты и природа', '🧘', 'Неспешный отдых: практики, природа, местная кухня, минимум переездов.'),
  ('road', 'Роуд-трипы', '🚐', 'Дорожные маршруты на автомобиле или фургоне с остановками там, где красиво, а не там, где удобно автобусу.'),
  ('photo', 'Фототуры', '📷', 'Маршруты под свет и сюжет: рассветы, северное сияние, пейзажи. Группа небольшая, чтобы всем хватало места.'),
  ('private', 'Для своей компании', '👥', 'Приватные поездки для друзей и семьи на 4–8 человек. Даты и темп выбираете вы.');
