INSERT INTO guides (id, name, role, city, country_id, languages, experience_years, specialties, bio, style, photo_url, credentials, is_demo_profile) VALUES
  ('anna', 'Анна Ветрова', 'Горный гид', 'Москва', 'ru', ARRAY['русский','английский','итальянский']::text[], 11, ARRAY['треккинг','горные приюты','альпийские маршруты']::text[], 'Ведёт малые группы по Альпам и Доломитам. Строит дни так, чтобы самые красивые участки приходились на утренний и вечерний свет, а середина дня оставалась для отдыха в приюте.', 'Идёт в темпе самого медленного участника, заранее готовит запасной вариант на случай дождя и перед выходом разбирает маршрут на карте.', NULL, '[]'::jsonb, TRUE),
  ('kenji', 'Кэндзи Ямада', 'Гид по культуре Японии', 'Киото', 'jp', ARRAY['русский','английский','японский']::text[], 14, ARRAY['традиционные ремёсла','чайная культура','храмы и сады']::text[], 'Вырос в Киото и показывает город через мастерские, чайные дома и небольшие храмы. Объясняет контекст: почему сад устроен именно так и как правильно смотреть на предмет ремесла.', 'Группа не больше 8 человек, мало переездов, много времени на разговоры с мастерами. Перед поездкой присылает короткую памятку об этикете.', NULL, '[]'::jsonb, TRUE),
  ('marat', 'Марат Исаев', 'Фотограф-инструктор', 'Санкт-Петербург', 'ru', ARRAY['русский','английский']::text[], 9, ARRAY['пейзажная съёмка','ночная съёмка','северное сияние']::text[], 'Снимает природные сюжеты и ведёт фототуры. Помогает настроить камеру для ночной съёмки и подобрать композицию, не навязывая собственный стиль.', 'В группе до 8 человек, чтобы у каждого был доступ к лучшей точке. Каждый вечер — разбор кадров. Подойдёт и владельцам смартфонов.', NULL, '[]'::jsonb, TRUE),
  ('lina', 'Лина Хасан', 'Гид по истории Египта', 'Каир', 'eg', ARRAY['русский','английский','арабский']::text[], 12, ARRAY['Древний Египет','раскопки и музеи','маршруты вне потока']::text[], 'Специализируется на истории Древнего Египта. Выстраивает маршрут так, чтобы приходить к главным объектам в часы, когда там меньше людей, и рассказывает без заученных текстов.', 'Работает с группами до 12 человек, обязательно оставляет в программе время на свободное знакомство с городом и местной кухней.', NULL, '[]'::jsonb, TRUE),
  ('dewa', 'Дева Путра', 'Хост ретритов, инструктор йоги', 'Убуд', 'id', ARRAY['русский','английский','индонезийский']::text[], 8, ARRAY['йога','балийская культура','церемонии']::text[], 'Родился на Бали. Организует ретриты в маленьких виллах среди рисовых террас, знакомит с храмовыми церемониями и семейной кухней.', 'Утренние практики не обязательны. Каждый выбирает свою нагрузку. Темп неспешный, переездов минимум.', NULL, '[]'::jsonb, TRUE),
  ('dan', 'Даниил Рощин', 'Организатор роуд-трипов', 'Денвер', 'us', ARRAY['русский','английский']::text[], 7, ARRAY['автопутешествия','национальные парки','кемпинг']::text[], 'Организует путешествия по американскому Юго-Западу и по Route 66. Строит маршрут вокруг закатов, рассветов и мест, где можно спокойно остановиться на ночь.', 'Группа до 6 человек в одном кемпервене или двух автомобилях. Общая кухня, совместные решения по маршруту, водители меняются.', NULL, '[]'::jsonb, TRUE),
  ('priya', 'Прия Шарма', 'Шеф и гастро-гид', 'Джайпур', 'in', ARRAY['русский','английский','хинди']::text[], 10, ARRAY['индийская кухня','специи','рынки']::text[], 'Готовит блюда Раджастхана и водит по рынкам. Знакомит с семьями, где можно научиться готовить и узнать, как специи работают в разных блюдах.', 'Строит программу вокруг трёх вещей: рынок утром, приготовление днём, ужин за общим столом. Учитывает диеты и вегетарианское питание.', NULL, '[]'::jsonb, TRUE),
  ('omar', 'Омар аль-Фарси', 'Организатор поездок по Аравии', 'Дубай', 'ae', ARRAY['русский','английский','арабский']::text[], 6, ARRAY['пустыня','оазисы','рыбацкие деревни']::text[], 'Показывает Эмираты за пределами небоскрёбов: пустынные лагеря, горные оазисы, старые кварталы и ремесленные рынки.', 'Выезды короткие, 4–6 дней, с акцентом на безопасность в пустыне: местные водители, запас воды, связь.', NULL, '[]'::jsonb, TRUE),
  ('tashi', 'Таши Шерпа', 'Гид по Гималаям', 'Покхара', 'np', ARRAY['русский','английский','непальский']::text[], 13, ARRAY['высотный треккинг','гималайские деревни']::text[], 'Родом из горной деревни, водит треккинговые группы в Аннапурне. Следит за акклиматизацией и состоянием участников, знает хозяев чайных домиков по именам.', 'Ежедневный осмотр самочувствия, график набора высоты с запасным днём, групповой темп. Всегда носит с собой пульсоксиметр и аптечку.', NULL, '[]'::jsonb, TRUE),
  ('mai', 'Май Нгуен', 'Организатор поездок по Юго-Восточной Азии', 'Ханой', 'vn', ARRAY['русский','английский','вьетнамский']::text[], 8, ARRAY['уличная еда','горные дороги','речные деревни']::text[], 'Работает по Вьетнаму и Таиланду. Знает рынки и закусочные, где едят местные, и поддерживает связи с семейными гостевыми домами.', 'Группа до 10 человек, питание — на улице и в семейных заведениях. Перед ужином объясняет, что в тарелке и как это едят.', NULL, '[]'::jsonb, TRUE),
  ('eirik', 'Эйрик Хансен', 'Гид по северной Норвегии', 'Свольвер', 'no', ARRAY['русский','английский','норвежский']::text[], 10, ARRAY['лофотенские горы','фиорды','ночная съёмка']::text[], 'Живёт на Лофотенских островах. Проводит пешие маршруты на невысоких, но выразительных вершинах и помогает ловить свет в северных широтах.', 'Погода меняется быстро, поэтому программа гибкая: гид выбирает вершину или береговую тропу по прогнозу накануне.', NULL, '[]'::jsonb, TRUE),
  ('diego', 'Диего Кеспе', 'Гид по Андам', 'Куско', 'pe', ARRAY['русский','английский','испанский','кечуа']::text[], 12, ARRAY['трекинг в Андах','культура кечуа','инкская история']::text[], 'Родился в долине Урубамба. Ведёт маршруты в обход переполненных троп, рассказывает об инках через живые традиции, а не только через руины.', 'Следит за акклиматизацией: день в Куско и Священной долине перед горным маршрутом. Идёт с носильщиками и поваром из деревень региона.', NULL, '[]'::jsonb, TRUE),
  ('yusuf', 'Юсуф Бенали', 'Организатор маршрутов по Магрибу и Леванту', 'Марракеш', 'ma', ARRAY['русский','английский','французский','арабский']::text[], 9, ARRAY['медины','пустыня','горные деревни']::text[], 'Строит маршруты по Марокко и Иордании. Знает, как пройти по старым городам без навязчивых торговцев и где лучше встретить рассвет в пустыне.', 'Небольшие семейные риады вместо отелей, караван в пустыню только при хорошей погоде, свободное время для базара.', NULL, '[]'::jsonb, TRUE),
  ('aylin', 'Айлин Йылмаз', 'Гид по Турции', 'Стамбул', 'tr', ARRAY['русский','английский','турецкий']::text[], 10, ARRAY['Каппадокия','античные города','кухня Эгейского моря']::text[], 'Работает в Каппадокии, Стамбуле и на Эгейском побережье. Показывает места до и после автобусных потоков, добавляет в маршрут местные ремёсла и кухню.', 'Небольшие семейные отели, утренние выходы в долины, мастер-классы по керамике и готовке.', NULL, '[]'::jsonb, TRUE),
  ('nino', 'Нино Беридзе', 'Гид по Грузии', 'Тбилиси', 'ge', ARRAY['русский','английский','грузинский']::text[], 9, ARRAY['вино','горные деревни','грузинская кухня']::text[], 'Родом из Кахети, работает с винными хозяйствами и семейными кухнями. Любит маршруты, где утро проходит в горах, а вечер — за большим столом.', 'Дегустации в небольших виноделиях, дороги в горы с проверенными водителями, свободный вечер для самостоятельной прогулки по Тбилиси.', NULL, '[]'::jsonb, TRUE),
  ('sanjaya', 'Санджая Перера', 'Гид по Шри-Ланке', 'Канди', 'lk', ARRAY['русский','английский','сингальский']::text[], 11, ARRAY['чайные плантации','национальные парки','буддийская культура']::text[], 'Знает остров от побережья до чайных гор. Составляет маршруты, где переезды короткие, а ночёвки — в небольших гестхаусах.', 'Рано утром — храмы и сафари, днём — отдых, вечером — разговоры. Помогает с питанием для тех, кто не любит острое.', NULL, '[]'::jsonb, TRUE),
  ('rui', 'Руй Феррейра', 'Гастро-гид по Португалии', 'Лиссабон', 'pt', ARRAY['русский','английский','португальский']::text[], 8, ARRAY['вино','морепродукты','старые кварталы']::text[], 'Работает с небольшими квинтами и семейными ресторанами. Показывает Лиссабон и долину Дору через вкус: от паштейш до вина из старых лоз.', 'Каждый день — одно главное блюдо или производитель. В группе до 10 человек, дегустации без спешки.', NULL, '[]'::jsonb, TRUE),
  ('chiara', 'Кьяра Росси', 'Организатор приватных поездок по Италии', 'Сиена', 'it', ARRAY['русский','английский','итальянский']::text[], 10, ARRAY['Тоскана','кулинарные мастер-классы','виноделие']::text[], 'Организует поездки для друзей и семей в Тоскане. Подбирает виллы, знакомит с хозяйствами и строит неспешные дни.', 'Маршрут подстраивается под компанию, а не наоборот. Перед поездкой обсуждает ожидания и ограничения.', NULL, '[]'::jsonb, TRUE),
  ('jisoo', 'Джису Пак', 'Гид по Южной Корее', 'Сеул', 'kr', ARRAY['русский','английский','корейский']::text[], 7, ARRAY['кухня','храмы','острова']::text[], 'Работает в Сеуле и на острове Чеджу. Показывает дворцы и храмы, уличную еду и тихие тропы, о которых редко пишут путеводители.', 'Группа до 10 человек, общественный транспорт и небольшие автобусы, пеший темп среднего уровня, с остановками на кофе и еду.', NULL, '[]'::jsonb, TRUE),
  ('liam', 'Лиам Харрис', 'Организатор поездок по Новой Зеландии', 'Квинстаун', 'nz', ARRAY['русский','английский']::text[], 9, ARRAY['автопутешествия','короткие прогулки','озёра и горы']::text[], 'Организует маршруты по Южному острову на фургонах и в небольших группах. Специализируется на дорогах, где остановка у озера важнее графика.', 'Дни сочетают переезд и короткие пешие прогулки, остановки по погоде, ночёвки в кемпингах и мотелях.', NULL, '[]'::jsonb, TRUE),
  ('baraka', 'Бараки Мванза', 'Сафари-гид', 'Аруша', 'tz', ARRAY['русский','английский','суахили']::text[], 12, ARRAY['сафари','поведение животных','национальные парки']::text[], 'Работает в северных парках Танзании. Помогает находить животных и объясняет их поведение, не нарушая правила парка.', 'Утренние и вечерние выезды, днём отдых в лодже или лагере. Фотографам оставляет лучшие места в машине поочерёдно.', NULL, '[]'::jsonb, TRUE),
  ('temuulen', 'Тэмүүлэн Бат', 'Гид по Монголии', 'Улан-Батор', 'mn', ARRAY['русский','английский','монгольский']::text[], 8, ARRAY['кочевая жизнь','степь','Гоби']::text[], 'Родом из семьи скотоводов. Ведёт маршруты по степям и пустыне Гоби, знакомит с семьями кочевников и показывает повседневную жизнь без постановки.', 'Проживание в гэрах, джипы с местными водителями, свободное время для общения и верховой езды. Темп спокойный, связь ограничена.', NULL, '[]'::jsonb, TRUE),
  ('igor', 'Игорь Лавров', 'Гид по Камчатке', 'Петропавловск-Камчатский', 'ru', ARRAY['русский','английский']::text[], 11, ARRAY['вулканы','медведи','термальные источники']::text[], 'Много лет работает на Камчатке. Ведёт группы к вулканам и в долины с источниками, соблюдая правила поведения при встрече с медведем.', 'Погодные окна определяют порядок маршрута. Для вертолётных участков держит запасные дни, группа не больше 8 человек.', NULL, '[]'::jsonb, TRUE);
