INSERT INTO cancellation_policies (id, name, disclaimer, is_demo, tiers) VALUES
  ('standard-demo', 'Стандартные условия отмены (шаблон)', 'Шаблон для демонстрации. Юридически значимые условия утверждаются в договоре после запуска компании.', TRUE, '[{"days_from":60,"days_to":null,"refund_percent":100,"note":"Возврат всей внесённой суммы, кроме уже оплаченных невозвратных расходов (билеты, визовые сборы, депозиты у поставщиков)."},{"days_from":30,"days_to":59,"refund_percent":80,"note":"Удерживается сумма предоплаты."},{"days_from":15,"days_to":29,"refund_percent":50,"note":"Удерживается половина стоимости тура."},{"days_from":0,"days_to":14,"refund_percent":0,"note":"Возврат не предусмотрен. Рекомендуем туристическую страховку с покрытием отмены поездки."}]'::jsonb);
INSERT INTO tours (id, title, country_id, region, category_id, format, private_available, days, nights, start_point, end_point, price_from, currency, single_supplement, season_months, season_best, season_note, group_min, group_max, difficulty, difficulty_note, fitness_requirements, short_description, description, highlights, accommodation, transport, meals, included, excluded, requirements, equipment, restrictions, docs_note, suitable_for, not_suitable_for, advantages, guide_id, cancellation_policy_id, hero_image, gallery_images, tags, is_demo, data_status) VALUES
  ('bali-retreat', 'Бали: йога-ретрит среди рисовых террас', 'id', 'Убуд и Нуса-Пенида', 'retreat', 'small_group', TRUE, 10, 9, 'Аэропорт Денпасара', 'Аэропорт Денпасара', 135000, 'RUB', 20000, ARRAY[4,5,6,7,8,9,10]::smallint[], 'С апреля по октябрь (сухой сезон)', 'В дождливый сезон программа сохраняется, но часть активностей на воде и в горах может быть изменена.', 6, 14, 1, 'Мягкая практика йоги и прогулки до 3 часов. Опыт не нужен.', NULL, 'Десять дней практики, храмовых церемоний и местной кухни рядом с рисовыми полями Убуда.', 'Неспешный ретрит в окрестностях Убуда: утренняя практика, свободные дни, церемония очищения в храме Тирта-Эмпул и два дня на острове Нуса-Пенида. Каждый выбирает свою нагрузку, ничего не обязательно. Гид знакомит с балийской культурой через семьи, у которых мы бываем.', ARRAY['Ежедневная йога и медитация','Церемония очищения в храме Тирта-Эмпул','Мастер-класс по балийской кухне в семье','Рисовые террасы Тегаллаланг и Джатилувих','Снорклинг на Нуса-Пениде']::text[], 'Девять ночей: семь ночей на вилле в окрестностях Убуда и две ночи на Нуса-Пениде (двухместные номера или бунгало).', 'Минивэн с водителем, скоростной катер до Нуса-Пениды, велосипеды по желанию.', 'Завтраки, шесть ужинов. Вегетарианское питание возможно.', ARRAY['Размещение: 9 ночей','Завтраки и 6 ужинов','Занятия йогой и медитацией','Все трансферы','Мастер-класс по кухне','Церемония очищения']::text[], ARRAY['Авиабилеты','Спа и массаж','Обеды','Страховка']::text[], ARRAY['Нет особых требований: йога подходит для новичков','Умение плавать для снорклинга']::text[], ARRAY['Коврик (по желанию)','Купальник и защитный от солнца крем','Одежда, закрывающая колени и плечи, для храмов','Репеллент']::text[], ARRAY['Нужно соблюдать правила в храмах','Снорклинг зависит от волнения моря','Скаты манты не гарантируются']::text[], 'Не подтверждено: правила въезда в Индонезию проверяются менеджером.', ARRAY['Тем, кому нужен отдых без спешки','Одиночным путешественникам','Тем, кто хочет попробовать йогу']::text[], ARRAY['Тем, кому нужны шумные вечеринки','Тем, кто не любит влажный климат']::text[], ARRAY['Спокойный ритм','Семейные вилла и кухня','Практика без обязательств','Два острова']::text[], 'dewa', 'standard-demo', 'bali', ARRAY['beach','trek']::text[], ARRAY['ретрит','йога','Бали','острова']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('bernese-oberland-traverse', 'Бернский Оберланд: большой переход Гриндельвальд — Кандерштег', 'ch', 'Бернский Оберланд', 'trek', 'small_group', FALSE, 9, 8, 'Интерлакен', 'Цюрих', 156000, 'RUB', 23000, ARRAY[7,8,9]::smallint[], 'Июль — начало сентября', 'Высокие перевалы могут быть закрыты снегом в начале июля. В сентябре дни короче и возможны заморозки.', 4, 8, 3, 'Дни по 6–8 часов, набор высоты 1 000–1 400 м, перевалы выше 2 600 м. Нужна хорошая физическая форма и опыт горных походов.', NULL, 'Девять дней среди ледников и швейцарских альпийских деревень.', 'Маршрут для опытных ходоков: от Гриндельвальда до Кандерштега через перевалы Кляйне-Шайдегг, Зефинен-Фурге и Хохтюрли. Ночуем в отелях и горных приютах, едим швейцарскую кухню и каждый день смотрим на Айгер, Мёнх и Юнгфрау.', ARRAY['Бахальпзее и вид на Айгер, Мёнх и Юнгфрау','Долина водопадов Лаутербруннен','Перевал Зефинен-Фурге','Перевал Хохтюрли','Озеро Эшинензее']::text[], 'Шесть ночей в отелях, две ночи в горных приютах (общие комнаты).', 'Поезда и канатные дороги по маршруту, трансфер в Цюрих.', 'Завтраки, ужины. Обеды с собой.', ARRAY['Размещение: 8 ночей','Завтраки и ужины','Горный гид','Канатные дороги по маршруту']::text[], ARRAY['Авиабилеты','Обеды','Снаряжение','Страховка']::text[], ARRAY['Опыт треккинга 7–8 часов','Хорошая физическая форма']::text[], ARRAY['Горные ботинки','Палки','Дождевик','Тёплая куртка','Налобный фонарь']::text[], ARRAY['Маршрут зависит от погоды','Перевалы могут быть закрыты снегом','Приюты требуют спальный вкладыш']::text[], 'Не подтверждено: шенгенская виза, проверяется менеджером.', ARRAY['Опытным ходокам','Любителям альпийских видов']::text[], ARRAY['Новичкам','Тем, кто боится высоты']::text[], ARRAY['Высокие перевалы','Ночёвки в приютах','Малая группа']::text[], 'anna', 'standard-demo', 'alps', ARRAY['trek','dolomites']::text[], ARRAY['Швейцария','треккинг','Альпы']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('dolomites-lakes', 'Доломиты: озёра, приюты и рассветы', 'it', 'Доломитовые Альпы, район Кортина-д’Ампеццо', 'trek', 'small_group', TRUE, 7, 6, 'Аэропорт Венеции', 'Аэропорт Венеции', 98000, 'RUB', 15000, ARRAY[6,7,8,9]::smallint[], 'Со второй половины июня до середины сентября', 'Приюты работают летом, на высоких тропах в июне возможны остатки снега. В сентябре дни короче и прохладнее.', 4, 10, 2, 'Дни по 4–7 часов в пути, набор высоты в основном 500–900 м. Есть участки с тросами и осыпями, но без технического лазания.', NULL, 'Семь дней между зелёных озёр и острых скал. Ночуем в отеле и в горном приюте, едим тирольскую кухню.', 'Неспешный треккинг по классическим точкам Доломитов с базой в Кортине. Мы идём по тропам в утренний и вечерний свет, а середину дня оставляем для отдыха в приюте. Ночь в приюте Нуволау даёт возможность встретить рассвет над Доломитами без толпы дневных туристов.', ARRAY['Озеро Брайес и подъём к приюту Бьелла','Круговой маршрут вокруг Тре Чиме ди Лаваредо','Озеро Сорапис бирюзового цвета','Ночь в приюте Нуволау и рассвет над Доломитами','Подземные ходы времён Первой мировой в Лагадзуой']::text[], 'Пять ночей в небольшом отеле или гестхаусе в Кортине (двухместные номера), одна ночь в приюте Нуволау (общая комната или комната на 4–6 мест, туалеты и душ на этаже, душ может быть платным).', 'Трансферы из аэропорта Венеции и обратно на микроавтобусе, радиальные выезды к началу троп. Канатные дороги — по ситуации.', 'Завтраки в отеле, ужины в ресторанах и приютах (пять ужинов из шести). Обеды на маршруте — в приютах или с собой, оплачиваются отдельно.', ARRAY['Размещение: 6 ночей','Завтраки и 5 ужинов','Гид-проводник','Трансферы по маршруту','Билеты на канатную дорогу к Лагадзуой']::text[], ARRAY['Авиабилеты','Обеды и напитки','Личное снаряжение','Туристическая страховка с активным отдыхом','Чаевые (по желанию)']::text[], ARRAY['Опыт горных прогулок 5–6 часов с набором 600–900 м','Умение идти по тропе с осыпью и тросом','Наличие страховки с покрытием треккинга']::text[], ARRAY['Треккинговые ботинки с жёсткой подошвой','Треккинговые палки','Дождевая куртка и тёплый слой','Налобный фонарь','Вкладыш в спальный мешок (для приюта)','Небольшой рюкзак 25–30 литров']::text[], ARRAY['Маршрут зависит от погоды и состояния троп, порядок дней может меняться','Приюты работают в летний сезон, ночёвка в Нуволау зависит от наличия мест у приюта','Детям до 14 лет по согласованию']::text[], 'Не подтверждено: для поездки в Италию может требоваться шенгенская виза, актуальные требования проверяются менеджером до бронирования.', ARRAY['Тем, кто хочет попробовать горные тропы без технической сложности','Фотографам, любящим утренний и вечерний свет','Парам и друзьям, путешествующим без детей']::text[], ARRAY['Тем, кто боится высоты и узких троп (участок Сорапис)','Людям с проблемами коленей и серьёзными сердечно-сосудистыми заболеваниями без консультации врача']::text[], ARRAY['Небольшая группа','Ночь в приюте','Классические и менее посещаемые тропы','Темп можно регулировать']::text[], 'anna', 'standard-demo', 'dolomites', ARRAY['dolo2','alps']::text[], ARRAY['горы','приюты','озёра','Италия']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('dubai-desert', 'Дубай и пустыня: дюны, оазисы и горный Хатта', 'ae', 'Дубай и эмират Дубай', 'adventure', 'small_group', FALSE, 5, 4, 'Дубай', 'Дубай', 72000, 'RUB', 11000, ARRAY[10,11,12,1,2,3,4]::smallint[], 'С октября по апрель', 'Летом очень жарко (40 °C и выше), поэтому маршрут рекомендуется в прохладный сезон.', 4, 14, 1, 'Короткие прогулки по городу, вечер в пустыне, небольшая прогулка в горах. Подходит всем.', NULL, 'Короткий и яркий тур: старый город, ночь в пустыне и горная деревня Хатта.', 'Пять дней, чтобы увидеть другую сторону Эмиратов: старый квартал Бастакия, рынки золота и специй, джип-сафари, ночь в лагере и день в горной деревне Хатта. Вечер на смотровой Бурдж-Халифа добавляет современный контраст.', ARRAY['Старый Дубай и рынки','Джип-сафари и ночь в пустыне','Хатта: озеро и горные дороги','Смотровая площадка Бурдж-Халифа']::text[], 'Три ночи в отеле в Дубае, одна ночь в пустынном лагере.', 'Микроавтобус и внедорожники для сафари.', 'Завтраки, ужин в лагере.', ARRAY['Размещение: 4 ночи','Завтраки','Гид и трансферы','Сафари','Билеты на смотровую']::text[], ARRAY['Авиабилеты','Обеды','Виза (если требуется)','Страховка']::text[], ARRAY['Нет особых требований']::text[], ARRAY['Лёгкая одежда','Шарф от песка','Защитный крем']::text[], ARRAY['Алкоголь ограничен','Одежда должна быть скромной в местах религиозного значения','Сафари зависит от погоды']::text[], 'Не подтверждено: правила въезда проверяются менеджером.', ARRAY['Тем, кто едет на короткое время','Парам и семьям']::text[], ARRAY['Тем, кто не любит жару']::text[], ARRAY['Небольшая группа','Ночь в пустыне','Короткий формат']::text[], 'omar', 'standard-demo', 'dubai', ARRAY['egypt','beach']::text[], ARRAY['Дубай','пустыня','короткий тур']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('egypt-ancient', 'Египет без толп: Каир, Луксор и круиз по Нилу', 'eg', 'Каир — Луксор — Асуан', 'culture', 'small_group', FALSE, 9, 8, 'Аэропорт Каира', 'Аэропорт Каира', 112000, 'RUB', 17000, ARRAY[10,11,12,1,2,3,4]::smallint[], 'С октября по апрель', 'Летом очень жарко, особенно в Луксоре и Асуане, поэтому выезды запланированы в прохладное время года.', 4, 12, 1, 'Ходьба по 3–5 часов в день с остановками. Жарко и пыльно, но нагрузка умеренная. Подходит всем, кто может ходить по лестницам и неровным поверхностям.', NULL, 'Пирамиды на рассвете, Долина царей и круиз по Нилу с гидом, увлечённым историей.', 'Классический египетский маршрут, построенный так, чтобы приходить к главным объектам в часы, когда там меньше людей. Три ночи в Каире, затем Луксор, двухдневный круиз по Нилу и Асуан. Гид рассказывает без заученных текстов и оставляет время на свободные прогулки.', ARRAY['Рассвет на плато Гиза и ступенчатая пирамида в Саккаре','Долина царей и храм Хатшепсут','Карнакский храм вечером','Круиз по Нилу с остановками в Эдфу и Ком-Омбо','Остров Филэ и нубийская деревня','Ранний выезд в Абу-Симбел']::text[], 'Три ночи в отеле в Каире, одна ночь в Луксоре, две ночи на круизном судне, одна ночь в Асуане, одна ночь в Каире (последняя). Двухместные номера, каюты.', 'Минивэны и автобусы с кондиционером, внутренние перелёты Каир — Луксор и Асуан — Каир, круизное судно.', 'Завтраки, пять ужинов. Все приёмы пищи на судне. Обеды в Каире и Луксоре оплачиваются отдельно.', ARRAY['Размещение: 8 ночей','Завтраки и 5 ужинов','Гид по истории (египтолог)','Внутренние перелёты','Круиз по Нилу','Входные билеты по программе']::text[], ARRAY['Международные перелёты','Визовый сбор','Обеды и напитки','Чаевые гидам и водителям','Страховка']::text[], ARRAY['Умение ходить 3–5 часов с остановками','Спокойное отношение к жаре']::text[], ARRAY['Лёгкая закрытая одежда','Шляпа и солнцезащитные очки','Удобная обувь','Крем с высоким SPF','Небольшой рюкзак и бутылка для воды']::text[], ARRAY['Порядок дней может меняться из-за расписания перелётов','В некоторые гробницы нужен отдельный билет','Съёмка в некоторых гробницах платная или запрещена']::text[], 'Не подтверждено: требования к въезду и вакцинации проверяются менеджером.', ARRAY['Путешественникам, которые любят историю','Тем, кто едет впервые в Египет','Группам друзей и семьям с подростками']::text[], ARRAY['Тем, кто не переносит жару','Людям с серьёзными проблемами с ногами']::text[], ARRAY['Гид-египтолог','Ранний вход к объектам','Круиз по Нилу','Нубийская деревня']::text[], 'lina', 'standard-demo', 'egypt', ARRAY['dubai','trek']::text[], ARRAY['история','Нил','Египет','круиз']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('fuji-hike', 'Фудзи и Накасэндо: восхождение и тракт сёгунов', 'jp', 'Хонсю: Фудзи, долина Кисо, Японские Альпы', 'trek', 'small_group', FALSE, 10, 9, 'Токио', 'Токио', 176000, 'RUB', 26000, ARRAY[7,8]::smallint[], 'Июль — начало сентября', 'Тропа Ёсида официально открыта в летний сезон (примерно с начала июля до начала сентября). Вне сезона подъём закрыт или небезопасен.', 4, 10, 3, 'Подъём на Фудзи (3 776 м) с ночёвкой в хижине и выходом на рассвет. Холод, ветер и высота, возможна горная болезнь. Остальные дни — прогулки по 3–6 часов.', NULL, 'Подъём на Фудзи, затем переход по старому тракту Накасэндо и прогулки в Японских Альпах.', 'Десять дней по Хонсю: акклиматизация у Кавагутико, восхождение на Фудзи с рассветом на вершине, онсэн и неспешный переход по долине Кисо по древнему тракту. В конце — Камикоти и замок Мацумото. Маршрут для тех, кто любит горы и хочет увидеть Японию без больших городов.', ARRAY['Восхождение на Фудзи по тропе Ёсида','Рассвет на вершине','Тракт Накасэндо: Магомэ — Цумаго','Каминокоти в Японских Альпах','Замок Мацумото']::text[], 'Восемь ночей в отелях и гостевых домах (двухместные номера), одна ночь в горной хижине на Фудзи (общая комната).', 'Поезда, автобусы и такси. Багаж пересылается курьерской службой.', 'Завтраки, шесть ужинов. Обеды оплачиваются отдельно.', ARRAY['Размещение: 9 ночей','Завтраки и ужины','Гид-проводник','Транспорт по маршруту','Страховка не включена']::text[], ARRAY['Авиабилеты','Обеды','Снаряжение','Страховка (обязательна)']::text[], ARRAY['Опыт треккинга 5–6 часов','Хорошее здоровье, готовность к высоте','Медицинская страховка с покрытием активного отдыха']::text[], ARRAY['Ботинки','Тёплая куртка и шапка','Налобный фонарь','Дождевик','Перчатки']::text[], ARRAY['Горная болезнь возможна, гид может остановить подъём','Погода на Фудзи меняется быстро','Подъём возможен только в сезон']::text[], 'Не подтверждено: условия въезда в Японию проверяются менеджером.', ARRAY['Тем, кто уже ходил в горы','Любителям Японии']::text[], ARRAY['Тем, кто боится высоты и холода','Людям с заболеваниями сердца и дыхания без консультации врача']::text[], ARRAY['Подъём на Фудзи с рассветом','Тракт Накасэндо','Малая группа']::text[], 'kenji', 'standard-demo', 'fuji', ARRAY['japan','kyoto']::text[], ARRAY['Япония','гора Фудзи','Накасэндо','треккинг']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('georgia-wine-mountains', 'Грузия: вино Кахети, горы Казбеги и кухня Тбилиси', 'ge', 'Тбилиси — Кахети — Казбеги', 'gastro', 'small_group', TRUE, 9, 8, 'Тбилиси', 'Тбилиси', 92000, 'RUB', 14000, ARRAY[5,6,9,10]::smallint[], 'Май — июнь и сентябрь — октябрь', 'Сентябрь — октябрь — время сбора винограда (ртвели). Зимой Военно-Грузинская дорога иногда закрывается из-за снега.', 4, 12, 2, 'Прогулки 2–5 часов в горах, длинные застолья. Подходит большинству путешественников.', NULL, 'Девять дней среди виноградников, горных церквей и застолий в Грузии.', 'Маршрут для тех, кто хочет попробовать грузинскую кухню и вино там, где их делают. Начинаем в Тбилиси, едем по Военно-Грузинской дороге к Казбеги, затем в Кахетию. Дегустации — в небольших винодельнях, кухню изучаем на мастер-классах. Каждый вечер — длинный стол (супра) с тостами.', ARRAY['Серные бани Тбилиси','Церковь Гергети под Казбеком','Дегустация вина из квеври','Мастер-класс по хинкали и хачапури','Монастырь Бодбе и Сигнахи']::text[], 'Четыре ночи в гостевых домах и небольших отелях в Тбилиси, две ночи в Казбеги, три ночи в Кахетии.', 'Микроавтобус с водителем, внедорожник в Гергети (по желанию).', 'Завтраки, ужины и мастер-классы. Обеды по желанию.', ARRAY['Размещение: 8 ночей','Завтраки и ужины','Гид','Дегустации','Мастер-класс']::text[], ARRAY['Авиабилеты','Обеды','Страховка']::text[], ARRAY['Умение ходить 2–3 часа']::text[], ARRAY['Удобная обувь','Тёплая куртка для гор']::text[], ARRAY['Погода в горах меняется','Вино — по желанию, водитель не пьёт']::text[], 'Не подтверждено.', ARRAY['Гурманам','Парам и друзьям']::text[], ARRAY['Тем, кто не любит долгие застолья']::text[], ARRAY['Малые винодельни','Горные пейзажи','Настоящая супра']::text[], 'nino', 'standard-demo', 'ge-1', ARRAY['ge-2','ge-3']::text[], ARRAY['Грузия','вино','кухня']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('iceland-aurora', 'Северное сияние: фототур по Исландии', 'is', 'Юг и запад острова', 'photo', 'small_group', FALSE, 6, 5, 'Рейкьявик', 'Аэропорт Кефлавик', 164000, 'RUB', 25000, ARRAY[9,10,11,12,1,2,3]::smallint[], 'С конца сентября до марта', 'Сияние зависит от солнечной активности и облачности, мы гарантируем только время и место, но не появление сияния. Ледяные пещеры доступны, как правило, с ноября по март.', 4, 8, 1, 'Короткие прогулки по снегу и льду, ночные выезды. Физическая подготовка не требуется, но нужна устойчивость к холоду.', NULL, 'Охота за сиянием с фотографом-инструктором: настройка камеры, композиция, ночные выезды.', 'Шесть дней, три-четыре ночных выезда и ледяная пещера в Ватнайёкюдле. Фотограф-инструктор помогает настроить камеру и подобрать точки, днём мы смотрим водопады и чёрные пляжи, а вечером разбираем кадры. Подходит владельцам зеркальных, беззеркальных камер и смартфонов.', ARRAY['Ночные выезды за сиянием','Ледяная пещера в Ватнайёкюдле (в сезон)','Водопады Сельяландсфосс и Скоугафосс','Алмазный пляж у ледниковой лагуны','Разбор кадров каждый вечер']::text[], 'Пять ночей в небольших гестхаусах и отелях на юге страны (двухместные номера). Условия зимой простые, душ и туалет могут быть общими.', 'Минивэн с водителем-гидом, зимние шины. Дороги зимой иногда закрываются, маршрут может быть изменён.', 'Завтраки в гестхаусах, обеды и ужины не включены, кроме прощального ужина.', ARRAY['Размещение: 5 ночей','Завтраки','Минивэн с водителем','Фотогид и разбор снимков','Экскурсия в ледяную пещеру (при погодных условиях)']::text[], ARRAY['Авиабилеты','Обеды и ужины','Аренда оборудования','Страховка']::text[], ARRAY['Умение ходить в зимней обуви по скользким поверхностям','Готовность стоять ночью на морозе 1–2 часа']::text[], ARRAY['Камера или смартфон с ручным режимом','Штатив','Запасные аккумуляторы (холод быстро их разряжает)','Тёплая одежда в несколько слоёв','Налобный фонарь с красным светом']::text[], ARRAY['Сияние не гарантировано: погода и солнечная активность непредсказуемы','Ледяные пещеры закрываются при ухудшении условий','Во время сильных штормов возможны задержки']::text[], 'Не подтверждено: для поездки в Исландию, как правило, нужна шенгенская виза. Проверяется менеджером.', ARRAY['Фотографам-любителям и начинающим','Парам и друзьям','Тем, кто хочет увидеть Исландию зимой']::text[], ARRAY['Тем, кто плохо переносит холод и ночные бодрствования','Тем, кто ожидает гарантированного сияния']::text[], ARRAY['Группа до 8 человек','Инструктор по ночной съёмке','Зимний маршрут по югу','Обработка снимков']::text[], 'marat', 'standard-demo', 'aurora', ARRAY['alps','dolo2']::text[], ARRAY['фототур','северное сияние','Исландия','зима']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('iceland-ring', 'Исландия: кольцевая дорога за 9 дней', 'is', 'Кольцевая дорога вокруг острова', 'road', 'small_group', FALSE, 9, 8, 'Рейкьявик', 'Кефлавик', 142000, 'RUB', 21000, ARRAY[6,7,8,9]::smallint[], 'Июнь — начало сентября', 'Белые ночи в июне и июле. Горные дороги открываются в июне. В сентябре возможна первая ночь с сиянием.', 4, 8, 2, 'Переезды по 3–5 часов и короткие прогулки до трёх часов. Погода меняется быстро.', NULL, 'Полный круг по острову: вулканы, ледники, водопады и горячие источники.', 'Девять дней на минивэне по кольцевой дороге. Мы останавливаемся у водопадов, на чёрных пляжах и у геотермальных зон, заходим на ледниковую лагуну и в Мюватн. Ночуем в гестхаусах и небольших отелях. Белые ночи позволяют снимать в любое время.', ARRAY['Водопады Сельяландсфосс, Скоугафосс и Деттифосс','Ледниковая лагуна Йёкюльсаурлоун','Геотермальная зона Мюватн','Наблюдение за китами в Хусавике','Белые ночи']::text[], 'Восемь ночей в гестхаусах и небольших отелях (двухместные номера, душ может быть общий).', 'Минивэн с водителем-гидом, около 2 000 км за поездку.', 'Завтраки, некоторые ужины. Обеды самостоятельно.', ARRAY['Размещение: 8 ночей','Завтраки','Минивэн','Гид-водитель','Выход на наблюдение за китами']::text[], ARRAY['Авиабилеты','Обеды и ужины','Купание в Мюватн (оплачивается отдельно)','Страховка']::text[], ARRAY['Готовность ехать по 3–5 часов','Умение идти по скользким тропам']::text[], ARRAY['Дождевик','Тёплый слой','Треккинговая обувь','Маска для сна (белые ночи)']::text[], ARRAY['Погода меняется очень быстро','Горные дороги открыты только летом','Некоторые участки на востоке зависят от ветра']::text[], 'Не подтверждено: шенгенская виза.', ARRAY['Путешественникам, которые любят дороги','Парам и друзьям']::text[], ARRAY['Тем, кто не любит долгие переезды']::text[], ARRAY['Полный круг острова','Белые ночи','Небольшая группа']::text[], 'marat', 'standard-demo', 'dolo2', ARRAY['aurora','alps']::text[], ARRAY['Исландия','кольцевая дорога','водопады']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('jordan-petra-wadi-rum', 'Иордания: Петра, Вади-Рам и каньон Муджиб', 'jo', 'Амман — Петра — Вади-Рам — Мёртвое море', 'adventure', 'small_group', FALSE, 8, 7, 'Амман', 'Амман', 126000, 'RUB', 19000, ARRAY[3,4,5,10,11]::smallint[], 'Март — май и октябрь — ноябрь', 'Летом в Петре и Вади-Раме очень жарко, зимой по ночам холодно. Каньон Муджиб открыт только в тёплый сезон (примерно с апреля по октябрь).', 4, 12, 2, 'Прогулки по 3–6 часов, лестницы в Петре, подъём к Монастырю (около 800 ступеней).', NULL, 'Восемь дней: розовые скалы Петры, бедуинский лагерь и купание в Мёртвом море.', 'Маршрут по главным местам Иордании с акцентом на прогулки. Два дня в Петре (включая вечер со свечами), ночь в бедуинском лагере в Вади-Раме, поход по каньону Муджиб и вечер в Мёртвом море. Группа небольшая, поэтому мы можем идти в удобное время.', ARRAY['Петра: Сокровищница, Монастырь','Ночь в Вади-Раме','Каньон Муджиб','Мёртвое море','Джераш']::text[], 'Семь ночей: отели в Аммане и Петре, лагерь в Вади-Раме.', 'Микроавтобус, джипы в пустыне.', 'Завтраки, ужины.', ARRAY['Размещение: 7 ночей','Завтраки и ужины','Jordan Pass (по возможности)','Гид']::text[], ARRAY['Авиабилеты','Обеды','Страховка']::text[], ARRAY['Умение ходить по лестницам']::text[], ARRAY['Удобная обувь','Шарф','Купальник']::text[], ARRAY['Муджиб закрыт в холодный сезон','Жара летом']::text[], 'Не подтверждено.', ARRAY['Любителям истории','Парам']::text[], ARRAY['Людям с проблемами ног']::text[], ARRAY['Малая группа','Ночь в пустыне']::text[], 'yusuf', 'standard-demo', 'jo-1', ARRAY['jo-2','jo-3']::text[], ARRAY['Иордания','Петра','пустыня']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('kamchatka-volcanoes', 'Камчатка: вулканы, медведи и горячие источники', 'ru', 'Петропавловск-Камчатский и южная Камчатка', 'expedition', 'small_group', FALSE, 9, 8, 'Петропавловск-Камчатский', 'Петропавловск-Камчатский', 276000, 'RUB', 41000, ARRAY[7,8,9]::smallint[], 'Июль — начало сентября', 'Снег на высоких маршрутах сходит к июлю. Рыба идёт на нерест в июле — сентябре, и в это время можно наблюдать медведей. С сентября резко холодает.', 4, 8, 3, 'Восхождение на Авачинский вулкан (около 2 750 м) и дни по 5–8 часов. Погода меняется быстро, вертолётные участки зависят от окон.', NULL, 'Девять дней на краю материка: вулканы, источники и дикая природа.', 'Экспедиция по югу Камчатки для тех, кто готов к переменчивой погоде. Мы поднимаемся на вулкан, купаемся в источниках у подножия Мутновской сопки, заходим в Налычево и по возможности летим на вертолёте в Долину гейзеров. Порядок дней зависит от погодных окон, поэтому в программе есть запасной день.', ARRAY['Восхождение на Авачинский вулкан','Мутновский вулкан и фумаролы','Источники Налычево','Долина гейзеров (вертолёт, по погоде)','Наблюдение за медведями (в сезон)']::text[], 'Семь ночей в гостиницах и базах отдыха, одна ночь в палатке или в домике на маршруте.', 'Внедорожники, вертолёт (по возможности), пешие участки.', 'Завтраки, ужины, на маршрутах — сухие пайки и горячая еда с кухни.', ARRAY['Размещение: 8 ночей','Питание','Транспорт','Гид','Вертолёт (при возможности)']::text[], ARRAY['Авиабилеты','Страховка','Личное снаряжение']::text[], ARRAY['Опыт горных прогулок','Хорошая физическая форма']::text[], ARRAY['Горные ботинки','Дождевик','Тёплые слои','Шапка','Перчатки','Средство от медведей (выдаёт гид)']::text[], ARRAY['Вертолёт зависит от погоды','Сроки сезона ограничены','Возможны задержки рейсов']::text[], 'Не подтверждено: часть районов требует разрешений.', ARRAY['Любителям вулканов','Фотографам']::text[], ARRAY['Тем, кто не готов к непогоде']::text[], ARRAY['Малая группа','Вертолёт','Источники']::text[], 'igor', 'standard-demo', 'kam-1', ARRAY['kam-2','kam-3']::text[], ARRAY['Камчатка','вулканы']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('korea-seoul-jeju', 'Южная Корея: Сеул, горы Сораксан и остров Чеджу', 'kr', 'Сеул — Сораксан — Чеджу', 'culture', 'small_group', FALSE, 9, 8, 'Сеул', 'Чеджу', 164000, 'RUB', 25000, ARRAY[4,5,9,10,11]::smallint[], 'Апрель — май и сентябрь — ноябрь', 'Весной цветёт сакура, осенью горы красные. Летом жарко, влажно и идут дожди.', 4, 10, 2, 'Прогулки по 3–5 часов, подъёмы по лестницам на гору Сорак. Подходит любителям активного отдыха.', NULL, 'Девять дней Кореи: дворцы Сеула, горы Сораксан и вулканический остров Чеджу.', 'Маршрут для тех, кто хочет увидеть современную и традиционную Корею. Сеул со дворцами и рынками, национальный парк Сораксан с храмом и водопадами, затем Чеджу: подъём на кратер Сонсан Ильчульбон, рынки и деревня хэнё — женщин-ныряльщиц.', ARRAY['Дворец Кёнбоккун','Деревня ханок Букчон','Национальный парк Сораксан','Кратер Сонсан Ильчульбон','Хэнё — женщины-ныряльщицы']::text[], 'Восемь ночей в отелях и гостевых домах.', 'Поезда KTX, местные автобусы, перелёт Сеул — Чеджу.', 'Завтраки, часть ужинов.', ARRAY['Размещение: 8 ночей','Завтраки','Перелёты','Гид']::text[], ARRAY['Авиабилеты','Обеды','Страховка']::text[], ARRAY['Умение ходить 3–5 часов']::text[], ARRAY['Удобная обувь','Дождевик']::text[], ARRAY['Погода в горах переменчива']::text[], 'Не подтверждено.', ARRAY['Любителям культуры','Парам']::text[], ARRAY['Тем, кто не любит острую еду']::text[], ARRAY['Малая группа','Кухня']::text[], 'jisoo', 'standard-demo', 'kr-1', ARRAY['kr-2','kr-3']::text[], ARRAY['Корея','Сеул','Чеджу']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('kyoto-tea', 'Киото: чай, храмы и мастерские ремесленников', 'jp', 'Киото и Нара, Кансай', 'culture', 'small_group', TRUE, 8, 7, 'Аэропорт Кансай', 'Аэропорт Кансай', 189000, 'RUB', 28000, ARRAY[3,4,10,11]::smallint[], 'Конец марта — начало апреля (сакура) и конец октября — ноябрь (момидзи)', 'В сезон сакуры и красных клёнов поток туристов выше, поэтому мы заранее планируем утренние посещения. Лето жаркое и влажное.', 4, 8, 1, 'Прогулки по 4–6 часов в день по ровной местности, много лестниц в храмах. Подходит большинству путешественников.', NULL, 'Старая Япония глазами местного жителя: чайная церемония, мастерские, сады и ночь в рёкане.', 'Маршрут для тех, кто хочет понять Киото, а не просто осмотреть храмы. Утром идём в места, куда не доходят автобусные группы, днём заходим в мастерские, вечером остаёмся в небольших кварталах. Один день отведён на Нару и олений парк, один — на ночь в горном рёкане с онсэном.', ARRAY['Чайная церемония в доме-мачия','Мастер-класс по керамике в районе Киёмидзу','Фусими Инари на рассвете','Бамбуковая роща Арасияма до открытия','Ночь в рёкане с онсэном и ужином кайсэки']::text[], 'Шесть ночей в отеле в центре Киото (двухместные номера), одна ночь в традиционном рёкане в Курама (японские комнаты на татами, футоны).', 'Поезда JR и частные линии, такси для переездов с багажом. Багаж можно отправить в следующий отель курьерской службой такюбин.', 'Завтраки, три ужина (в том числе кайсэки в рёкане). Обеды оплачиваются отдельно.', ARRAY['Размещение: 7 ночей','Завтраки и 3 ужина','Гид-историк','Все входы и мастер-классы по программе','Проездной на поезда в регионе']::text[], ARRAY['Авиабилеты','Обеды','Личные расходы','Страховка']::text[], ARRAY['Умение подниматься по лестницам: в Фусими Инари около 1 000 ступеней','Готовность снимать обувь и соблюдать правила этикета']::text[], ARRAY['Удобная обувь, которую легко снимать','Небольшой рюкзак','Накидка от дождя','Наличные йены (карты принимают не везде)']::text[], ARRAY['Некоторые мастерские принимают только небольшие группы','В сезон сакуры возможны очереди и закрытые зоны','Футон в рёкане не подойдёт людям с серьёзными проблемами со спиной']::text[], 'Не подтверждено: условия въезда в Японию для граждан РФ необходимо проверять заранее у консульства.', ARRAY['Любителям культуры и неспешных прогулок','Тем, кто хочет увидеть ремёсла','Парам и путешествующим в одиночку']::text[], ARRAY['Тем, кому нужен активный отдых и ночная жизнь','Людям с ограниченной подвижностью (лестницы)']::text[], ARRAY['Группа до 8 человек','Встречи с мастерами','Утренние посещения без толп','Ночь в рёкане']::text[], 'kenji', 'standard-demo', 'kyoto', ARRAY['japan','fuji']::text[], ARRAY['культура','ремёсла','чайная церемония','Япония']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('maldives-snorkel', 'Мальдивы: острова местных жителей и снорклинг', 'mv', 'Южный Ари', 'beach', 'small_group', FALSE, 8, 7, 'Аэропорт Мале', 'Аэропорт Мале', 148000, 'RUB', 22000, ARRAY[11,12,1,2,3,4]::smallint[], 'С ноября по апрель (сухой сезон)', 'В сезон дождей море неспокойное, видимость под водой хуже. Китовых акул можно встретить круглый год, но не гарантированно.', 4, 12, 1, 'Пляж и снорклинг. Нужно уметь плавать, нагрузка минимальна.', NULL, 'Вместо курортных островов — гестхаусы на островах местных жителей, снорклинг и семейная кухня.', 'Неделя на южном Ари: проживание в гестхаусах, ежедневный снорклинг с лодки, выход к китовым акулам и скатам манта. Остров местный, поэтому алкоголя нет, пляж для купания выделен. Подойдёт тем, кто хочет Мальдивы без курортных цен.', ARRAY['Снорклинг с китовой акулой (при встрече)','Гестхаусы на местных островах','Закат на песчаной отмели','Ужин на пляже']::text[], 'Семь ночей в гестхаусах на местном острове (двухместные номера с кондиционером).', 'Паром или катер Мале — остров, лодки для снорклинга.', 'Полупансион (завтраки и ужины).', ARRAY['Размещение: 7 ночей','Полупансион','Снаряжение для снорклинга','Трансферы катерами','Гид']::text[], ARRAY['Авиабилеты','Обеды','Алкоголь (на местных островах недоступен)','Страховка']::text[], ARRAY['Умение плавать','Согласие соблюдать местные правила одежды на острове']::text[], ARRAY['Лёгкая одежда','Купальник для отведённого пляжа','Защитный крем','Рашгард (по желанию)']::text[], ARRAY['На местных островах нет алкоголя','Одежда в деревне должна быть закрытой','Встреча с китовыми акулами не гарантируется']::text[], 'Не подтверждено: правила въезда проверяются менеджером.', ARRAY['Тем, кто хочет море без курортных цен','Парам и друзьям','Семьям с детьми-подростками']::text[], ARRAY['Тем, кому нужна роскошь курортного отеля','Тем, кто ожидает вечеринок и алкоголя']::text[], ARRAY['Островная жизнь','Снорклинг ежедневно','Небольшая группа']::text[], 'omar', 'standard-demo', 'beach', ARRAY['bali','dubai']::text[], ARRAY['Мальдивы','снорклинг','острова']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('mongolia-nomads-gobi', 'Монголия: кочевники, степь и пустыня Гоби', 'mn', 'Улан-Батор — Хархорин — Гоби', 'expedition', 'small_group', FALSE, 12, 11, 'Улан-Батор', 'Улан-Батор', 238000, 'RUB', 36000, ARRAY[6,7,8,9]::smallint[], 'Июнь — сентябрь', 'Июль — фестиваль Надом. Зимой очень холодно, ночью −30 °C, поэтому лагеря закрыты.', 4, 10, 2, 'Длинные переезды по бездорожью, простые условия. Пеших нагрузок немного.', NULL, 'Двенадцать дней среди юрт, табунов и дюн.', 'Экспедиционный маршрут по Монголии: от столицы к древней столице Хархорин и водопаду Орхон, затем перелёт в Южную Гоби. Мы живём в юртах и в семьях кочевников, помогаем с лошадьми и пробуем молочные продукты. Условия простые: душ ограничен.', ARRAY['Хархорин и монастырь Эрдэнэ-Дзу','Водопад Улаан-Цутгалан','Дюны Хонгорын-Элс','Пылающие скалы Баянзаг','Семьи кочевников']::text[], 'Юрты в лагерях, семьи, отель в Улан-Баторе.', 'Джипы, внутренний перелёт.', 'Полный пансион.', ARRAY['Размещение: 11 ночей','Питание','Транспорт','Гид']::text[], ARRAY['Авиабилеты','Виза','Страховка']::text[], ARRAY['Готовность к простым условиям']::text[], ARRAY['Тёплая одежда','Дождевик']::text[], ARRAY['Связь ограничена']::text[], 'Не подтверждено.', ARRAY['Любителям экспедиций']::text[], ARRAY['Тем, кому нужен комфорт']::text[], ARRAY['Жизнь кочевников']::text[], 'temuulen', 'standard-demo', 'mn-1', ARRAY['mn-2','mn-3']::text[], ARRAY['Монголия','Гоби']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('morocco-sahara-medina', 'Марокко: медины, ущелья и ночь в Сахаре', 'ma', 'Марракеш — Атлас — Мерзуга — Фес — Шефшауэн', 'culture', 'small_group', FALSE, 10, 9, 'Марракеш', 'Фес', 124000, 'RUB', 19000, ARRAY[3,4,5,10,11]::smallint[], 'Март — май и октябрь — ноябрь', 'Летом в пустыне и в Марракеше слишком жарко, зимой по ночам холодно и бывает снег в Атласе.', 4, 12, 2, 'Длинные переезды на автомобиле, прогулки по 2–4 часа, поездка на верблюде.', NULL, 'Десять дней по Марокко: медины, ущелья Атласа, ночь в пустыне и голубой Шефшауэн.', 'Маршрут из Марракеша в Фес с остановками в Атласе, у Ait Benhaddou и в долине Дадес. Ночь в лагере у дюн Эрг-Шебби, затем Фес с кожевенными мастерскими и голубой Шефшауэн. Живём в риадах, едим домашнюю кухню и покупаем у ремесленников.', ARRAY['Площадь Джемаа-эль-Фна','Ait Benhaddou','Ущелья Тодра','Ночь у дюн Эрг-Шебби','Медина Феса','Голубой Шефшауэн']::text[], 'Девять ночей в риадах и гестхаусах (двухместные номера), одна ночь в лагере в пустыне (палатки с кроватями).', 'Микроавтобус с водителем, верблюды, внедорожники в Сахаре.', 'Завтраки, ужины (кроме одного вечера).', ARRAY['Размещение: 9 ночей','Завтраки и ужины','Транспорт','Гид']::text[], ARRAY['Авиабилеты','Обеды','Страховка']::text[], ARRAY['Умение сидеть на верблюде']::text[], ARRAY['Лёгкая одежда','Закрытые плечи и колени','Тёплая куртка на ночь в пустыне','Шарф']::text[], ARRAY['Лагерь в пустыне простой','Торговцы активны','Порядок дней зависит от погоды']::text[], 'Не подтверждено.', ARRAY['Любителям медин','Парам']::text[], ARRAY['Тем, кто не любит жару']::text[], ARRAY['Небольшие риады','Ночь в Сахаре']::text[], 'yusuf', 'standard-demo', 'ma-1', ARRAY['ma-2','ma-3','ma-4']::text[], ARRAY['Марокко','Сахара','медины']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('nepal-annapurna-base-camp', 'Непал: базовый лагерь Аннапурны и закат на Пун-Хилл', 'np', 'Покхара — Аннапурна — Катманду', 'trek', 'small_group', FALSE, 14, 13, 'Катманду', 'Катманду', 189000, 'RUB', 28000, ARRAY[3,4,5,10,11]::smallint[], 'Март — май и октябрь — ноябрь', 'Весной цветёт рододендрон, осенью небо чище всего. В декабре — феврале на высоте холодно и возможен снег, летом идут муссонные дожди.', 4, 10, 3, 'Семь-восемь дней треккинга по 5–8 часов, набор высоты до 4 130 м. Длинные спуски и подъёмы по каменным ступеням. Нужна хорошая подготовка и готовность к простым условиям.', NULL, 'Четырнадцать дней через рододендроновые леса и ледниковые долины к базовому лагерю Аннапурны.', 'Классический треккинг по Санктуарию Аннапурны с ночёвками в чайных домиках, закатом на Пун-Хилл и рассветом у базового лагеря на высоте 4 130 м. Начинаем и заканчиваем в Катманду, несколько дней отводим на акклиматизацию и знакомство со страной. Гид-шерпа следит за самочувствием группы и корректирует график.', ARRAY['Рассвет на Пун-Хилл (3 210 м)','Деревни гурунгов Гандрук и Чхомронг','Ночёвка в чайных домиках','Базовый лагерь Аннапурны (4 130 м)','Горячие источники Джину']::text[], 'Четыре ночи в отелях Катманду и Покхары, восемь ночей в чайных домиках на маршруте (простые комнаты на 2–4 человека, туалеты и душ — общие, горячий душ может быть платным).', 'Автомобили и местные автобусы, перелёты Катманду — Покхара (или переезд на микроавтобусе), далее пешком.', 'Завтраки в отелях, в чайных домиках — завтраки и ужины включены (вегетарианское меню), обеды на тропе оплачиваются отдельно.', ARRAY['Размещение: 13 ночей','Разрешения на треккинг','Гид-шерпа и носильщики (один на двоих)','Питание на маршруте (завтраки, ужины)','Трансферы по программе']::text[], ARRAY['Международные перелёты','Виза','Обеды на маршруте','Личное снаряжение','Страховка с покрытием высот до 4 500 м','Чаевые']::text[], ARRAY['Опыт многодневных походов','Хорошая физическая форма','Страховка, покрывающая эвакуацию на высоте']::text[], ARRAY['Треккинговые ботинки','Спальный мешок (комфорт до −10 °C, можно взять в аренду)','Куртка пуховая','Треккинговые палки','Налобный фонарь','Таблетки для очистки воды','Солнцезащитные очки категории 3']::text[], ARRAY['Горная болезнь возможна, гид может остановить подъём','Погода и тропы в сезон дождей небезопасны','Связь и интернет в чайных домиках ограничены и платные']::text[], 'Не подтверждено: виза в Непал и разрешения на треккинг уточняются менеджером.', ARRAY['Опытным путешественникам','Тем, кто хочет увидеть Гималаи']::text[], ARRAY['Тем, кто боится высоты','Людям с болезнями сердца и лёгких без консультации врача']::text[], ARRAY['Постепенный набор высоты','Гид-шерпа','Малая группа','Ночёвки в деревнях гурунгов']::text[], 'tashi', 'standard-demo', 'np-1', ARRAY['np-2','np-3','np-4']::text[], ARRAY['Непал','Гималаи','Аннапурна','треккинг']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('newzealand-south-island', 'Новая Зеландия: Южный остров на колёсах', 'nz', 'Крайстчерч — Текапо — Квинстаун — Милфорд-Саунд', 'road', 'small_group', FALSE, 14, 13, 'Крайстчерч', 'Крайстчерч', 296000, 'RUB', 44000, ARRAY[11,12,1,2,3]::smallint[], 'Ноябрь — март (лето в южном полушарии)', 'Летом дни длинные, а сезон — самый востребованный, жильё лучше бронировать заранее. Зимой часть дорог закрывается снегом, а Милфорд-Саунд посещают реже.', 4, 6, 1, 'Прогулки по 1–4 часа, в основном по ухоженным тропам. Переезды по 3–5 часов.', NULL, 'Четырнадцать дней на колёсах по Южному острову: озёра, горы, фьорды и ледники.', 'Круговой маршрут из Крайстчерча по самым красивым участкам Южного острова. Мы выбираем короткие прогулки, чтобы успеть и остановиться у озера, и посмотреть на звёзды в заповеднике тёмного неба у Текапо. Едем на фургоне или минивэне на 4–6 человек, ночуем в кемпингах и мотелях.', ARRAY['Церковь Доброго Пастыря на озере Текапо','Долина Хукер и гора Аораки (Кука)','Квинстаун и озеро Вакатипу','Круиз по Милфорд-Саунду','Ледники Фокс и Франц-Йозеф','Перевал Артура']::text[], 'Смесь кемпингов (6–7 ночей) и мотелей (6 ночей).', 'Фургон или минивэн на 4–6 человек, два водителя.', 'Завтраки и ужины на общей кухне, обеды самостоятельно.', ARRAY['Размещение: 13 ночей','Автомобиль','Бензин','Гид']::text[], ARRAY['Авиабилеты','Виза','Страховка','Активности']::text[], ARRAY['Права на вождение']::text[], ARRAY['Дождевик','Тёплый слой','Удобная обувь']::text[], ARRAY['Ограничения левостороннего движения','Погода меняется']::text[], 'Не подтверждено.', ARRAY['Парам','Друзьям']::text[], ARRAY['Тем, кто не любит ездить']::text[], ARRAY['Малая группа','Свобода маршрута']::text[], 'liam', 'standard-demo', 'nz-1', ARRAY['nz-2','nz-3']::text[], ARRAY['Новая Зеландия','роуд-трип']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('norway-lofoten', 'Лофотены: вершины, рыбацкие деревни и северный свет', 'no', 'Лофотенские острова', 'photo', 'small_group', FALSE, 8, 7, 'Свольвер', 'Свольвер', 198000, 'RUB', 30000, ARRAY[6,7,8,9]::smallint[], 'Июнь — сентябрь', 'В июне и июле солнце не заходит (полуночное солнце). С конца августа возвращаются тёмные ночи и возможно северное сияние. В июле — августе больше всего туристов.', 4, 8, 2, 'Прогулки по 3–6 часов, короткие крутые подъёмы (Рейнебринген, Рюттен). Тропы каменистые и скользкие после дождя.', NULL, 'Восемь дней среди островов, острых вершин и красных рыбацких хижин. Лёгкие подъёмы и съёмка в северном свете.', 'Восемь дней на архипелаге за Полярным кругом. Днём — небольшие восхождения на пики над фьордами, вечером — съёмка в тёплом свете. Мы живём в рорбу (рыбацких хижинах) и едим местную рыбу, а гид из Свольвера знает, куда идти по прогнозу погоды. Фотографу-любителю этого достаточно, чтобы вернуться с сильными кадрами.', ARRAY['Подъём на Рейнебринген над Рейне','Пляж Квалвика и пик Рюттен','Хамнёй и Нусфьорд на рассвете','Футбольное поле Хеннингсвер','Морская прогулка по Тролльфьорду']::text[], 'Семь ночей в рорбу или небольших гостевых домах (рыбацкие домики с кухней, душем и двух-четырёхместные комнаты).', 'Минивэн с водителем-гидом, мелкие лодки, местные паромы (если требуется).', 'Завтраки, ужины в ресторанах, обеды самостоятельно.', ARRAY['Размещение: 7 ночей','Завтраки и ужины','Гид','Трансферы','Лодка по Тролльфьорду']::text[], ARRAY['Авиабилеты','Обеды','Страховка']::text[], ARRAY['Умение ходить по скользким тропам 4–6 часов','Желание фотографировать']::text[], ARRAY['Дождевик','Треккинговые ботинки','Штатив','Тёплые слои','Репеллент (летом)']::text[], ARRAY['Погода меняется быстро','Часть троп закрыта для защиты растительности','В пик сезона гестхаусы требуют бронирования заранее']::text[], 'Не подтверждено: шенгенская виза.', ARRAY['Фотографам','Любителям лёгких восхождений']::text[], ARRAY['Тем, кто боится высоты на узких тропах']::text[], ARRAY['Малая группа','Рорбу','Фотографии при полуночном солнце']::text[], 'eirik', 'standard-demo', 'no-1', ARRAY['no-2','no-3']::text[], ARRAY['Норвегия','Лофотены','фототур']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('peru-salkantay', 'Перу: тропа Салкантай и Мачу-Пикчу', 'pe', 'Куско — Священная долина — Салкантай — Мачу-Пикчу', 'trek', 'small_group', FALSE, 10, 9, 'Куско', 'Куско', 214000, 'RUB', 32000, ARRAY[5,6,7,8,9]::smallint[], 'Май — сентябрь (сухой сезон)', 'С декабря по март идут дожди, тропа Салкантай может быть закрыта. Июнь — август — самые холодные ночи, но самое ясное небо.', 4, 10, 3, 'Четыре дня по горным тропам до 7–8 часов, перевал на высоте 4 630 м. Нужна акклиматизация и хорошая физическая форма.', NULL, 'Десять дней в Андах: Куско, Священная долина, тропа Салкантай и Мачу-Пикчу.', 'Альтернатива классической Инка-трейл, где нет лимита по разрешениям. Первые три дня — акклиматизация: Куско и Священная долина. Затем четыре дня треккинга через лагуну Умантай, перевал Салкантай и тропический лес до Агуас-Кальентес. Мачу-Пикчу — на рассвете. Мы идём с поварами и носильщиками из местных деревень.', ARRAY['Озеро Умантай','Перевал Салкантай (4 630 м)','Кофейные плантации в лесу','Мачу-Пикчу на рассвете','Священная долина']::text[], 'Три ночи в отелях Куско и Священной долины, три ночи в палатках, одна ночь в Агуас-Кальентес, три ночи в Куско.', 'Микроавтобусы, лошади для багажа (на тропе), поезд Агуас-Кальентес — Ольянтайтамбо.', 'Завтраки, обеды и ужины на тропе (повар), в городах — завтраки.', ARRAY['Размещение: 9 ночей','Палатки и повар','Носильщики','Гид','Входные билеты в Мачу-Пикчу']::text[], ARRAY['Авиабилеты','Обеды в городах','Страховка с высотой до 5 000 м']::text[], ARRAY['Опыт многодневных походов','Хорошая физическая форма']::text[], ARRAY['Спальный мешок','Ботинки','Куртка','Палки','Налобный фонарь']::text[], ARRAY['Горная болезнь возможна','Входы в Мачу-Пикчу ограничены по времени','Тропа зависит от дождей']::text[], 'Не подтверждено.', ARRAY['Опытным ходокам','Любителям истории инков']::text[], ARRAY['Тем, кто плохо переносит высоту','Людям с проблемами сердца']::text[], ARRAY['Нет жёсткой квоты на тропе','Палатки','Малая группа']::text[], 'diego', 'standard-demo', 'pe-1', ARRAY['pe-2','pe-3']::text[], ARRAY['Перу','Мачу-Пикчу','Салкантай']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('portugal-lisbon-douro', 'Португалия: Лиссабон, Порту и долина Дору', 'pt', 'Лиссабон — Порту — Дору', 'gastro', 'small_group', TRUE, 8, 7, 'Лиссабон', 'Порту', 132000, 'RUB', 20000, ARRAY[4,5,6,9,10]::smallint[], 'Апрель — июнь и сентябрь — октябрь', 'Сентябрь — время сбора винограда в долине Дору. Летом очень много туристов.', 4, 10, 1, 'Прогулки по холмистым городам по 3–4 часа. Подходит всем.', NULL, 'Восемь дней кухни, вина и холмистых городов Португалии.', 'Гастро-маршрут по Португалии: паштейш и тасаки в Лиссабоне, поездка в Синтру, Порту с погребами портвейна и два дня в долине Дору. Мы пробуем блюда в небольших семейных ресторанах и встречаемся с виноделами.', ARRAY['Лиссабон: Алфама и трамвай 28','Синтра','Порту: набережная Рибейра','Погреба портвейна','Долина Дору']::text[], 'Три ночи в Лиссабоне, две в Порту, две в долине Дору.', 'Поезда, микроавтобус, лодка.', 'Завтраки, ужины, дегустации.', ARRAY['Размещение: 7 ночей','Завтраки','Дегустации','Гид']::text[], ARRAY['Авиабилеты','Обеды','Страховка']::text[], ARRAY['Нет']::text[], ARRAY['Удобная обувь']::text[], ARRAY['Погода в Порту переменчива']::text[], 'Не подтверждено.', ARRAY['Гурманам']::text[], ARRAY['Тем, кто не любит рыбу']::text[], ARRAY['Малые винодельни']::text[], 'rui', 'standard-demo', 'pt-1', ARRAY['pt-2','pt-3']::text[], ARRAY['Португалия','вино','кухня']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('rajasthan-spice', 'Раджастхан: специи, дворцы и семейные кухни', 'in', 'Дели — Агра — Джайпур — Удайпур', 'gastro', 'small_group', TRUE, 9, 8, 'Дели', 'Удайпур', 96000, 'RUB', 14000, ARRAY[10,11,12,1,2,3]::smallint[], 'С октября по март', 'Летом в Раджастхане температура превышает 40 °C, поэтому выезды запланированы в прохладный сезон.', 4, 10, 1, 'Прогулки по 3–4 часа, длинные переезды на автомобиле и поезде.', NULL, 'Готовим в семейных домах, едим на рынках и смотрим на Тадж-Махал на рассвете.', 'Девять дней по «золотому треугольнику» с гастрономическим уклоном. Утром идём на рынки, днём готовим и осматриваем форты, вечером ужинаем с семьями. Тадж-Махал смотрим на рассвете.', ARRAY['Рынок специй и мастер-класс в Джайпуре','Тадж-Махал на рассвете','Амбер-форт и ступенчатый колодец','Ужин с видом на озеро Пичола в Удайпуре','Завтрак в семье гончаров']::text[], 'Восемь ночей в отелях-хавели (двухместные номера), в Агре и Джайпуре — отели среднего уровня.', 'Минивэн с водителем, поезд Дели — Агра (по возможности), перелёт из Удайпура.', 'Завтраки, ужины. Обеды в рамках мастер-классов.', ARRAY['Размещение: 8 ночей','Завтраки и ужины','Мастер-классы','Транспорт и гид','Входы']::text[], ARRAY['Авиабилеты','Виза','Личные расходы','Страховка']::text[], ARRAY['Умение переносить длительные переезды','Желание пробовать острую еду']::text[], ARRAY['Лёгкая одежда','Закрытые плечи и колени для храмов','Средства для желудка','Антисептик для рук']::text[], ARRAY['Тадж-Махал закрыт по пятницам','Острота блюд регулируется, но не исключается','Возможны проблемы с желудком']::text[], 'Не подтверждено: требуется виза или электронное разрешение, проверяется менеджером.', ARRAY['Гурманам','Парам и друзьям']::text[], ARRAY['Тем, кому нужна западная кухня','Людям с чувствительным желудком']::text[], ARRAY['Мастер-классы','Рассвет у Тадж-Махала','Ночёвки в хавели']::text[], 'priya', 'standard-demo', 'india', ARRAY['dubai','egypt']::text[], ARRAY['гастро','Индия','специи']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('srilanka-tea-ayurveda', 'Шри-Ланка: чайные горы, слоны и аюрведа', 'lk', 'Центр, горы и юг острова', 'retreat', 'small_group', FALSE, 11, 10, 'Коломбо', 'Коломбо', 142000, 'RUB', 21000, ARRAY[12,1,2,3,4]::smallint[], 'Декабрь — апрель', 'В этот период сухо на юге и на западе. Центральные горы прохладны. В мае — сентябре на юге идут муссонные дожди.', 4, 10, 1, 'Прогулки по 2–4 часа, поездка на поезде, сафари. Подходит всем.', NULL, 'Одиннадцать дней среди храмов, чайных гор и океана с днём аюрведы.', 'Маршрут для спокойного путешествия по Шри-Ланке. Культурный треугольник (Сигирия, Дамбулла), храм Зуба Будды в Канди, чайные плантации Нувара-Элия и знаменитая поездка на поезде до Эллы. Затем сафари в Яле и три дня на океане с сеансами аюрведы. Мы живём в небольших гестхаусах и едим домашнюю кухню.', ARRAY['Скала Сигирия','Храм Зуба Будды в Канди','Поезд Канди — Элла','Чайные плантации Нувара-Элия','Сафари в национальном парке Яла']::text[], 'Десять ночей в небольших гестхаусах и отелях (двухместные номера).', 'Микроавтобус с водителем, поезд Нану-Оя — Элла, джип в Яле.', 'Завтраки, ужины.', ARRAY['Размещение: 10 ночей','Завтраки и ужины','Сафари','Поезд','Сеанс аюрведы']::text[], ARRAY['Авиабилеты','Обеды','Страховка']::text[], ARRAY['Нет особых требований']::text[], ARRAY['Лёгкая одежда','Закрытая одежда для храмов','Репеллент']::text[], ARRAY['Поезда могут задерживаться','Встреча с леопардом не гарантируется','Билеты на поезд ограничены']::text[], 'Не подтверждено.', ARRAY['Парам','Одиночным путешественникам','Семьям']::text[], ARRAY['Тем, кто ждёт курортного комфорта']::text[], ARRAY['Спокойный ритм','Разнообразные пейзажи','Аюрведа']::text[], 'sanjaya', 'standard-demo', 'lk-1', ARRAY['lk-2','lk-3','lk-4']::text[], ARRAY['Шри-Ланка','чай','аюрведа']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('tanzania-serengeti', 'Танзания: Серенгети, Нгоронгоро и Тарангире', 'tz', 'Северная Танзания', 'expedition', 'small_group', FALSE, 9, 8, 'Аруша', 'Аруша', 389000, 'RUB', 58000, ARRAY[6,7,8,9,10]::smallint[], 'Июнь — октябрь (сухой сезон)', 'В сухой сезон животных легче найти у водоёмов. Миграция гну в северной Серенгети с июля по октябрь, пересечение реки Мара обычно с августа по сентябрь.', 4, 8, 2, 'Сафари в джипах 5–7 часов в день, пыльные дороги, жара. Прогулки пешком не планируются.', NULL, 'Девять дней сафари: слоны, львы, кратер и бескрайние равнины.', 'Классический северный сафари-круг: Тарангире с баобабами и слонами, озеро Маньяра, кратер Нгоронгоро и несколько дней в Серенгети. Группа до 8 человек в двух внедорожниках с откидной крышей. Гид-сафари объясняет поведение животных и выбирает маршруты по недавним встречам.', ARRAY['Слоны и баобабы Тарангире','Кратер Нгоронгоро','Центральная Серенгети','Миграция гну (по сезону)','Ночи в палаточных лагерях']::text[], 'Восемь ночей в палаточных лагерях и лоджах (двухместные палатки).', 'Внедорожники 4x4, внутренний рейс из Серенгети.', 'Полный пансион на сафари.', ARRAY['Размещение: 8 ночей','Питание','Сафари','Гид']::text[], ARRAY['Авиабилеты','Виза','Прививки','Страховка']::text[], ARRAY['Прививки по требованиям']::text[], ARRAY['Нейтральная одежда','Бинокль','Репеллент']::text[], ARRAY['Животных увидеть не гарантируется','Дороги пыльные']::text[], 'Не подтверждено: уточнить прививки.', ARRAY['Любителям природы','Фотографам']::text[], ARRAY['Людям с проблемами спины']::text[], ARRAY['Малая группа','Миграция']::text[], 'baraka', 'standard-demo', 'tz-1', ARRAY['tz-2','tz-3']::text[], ARRAY['Танзания','сафари']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('thailand-krabi-chiang-mai', 'Таиланд: храмы Чиангмая и острова Краби', 'th', 'Чиангмай и Краби', 'beach', 'small_group', FALSE, 12, 11, 'Чиангмай', 'Краби', 168000, 'RUB', 25000, ARRAY[11,12,1,2,3]::smallint[], 'Ноябрь — март', 'В Чиангмае и на Андаманском побережье это самый сухой сезон. Апрель — жарко, июнь — октябрь — дожди и неспокойное море.', 4, 12, 1, 'Лёгкие прогулки, снорклинг, каяки. Нужно уметь плавать.', NULL, 'Север и юг Таиланда: храмы и этичный слоновий приют в горах, затем пляжи и острова.', 'Двенадцать дней в Таиланде в двух частях. Первая — Чиангмай: храмы, рынки, мастер-класс по кухне и этичный приют для слонов. Вторая — побережье Краби: пляж Рейли, острова и снорклинг. Подходит тем, кто хочет сочетать культуру и пляж.', ARRAY['Храм Дой Сутхеп','Этичный приют для слонов без катания','Мастер-класс по тайской кухне','Каяк и снорклинг у островов','Пляж Рейли и скалы']::text[], 'Пять ночей в Чиангмае (отель), шесть ночей на побережье (отель у моря).', 'Микроавтобус, лодки, перелёт Чиангмай — Краби.', 'Завтраки, часть ужинов.', ARRAY['Размещение: 11 ночей','Завтраки','Приют для слонов','Лодки','Перелёт']::text[], ARRAY['Международные перелёты','Обеды','Страховка']::text[], ARRAY['Умение плавать']::text[], ARRAY['Купальник','Защитный крем','Лёгкая одежда','Закрытая одежда для храмов']::text[], ARRAY['Лодки зависят от волн','Некоторые храмы требуют закрытую одежду']::text[], 'Не подтверждено.', ARRAY['Парам','Друзьям','Семьям']::text[], ARRAY['Тем, кому нужна экстремальная активность']::text[], ARRAY['Культура и пляж','Малая группа']::text[], 'mai', 'standard-demo', 'th-1', ARRAY['th-2','th-3']::text[], ARRAY['Таиланд','острова','храмы']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('turkey-cappadocia-aegean', 'Турция: Стамбул, Каппадокия и Эгейское побережье', 'tr', 'Стамбул — Каппадокия — Эфес — Памуккале', 'culture', 'small_group', TRUE, 9, 8, 'Стамбул', 'Измир', 118000, 'RUB', 18000, ARRAY[4,5,6,9,10]::smallint[], 'Апрель — июнь и сентябрь — октябрь', 'Летом на Эгейском побережье и в Памуккале очень жарко. Зимой в Каппадокии бывает снег, а воздушные шары чаще отменяют из-за ветра.', 4, 12, 1, 'Прогулки по 3–5 часов, много лестниц и неровных дорог в Каппадокии и на раскопках. Подходит большинству путешественников.', NULL, 'Девять дней среди мечетей, пещерных городов и античных руин Турции.', 'Маршрут по трём очень разным частям страны. Два дня в Стамбуле: Айя-София, Босфор и Гранд-базар. Затем Каппадокия с долинами, подземным городом и пещерными отелями. В конце — Эфес и белые террасы Памуккале. Между регионами летаем, чтобы не терять дни на дорогу.', ARRAY['Стамбул: Айя-София, Босфор и Гранд-базар','Прогулка по долине Роз в Каппадокии','Подземный город Деринкую','Эфес без толп','Термальные террасы Памуккале']::text[], 'Два ночи в Стамбуле в бутик-отеле, три ночи в пещерном отеле в Гёреме, две ночи в отеле в Сельчуке и Памуккале, одна ночь в Измире.', 'Микроавтобус с водителем, два внутренних перелёта, паром по Босфору.', 'Завтраки, пять ужинов. Обеды по желанию.', ARRAY['Размещение: 8 ночей','Завтраки и ужины','Гид по Турции','Внутренние перелёты','Входы по программе']::text[], ARRAY['Международные перелёты','Полёт на воздушном шаре (по желанию, не гарантируется)','Обеды','Страховка']::text[], ARRAY['Умение ходить по неровным тропам и лестницам']::text[], ARRAY['Удобная обувь','Лёгкая одежда','Закрытая одежда для мечетей','Шарф для женщин']::text[], ARRAY['Воздушные шары зависят от ветра','Мечети закрыты для туристов во время молитвы','Порядок дней может меняться из-за расписания рейсов']::text[], 'Не подтверждено.', ARRAY['Путешественникам, которые хотят увидеть сразу несколько регионов','Парам и друзьям']::text[], ARRAY['Тем, кому тяжело ходить по лестницам']::text[], ARRAY['Три региона за девять дней','Пещерный отель','Малая группа']::text[], 'aylin', 'standard-demo', 'tr-1', ARRAY['tr-2','tr-3','tr-4']::text[], ARRAY['Турция','Каппадокия','Эфес']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('tuscany-private-friends', 'Тоскана для своей компании: вилла, вино и неспешные дни', 'it', 'Сиена, Кьянти, Валь-д’Орча', 'private', 'private', TRUE, 7, 6, 'Флоренция', 'Флоренция', 164000, 'RUB', 25000, ARRAY[4,5,6,9,10]::smallint[], 'Апрель — июнь и сентябрь — октябрь', 'Сентябрь — октябрь — время сбора винограда и оливок. Летом жарко и людно, зимой многие хозяйства закрыты.', 4, 8, 1, 'Прогулки по холмам по 2–4 часа, полдня на ногах в городах.', NULL, 'Семь дней на вилле: Сиена, Кьянти, Монтальчино и вечера за общим столом.', 'Приватная поездка для друзей или семьи на 4–8 человек. Мы снимаем виллу или агритуризмо в окрестностях Сиены, планируем программу вместе с вами и держим темп, удобный компании. Утром — прогулки, днём — дегустации и мастер-классы, вечером — ужин за одним столом.', ARRAY['Вилла в окрестностях Сиены','Пьяцца дель Кампо','Кьянти и дегустации','Монтальчино и Брунелло','Мастер-класс по пасте']::text[], 'Шесть ночей на вилле или в агритуризмо с бассейном (общие зоны, двух-трёхместные комнаты).', 'Минивэн с водителем для группы, собственный водитель на выезды.', 'Завтраки, пять ужинов. Обеды по желанию.', ARRAY['Размещение: 6 ночей','Завтраки и ужины','Трансферы','Дегустации','Мастер-класс']::text[], ARRAY['Авиабилеты','Обеды','Страховка','Чаевые']::text[], ARRAY['Группа 4–8 человек']::text[], ARRAY['Удобная обувь','Лёгкая одежда']::text[], ARRAY['Приватный состав согласуется заранее','Вино — по желанию']::text[], 'Не подтверждено.', ARRAY['Друзьям','Семьям','Парам']::text[], ARRAY['Тем, кто хочет быстрой программы']::text[], ARRAY['Своя компания','Вилла','Программа под вас']::text[], 'chiara', 'standard-demo', 'tus-1', ARRAY['tus-2','tus-3']::text[], ARRAY['Италия','Тоскана','вино']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('usa-route66', 'Route 66: Чикаго — Санта-Моника', 'us', 'Через восемь штатов, около 3 900 км', 'road', 'small_group', FALSE, 14, 13, 'Чикаго', 'Санта-Моника', 238000, 'RUB', 36000, ARRAY[5,6,9,10]::smallint[], 'Май — июнь и сентябрь — октябрь', 'Летом на юго-западе жара выше 40 °C, зимой на севере возможны снегопады и закрытые участки.', 4, 6, 1, 'Основная нагрузка — вождение 4–6 часов в день и короткие прогулки. Подходит всем, кто комфортно чувствует себя в дороге.', NULL, 'Знаменитая трасса: винтажные мотели, придорожные закусочные и закат на пирсе Санта-Моники.', 'Четырнадцать дней по исторической трассе Route 66 от Чикаго до Санта-Моники. Мы не пытаемся проехать каждую милю, а выбираем участки, где сохранились старые мотели, закусочные и вывески. Ночуем в мотелях 1950-х годов, едим там, где едят местные, и оставляем время на остановки для съёмки.', ARRAY['Начало трассы в Чикаго и Cloud Gate','Арка Гейтвей и джаз в Сент-Луисе','Кадиллак-ранчо в Амарилло','Неоновые вывески в Тукумкари','Национальный парк Окаменелый лес','Пирс Санта-Моники на закате']::text[], 'Тринадцать ночей в мотелях и небольших отелях вдоль трассы (двухместные номера). В Окаменелом лесу — ночь в мотеле Wigwam.', 'Минивэн на 4–6 человек, два водителя, бензин и парковки включены. Заправки по маршруту.', 'Завтраки в мотелях и кафе, обеды и ужины в придорожных заведениях оплачиваются отдельно.', ARRAY['Размещение: 13 ночей','Автомобиль и бензин','Гид-организатор','Входы в национальные парки по маршруту']::text[], ARRAY['Авиабилеты','Обеды и ужины','Виза или электронное разрешение','Страховка']::text[], ARRAY['Права на вождение (международные права могут быть нужны)','Готовность ехать 4–6 часов в день']::text[], ARRAY['Удобная обувь','Солнцезащитные очки','Лёгкая и тёплая одежда','Камера или смартфон']::text[], ARRAY['Погода влияет на порядок дней','Некоторые мотели — винтажные, с простыми условиями','Дорога в Нью-Мексико и Аризоне может быть закрыта из-за ремонта']::text[], 'Не подтверждено: условия въезда в США проверяются менеджером.', ARRAY['Любителям истории американских дорог','Друзьям и парам']::text[], ARRAY['Тем, кто не любит долгие переезды','Тем, кому важны современные отели']::text[], ARRAY['Классический маршрут','Мотели 50-х','Неспешные остановки']::text[], 'dan', 'standard-demo', 'usa2', ARRAY['usa','dawn']::text[], ARRAY['США','Route 66','роуд-трип']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('usa-southwest', 'Юго-Запад США: роуд-трип по национальным паркам', 'us', 'Юта — Аризона — Невада', 'road', 'small_group', FALSE, 12, 11, 'Лас-Вегас', 'Лас-Вегас', 214000, 'RUB', 32000, ARRAY[5,6,9,10]::smallint[], 'Май — июнь и сентябрь — октябрь', 'Летом в каньонах очень жарко (до 40 °C и выше), зимой часть дорог и троп закрыта. В межсезонье температура комфортна.', 4, 6, 2, 'Короткие прогулки по 2–5 часов, один долгий день в Брайс-каньоне или Арчес. Переезды по 3–5 часов.', NULL, 'Двенадцать дней в автодоме и мотелях по каньонам, пустыне и закатам.', 'Круговой маршрут из Лас-Вегаса по паркам Юты, Аризоны и обратно. Мы едим вместе, ночуем в кемпингах и мотелях и выбираем остановки по свету. Группа ездит в одной машине, водители меняются.', ARRAY['Зайон, Брайс и Арчес','Монумент-Вэлли на закате','Антилоп-каньон и Хорсшу-Бенд','Гранд-Каньон, Южная кромка','Участок Route 66 в Аризоне']::text[], 'Смесь кемпингов (4–5 ночей) и мотелей (6 ночей). В кемпингах палатки или спальные места в автодоме.', 'Автомобиль или автодом на 4–6 человек, 2 водителя, бензин и парковки включены.', 'Совместная кухня и ужины, завтраки готовим сами, обеды в дороге.', ARRAY['Аренда автомобиля или автодома','Бензин и парковки','Входы в национальные парки','Гид-организатор','Продукты для общей кухни']::text[], ARRAY['Авиабилеты','Рестораны','Страховка','Виза или ESTA']::text[], ARRAY['Водительское удостоверение с правом управления (международные права могут потребоваться)','Готовность жить в кемпинге']::text[], ARRAY['Удобная обувь','Головной убор','Бутылка для воды 2 л','Спальный мешок (по желанию)']::text[], ARRAY['Летом в каньонах очень жарко','Некоторые тропы требуют предварительного разрешения','Порядок дней может меняться из-за погоды']::text[], 'Не подтверждено: условия въезда в США и тип визы проверяются заранее.', ARRAY['Любителям дорог и пейзажей','Парам и друзьям']::text[], ARRAY['Тем, кто не любит длинные переезды','Тем, кто не готов к кемпингу']::text[], ARRAY['Небольшая группа','Общая кухня','Закаты и рассветы','Дорожная свобода']::text[], 'dan', 'standard-demo', 'usa', ARRAY['usa2','dawn']::text[], ARRAY['роуд-трип','США','каньоны']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb),
  ('vietnam-ha-giang-hoi-an', 'Вьетнам: дороги Ха Занга, бухта Лан Ха и Хойан', 'vn', 'Ханой — Ха Занг — Лан Ха — Хойан — Хюэ — Хошимин', 'adventure', 'small_group', FALSE, 14, 13, 'Ханой', 'Хошимин', 175000, 'RUB', 26000, ARRAY[3,4,5,9,10,11]::smallint[], 'Март — май и сентябрь — ноябрь', 'Север в декабре — феврале холодный и сырой, в июне — августе жарко и возможны ливни. Ха Занг красивее всего в сентябре — ноябре, когда созревает рис.', 4, 10, 2, 'Дороги в горах длинные и извилистые (3–6 часов в день), прогулки короткие. Нужна устойчивость к укачиванию.', NULL, 'Четырнадцать дней по Вьетнаму: от горных дорог и ночи на бухте до старого города Хойан.', 'Маршрут для тех, кто хочет увидеть Вьетнам вблизи. Начинаем с еды и кварталов Ханоя, затем три дня по петле Ха Занг: перевал Ма Пи Ленг, плато Донг Ван и ущелье реки Ньо Кэ. После — ночь на лодке в бухте Лан Ха, прилёт в Дананг и Хойан с мастер-классом по кухне. В конце — Хюэ и дельта Меконга.', ARRAY['Петля Ха Занг и перевал Ма Пи Ленг','Ужин из уличной еды в Ханое','Ночь на лодке в бухте Лан Ха','Мастер-класс по кухне в Хойане','Хюэ и перевал Хайван','Дельта Меконга']::text[], 'Двенадцать ночей в отелях и гестхаусах (двухместные номера), одна ночь на лодке в бухте Лан Ха (каюта).', 'Микроавтобусы, внутренние рейсы (Ханой — Дананг, Хюэ — Хошимин), лодки.', 'Завтраки включены. Ужины — совместные, обеды самостоятельно.', ARRAY['Размещение: 13 ночей','Завтраки','Внутренние перелёты','Круиз по Лан Ха','Гид']::text[], ARRAY['Международные перелёты','Обеды и ужины','Виза','Страховка']::text[], ARRAY['Устойчивость к укачиванию на горных дорогах']::text[], ARRAY['Лёгкая одежда','Дождевик','Репеллент','Удобная обувь']::text[], ARRAY['Дороги в горах могут быть закрыты после дождей','Лодки в бухте зависят от погоды']::text[], 'Не подтверждено.', ARRAY['Любителям Азии','Тем, кто любит уличную еду']::text[], ARRAY['Тем, кто не любит долгие переезды','Тем, кто плохо переносит влажность']::text[], ARRAY['Малая группа','Кухня разных регионов','Горные дороги и побережье']::text[], 'mai', 'standard-demo', 'vn-1', ARRAY['vn-2','vn-3','vn-4']::text[], ARRAY['Вьетнам','Ха Занг','Хойан','еда']::text[], TRUE, '{"price":"demo","departures":"demo","seats":"demo","itinerary":"concept_requires_operator_review","entry_requirements":"unverified"}'::jsonb);
INSERT INTO tour_days (tour_id, day_no, title, places, summary, activities, free_time, unique_experience) VALUES
  ('bali-retreat', 1, 'Прилёт и заселение', ARRAY['Аэропорт Денпасара','Убуд']::text[], 'Встреча в аэропорту Денпасара и трансфер в Убуд (около 1,5 часа). Заселение на вилле среди рисовых полей, приветственный круг с чаем из лемонграсса и ужин с хозяевами.', ARRAY[]::text[], 'Вечер — свободное время.', NULL),
  ('bali-retreat', 2, 'Утренняя практика и Кампухан', ARRAY['Убуд','Кампухан Ридж']::text[], 'Йога на рассвете, завтрак и неспешная прогулка по тропе Кампухан Ридж среди травы.', ARRAY['Йога 75 минут','Прогулка 1,5 часа']::text[], 'После обеда — свободное время.', NULL),
  ('bali-retreat', 3, 'Тирта-Эмпул и Гунунг Кави', ARRAY['Тирта-Эмпул','Гунунг Кави']::text[], 'Храмовая церемония очищения в священных источниках, затем прогулка среди скальных гробниц Гунунг Кави.', ARRAY['Церемония очищения','Прогулка по долине']::text[], NULL, 'Ритуал проходит в традиционной одежде, которую выдают на месте.'),
  ('bali-retreat', 4, 'Кулинарный день', ARRAY['Рынок Убуда','Семейный дом']::text[], 'Утром — рынок, затем мастер-класс по балийской кухне в семейном дворике (бумбу, сате).', ARRAY['Рынок','Мастер-класс']::text[], 'Вторая половина дня — свободное время.', 'Готовим на дровяной печи вместе с хозяйкой.'),
  ('bali-retreat', 5, 'Свободный день', ARRAY['Убуд','Джатилувих']::text[], 'Свободный день для спа, массажа или поездки к рисовым террасам Джатилувих (по желанию).', ARRAY['Спа (по желанию)','Велопрогулка (по желанию)']::text[], 'Весь день свободен.', NULL),
  ('bali-retreat', 6, 'Переезд на Нуса-Пениду', ARRAY['Санур','Нуса-Пенида']::text[], 'Быстрый катер из Санура на Нуса-Пениду (около 40–60 минут). Скалы Келингкинг и пляж у обрыва.', ARRAY['Осмотр скал','Обед на острове']::text[], NULL, 'Вид на обрыв, похожий на силуэт динозавра.'),
  ('bali-retreat', 7, 'Снорклинг', ARRAY['Кристал-Бэй','Манта-Пойнт']::text[], 'Снорклинг в бухте Кристал-Бэй и Манта-Пойнт (скаты манты встречаются не гарантированно).', ARRAY['Снорклинг с лодки']::text[], 'Остаток дня — пляж.', 'Рядом проплывают крупные скаты, если повезёт.'),
  ('bali-retreat', 8, 'Возвращение в Убуд', ARRAY['Нуса-Пенида','Убуд']::text[], 'Скоростной катер обратно на Бали и дорога в Убуд (около 3 часов с катером). Вечером — мягкая йога на закате и ужин на вилле.', ARRAY['Йога на закате','Ужин']::text[], 'Свободный вечер.', NULL),
  ('bali-retreat', 9, 'Закрытие ретрита', ARRAY['Убуд']::text[], 'Утренняя практика, прощальный круг, где каждый делится впечатлениями. Вечером — совместный ужин из блюд, которые мы готовили на мастер-классе.', ARRAY['Практика','Прощальный ужин']::text[], 'День свободен.', NULL),
  ('bali-retreat', 10, 'Отъезд', ARRAY['Убуд','Аэропорт Денпасара']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('bernese-oberland-traverse', 1, 'Интерлакен и Гриндельвальд', ARRAY['Интерлакен','Гриндельвальд']::text[], 'Встреча группы, переезд на поезде по долине в Гриндельвальд. Вечерняя прогулка вдоль реки и разбор маршрута с гидом, проверка снаряжения.', ARRAY['Проверка снаряжения']::text[], 'Свободный вечер.', 'Лунный свет на северной стене Айгера.'),
  ('bernese-oberland-traverse', 2, 'Фирст и Бахальпзее', ARRAY['Фирст','Бахальпзее','Шреккхорн']::text[], 'Подъём канатной дорогой в Фирст и прогулка до озера Бахальпзее на высоте около 2 265 м. На тропе открывается вид на Шреккхорн и Веттерхорн.', ARRAY['Прогулка 4–5 часов','Канатная дорога']::text[], 'Вторая половина дня — свободна.', 'Озеро отражает вершины в безветренную погоду.'),
  ('bernese-oberland-traverse', 3, 'Большая Шайдегг и Кляйне-Шайдегг', ARRAY['Гросс-Шайдегг','Кляйне-Шайдегг']::text[], 'Переход по долине под северной стеной Айгера к перевалу Кляйне-Шайдегг. Набор около 900 м, вид на Айгер, Мёнх и Юнгфрау не закрывается.', ARRAY['Треккинг 6 часов']::text[], NULL, 'Поезда зубчатой железной дороги проходят прямо у тропы.'),
  ('bernese-oberland-traverse', 4, 'Венген и Лаутербруннен', ARRAY['Венген','Штауббах','Лаутербруннен']::text[], 'Спуск через Венген в долину Лаутербруннен, где около 70 водопадов. Остановка у водопада Штауббах и водопадов Трюммельбах.', ARRAY['Прогулка 4–5 часов']::text[], 'Вечером — свободное время.', 'Звук воды между скал.'),
  ('bernese-oberland-traverse', 5, 'Мюррен и Шильтхорн', ARRAY['Гиммельвальд','Мюррен','Шильтхорн']::text[], 'Подъём по склону в Гиммельвальд и Мюррен — деревню без автомобилей. Подъём на Шильтхорн на канатной дороге (по погоде).', ARRAY['Прогулка 3–4 часа','Канатная дорога']::text[], NULL, 'Панорама на сотни вершин.'),
  ('bernese-oberland-traverse', 6, 'Перевал Зефинен-Фурге', ARRAY['Зефинен-Фурге','Гризальп']::text[], 'Самый красивый и длинный день. Подъём через луга к перевалу (около 2 612 м), затем спуск через долину в деревню Гризальп.', ARRAY['Треккинг 7–8 часов']::text[], NULL, 'Одиночество на перевале.'),
  ('bernese-oberland-traverse', 7, 'Перевал Хохтюрли', ARRAY['Хохтюрли','Блюмлисальпхютте']::text[], 'Подъём по скальной тропе к перевалу Хохтюрли (2 778 м) и приюту Блюмлисальп. В конце — ночёвка у ледника.', ARRAY['Треккинг 7–8 часов']::text[], NULL, 'Приют стоит под ледником Блюмлисальп.'),
  ('bernese-oberland-traverse', 8, 'Кандерштег и Эшинензее', ARRAY['Эшинензее','Кандерштег']::text[], 'Спуск к озеру Эшинензее — одному из самых живописных в Альпах, купание по желанию, спуск в Кандерштег.', ARRAY['Треккинг 5 часов']::text[], 'Свободный вечер.', 'Зелёная вода озера.'),
  ('bernese-oberland-traverse', 9, 'Отъезд', ARRAY['Кандерштег','Цюрих']::text[], 'Завтрак и поезд в Цюрих (около 2 часов).', ARRAY[]::text[], 'Время для покупок в Цюрихе.', NULL),
  ('dolomites-lakes', 1, 'Кортина-д’Ампеццо: прибытие', ARRAY['Аэропорт Венеции','Кортина-д’Ампеццо']::text[], 'Встреча в аэропорту Венеции, трансфер (около двух часов пути), заселение, знакомство с группой и разбор маршрута.', ARRAY['Ужин в небольшом ресторане с блюдами региона']::text[], 'Вечерняя прогулка по центру Кортины.', NULL),
  ('dolomites-lakes', 2, 'Озеро Брайес и приют Бьелла', ARRAY['Лаго ди Брайес','Рифуджио Бьелла']::text[], 'Круговая тропа вокруг озера и подъём к приюту Бьелла на высоту около 2 300 м. Дорога от озера идёт через лес на открытые склоны.', ARRAY['Треккинг около 5 часов с остановками','Фотосессия на деревянных лодках у пирса']::text[], 'После спуска — час свободного времени у озера.', 'Утром озеро часто безветренное, и горы отражаются как в зеркале.'),
  ('dolomites-lakes', 3, 'Тре Чиме ди Лаваредо', ARRAY['Рифуджио Ауронцо','Рифуджио Локателли','Форчелла Лаваредо']::text[], 'Классическая круговая тропа вокруг трёх вершин, самого узнаваемого символа Доломитов. Около 10 км, с короткими подъёмами.', ARRAY['Пеший маршрут 5–6 часов','Обед в приюте Локателли']::text[], 'Время для фотографий на перевале.', 'Три зубца меняют цвет по мере движения солнца.'),
  ('dolomites-lakes', 4, 'Озеро Сорапис', ARRAY['Пассо Тре Кроче','Лаго ди Сорапис','Рифуджио Ванделли']::text[], 'Тропа ведёт через лес и каменные осыпи к озеру молочно-бирюзового цвета. На участке перед озером есть тросы и узкие карнизы.', ARRAY['Треккинг 5–6 часов туда и обратно']::text[], 'Купаться не рекомендуется: вода ледяная и озеро находится в охраняемой зоне.', 'Цвет воды зависит от ледниковой взвеси и света.'),
  ('dolomites-lakes', 5, 'Чинкве Торри и приют Нуволау', ARRAY['Чинкве Торри','Рифуджио Нуволау']::text[], 'Переход через скальную группу Чинкве Торри к приюту Нуволау на высоте около 2 575 м. Вокруг — окопы и позиции Первой мировой войны.', ARRAY['Подъём к приюту 3–4 часа','Ночёвка в приюте']::text[], 'Свободный вечер на террасе приюта.', 'Закат над Тофаной в горном приюте. Свет после ухода дневных туристов особенно мягкий.'),
  ('dolomites-lakes', 6, 'Рассвет, Лагадзуой и прощальный ужин', ARRAY['Рифуджио Нуволау','Пассо Фальцарего','Лагадзуой']::text[], 'Рассвет у приюта, спуск и переезд к Лагадзуой. Канатная дорога (при работе) и прогулка по тоннелям Первой мировой с налобным фонарём.', ARRAY['Прогулка по галереям с фонарями','Прощальный ужин в агритуризмо']::text[], 'Вторая половина дня — свободное время в Кортине.', 'Подземные галереи, прорубленные в скале солдатами в 1915–1917 годах.'),
  ('dolomites-lakes', 7, 'Отъезд', ARRAY['Кортина-д’Ампеццо','Аэропорт Венеции']::text[], 'Завтрак и трансфер в аэропорт. Рекомендуем бронировать вылет не раньше второй половины дня.', ARRAY[]::text[], 'Если вылет вечером, можно задержаться в Кортине для покупок.', NULL),
  ('dubai-desert', 1, 'Дубай: Дейра и Бастакия', ARRAY['Дубай-Крик','Бастакия','Рынок специй']::text[], 'Знакомство со старым Дубаем: поездка на абре через бухту, рынок специй и квартал Бастакия с домами с ветряными башнями.', ARRAY['Лодка абра','Прогулка 3 часа']::text[], 'Вечер свободен.', 'Запах шафрана и ладана на рынке.'),
  ('dubai-desert', 2, 'Старый Дубай и Бурдж-Халифа', ARRAY['Рынок золота','Музей Дубая','Бурдж-Халифа']::text[], 'Рынок золота, форт Аль-Фахиди и музей. Вечером — подъём на смотровую площадку Бурдж-Халифа на закате.', ARRAY['Смотровая площадка']::text[], NULL, 'Огни города с высоты.'),
  ('dubai-desert', 3, 'Сафари в пустыне', ARRAY['Пустыня Лахбаб','Лагерь']::text[], 'Выезд на джипах на дюны, остановка на закате. В лагере — ужин, чай и вечер у костра. Ночь в палатке с кроватью.', ARRAY['Джип-сафари','Верблюды']::text[], 'Вечер у костра.', 'Звёзды без городской засветки.'),
  ('dubai-desert', 4, 'Хатта', ARRAY['Хатта','Горы Хаджар','Озеро Хатта']::text[], 'Утреннее возвращение к шоссе и поездка в горную деревню Хатта. Каяки на озере, прогулка по старой крепости.', ARRAY['Каяки (по желанию)','Прогулка 2 часа']::text[], NULL, 'Бирюзовое озеро среди скал.'),
  ('dubai-desert', 5, 'Отъезд', ARRAY['Дубай','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], 'Время для покупок в торговом центре.', NULL),
  ('egypt-ancient', 1, 'Каир: прибытие', ARRAY['Аэропорт Каира','Нил']::text[], 'Встреча в аэропорту, трансфер в отель в центре и знакомство с гидом. Вечером — ужин с видом на Нил и обзор программы.', ARRAY['Вечерняя прогулка по набережной']::text[], 'Оставшееся время — отдых.', NULL),
  ('egypt-ancient', 2, 'Гиза и Саккара', ARRAY['Плато Гиза','Сфинкс','Саккара','Мемфис']::text[], 'Ранний выезд к пирамидам Гизы, затем Саккара с пирамидой Джосера и гробницами с росписями.', ARRAY['Осмотр объектов 5–6 часов','Обед у дороги']::text[], 'Вечером — свободное время.', 'Утренний свет на пирамидах, ещё нет автобусов.'),
  ('egypt-ancient', 3, 'Каирские музеи и Хан-эль-Халили', ARRAY['Египетские музеи','Исламский Каир','Хан-эль-Халили']::text[], 'Музей древностей с гидом, затем старый Каир и рынок Хан-эль-Халили. Конкретный музей (Египетский музей или Большой Египетский музей) определяется на момент поездки.', ARRAY['Музей 3 часа','Прогулка по рынку']::text[], 'Свободное время на рынке.', NULL),
  ('egypt-ancient', 4, 'Перелёт в Луксор и Карнак', ARRAY['Луксор','Карнакский храм','Луксорский храм']::text[], 'Утренний перелёт в Луксор, обед и вечерняя экскурсия в Карнак. Храмовый комплекс особенно хорош на закате.', ARRAY['Экскурсия в Карнак','Прогулка по аллее сфинксов']::text[], NULL, 'Вечерняя подсветка храма.'),
  ('egypt-ancient', 5, 'Долина царей и круиз', ARRAY['Долина царей','Храм Хатшепсут','Колоссы Мемнона']::text[], 'Три гробницы в Долине царей (выбор зависит от доступности билетов), храм Хатшепсут. После обеда посадка на круизное судно.', ARRAY['Осмотр гробниц','Начало круиза']::text[], 'Вечер на борту.', 'На закате судно выходит на Нил.'),
  ('egypt-ancient', 6, 'Эдфу и Ком-Омбо', ARRAY['Эдфу','Ком-Омбо','Нил']::text[], 'Остановки у двух храмов эпохи Птолемеев. Между ними — время для отдыха на палубе.', ARRAY['Храм Хоруса в Эдфу (один из лучше всего сохранившихся храмов страны)','Храм Ком-Омбо на закате']::text[], 'Отдых на палубе.', 'Закат на Ниле с палубы.'),
  ('egypt-ancient', 7, 'Асуан: Филэ и нубийская деревня', ARRAY['Асуан','Остров Филэ','Нубийская деревня']::text[], 'Высадка в Асуане, поездка на остров Филэ и знакомство с жизнью нубийской деревни на лодке-фелюке.', ARRAY['Лодочная прогулка','Чай в нубийском доме']::text[], 'Свободный вечер.', 'Разговор с хозяевами нубийского дома.'),
  ('egypt-ancient', 8, 'Абу-Симбел и возвращение в Каир', ARRAY['Абу-Симбел','Асуан','Каир']::text[], 'Очень ранний выезд (около 3–4 часов в одну сторону) в Абу-Симбел, затем перелёт в Каир.', ARRAY['Осмотр храмов Рамсеса II','Перелёт Асуан — Каир']::text[], NULL, 'Рассвет над озером Насер.'),
  ('egypt-ancient', 9, 'Отъезд', ARRAY['Каир']::text[], 'Трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('fuji-hike', 1, 'Токио: прибытие', ARRAY['Аэропорт','Токио','Синдзюку']::text[], 'Встреча, трансфер и заселение. Вечером — проверка снаряжения и ужин в идзакая в районе Синдзюку.', ARRAY['Проверка снаряжения']::text[], 'Вечер свободен.', 'Горячая лапша после перелёта.'),
  ('fuji-hike', 2, 'Кавагутико: акклиматизация', ARRAY['Кавагутико','Осино-Хаккай']::text[], 'Переезд на автобусе (около 2 часов) к озеру Кавагутико. Прогулка по деревне Осино-Хаккай с источниками и вид на Фудзи.', ARRAY['Прогулка 3 часа']::text[], 'Отдых перед подъёмом.', 'Родниковая вода из подножия вулкана.'),
  ('fuji-hike', 3, 'Начало подъёма', ARRAY['5-я станция Ёсида','8-я станция']::text[], 'Автобус к 5-й станции (около 2 300 м). Подъём до хижины на 8-й станции в течение 5–6 часов, ужин и ранний отбой.', ARRAY['Подъём 5–6 часов']::text[], NULL, 'Закат над облаками.'),
  ('fuji-hike', 4, 'Рассвет и спуск', ARRAY['Вершина Фудзи','Кавагутико']::text[], 'Ночной выход на вершину (около 3 776 м), встреча рассвета. Спуск по осыпи к 5-й станции, вечером — онсэн.', ARRAY['Подъём 2–3 часа','Спуск 3–4 часа','Онсэн']::text[], 'Отдых.', 'Тень Фудзи на облаках.'),
  ('fuji-hike', 5, 'Накасэндо: Магомэ — Цумаго', ARRAY['Магомэ','Цумаго']::text[], 'Поезд и автобус в долину Кисо. Прогулка по старинному тракту сёгунов между двумя почтовыми станциями с деревянными домами.', ARRAY['Прогулка 2,5–3 часа']::text[], 'Вечер в гостевом доме.', 'Колокольчик от медведей на тропе.'),
  ('fuji-hike', 6, 'Нарай-дзюку и долина Кисо', ARRAY['Нарай-дзюку','Кисо']::text[], 'Самая длинная почтовая станция тракта. Прогулка вдоль старых домов-гостиниц и обед у хозяев.', ARRAY['Прогулка 3 часа']::text[], 'Свободное время.', 'Лакированные гребни — местное ремесло.'),
  ('fuji-hike', 7, 'Каминокоти', ARRAY['Каминокоти','Мост Каппа','Река Адзуса']::text[], 'Переезд в Японские Альпы и прогулка вдоль реки к мосту Каппа с видом на вершины.', ARRAY['Прогулка 4–5 часов']::text[], NULL, 'Вода такого прозрачного цвета, что видно дно.'),
  ('fuji-hike', 8, 'Мацумото', ARRAY['Мацумото','Замок Ворона']::text[], 'Замок Мацумото — один из старейших сохранившихся в Японии. Прогулка по старому городу, ужин из блюд региона.', ARRAY['Осмотр замка']::text[], 'Вечер свободен.', 'Чёрные стены на фоне гор.'),
  ('fuji-hike', 9, 'Возвращение в Токио', ARRAY['Токио','Асакуса']::text[], 'Поезд в Токио и прощальный ужин. Вечерняя прогулка по Асакусе.', ARRAY['Прощальный ужин']::text[], 'Свободное время.', NULL),
  ('fuji-hike', 10, 'Отъезд', ARRAY['Токио','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('georgia-wine-mountains', 1, 'Тбилиси: прибытие', ARRAY['Аэропорт Тбилиси','Старый город','Серные бани']::text[], 'Встреча, трансфер в центр и заселение в гостевом доме с балконом. Вечером — прогулка по старому городу и ужин в семейном ресторане.', ARRAY['Ужин с первой дегустацией']::text[], 'Свободный вечер.', 'Резные балконы над улицей.'),
  ('georgia-wine-mountains', 2, 'Тбилиси: бани и кухня', ARRAY['Абанотубани','Нарикала','Мост Мира']::text[], 'Утро — серные бани и канатная дорога к крепости Нарикала. После обеда — рынок и мастер-класс по хинкали и хачапури.', ARRAY['Мастер-класс 3 часа']::text[], 'Вечерняя прогулка.', 'Хачапури по-аджарски с яйцом.'),
  ('georgia-wine-mountains', 3, 'Мцхета и дорога в горы', ARRAY['Мцхета','Джвари','Ананури']::text[], 'Монастырь Джвари над слиянием рек и собор Светицховели в Мцхете. Затем Ананури и подъём по Военно-Грузинской дороге.', ARRAY['Остановки']::text[], NULL, 'Серпантины и ледниковые долины.'),
  ('georgia-wine-mountains', 4, 'Степанцминда и Гергети', ARRAY['Степанцминда','Церковь Гергети']::text[], 'Подъём к церкви Святой Троицы на высоте 2 170 м — пешком около 2–3 часов или на внедорожнике. Вид на Казбек (5 047 м) при ясной погоде.', ARRAY['Подъём или внедорожник']::text[], 'Вечер свободен.', 'Церковь над облаками.'),
  ('georgia-wine-mountains', 5, 'Переезд в Кахетию', ARRAY['Гудаури','Телави','Алазанская долина']::text[], 'Дорога через перевал и спуск в Кахетию. Заселение в гостевой дом среди виноградников и ужин с хозяйкой.', ARRAY['Вечерняя дегустация']::text[], NULL, 'Запах виноградных листьев.'),
  ('georgia-wine-mountains', 6, 'Кахетия: квеври', ARRAY['Телави','Кварели','Винодельня']::text[], 'Знакомство с квеври — глиняными кувшинами, закопанными в землю. Дегустация янтарного вина в семейной винодельне и обед с хозяевами.', ARRAY['Дегустация 2 часа']::text[], NULL, 'Белое вино янтарного цвета.'),
  ('georgia-wine-mountains', 7, 'Сигнахи и Бодбе', ARRAY['Бодбе','Сигнахи']::text[], 'Монастырь святой Нино, где находится её гробница, и город любви Сигнахи с видом на Алазанскую долину.', ARRAY['Прогулка по городу']::text[], 'Свободный вечер.', 'Крепостная стена на холме.'),
  ('georgia-wine-mountains', 8, 'Возвращение в Тбилиси', ARRAY['Тбилиси','Сололаки']::text[], 'Дорога в Тбилиси, прогулка по району Сололаки и прощальная супра с тостами.', ARRAY['Прощальный ужин']::text[], NULL, 'Тамада произносит тосты.'),
  ('georgia-wine-mountains', 9, 'Отъезд', ARRAY['Тбилиси','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('iceland-aurora', 1, 'Рейкьявик: встреча и теория', ARRAY['Рейкьявик']::text[], 'Встреча группы, обзор погоды и прогноза сияния. Краткая теория ночной съёмки и подготовка снаряжения.', ARRAY['Занятие по настройкам камеры','Ужин']::text[], 'Свободное время вечером.', NULL),
  ('iceland-aurora', 2, 'Золотое кольцо и первая ночь', ARRAY['Тингветлир','Гейзир','Гюдльфосс']::text[], 'Национальный парк Тингветлир, гейзерная зона Гейсир и водопад Гюдльфосс. Вечером — первый выезд за сиянием при ясной погоде.', ARRAY['Дневные съёмки','Ночной выезд']::text[], 'Днём — отдых в гестхаусе.', 'Парящие над землёй сполохи на фоне зимнего неба.'),
  ('iceland-aurora', 3, 'Южное побережье', ARRAY['Сельяландсфосс','Скоугафосс','Рейнисфьяра','Вик']::text[], 'Водопады, чёрный пляж и базальтовые колонны. Вечером ночёвка в Вике и возможный второй выезд.', ARRAY['Съёмка водопадов на выдержках','Прогулка по пляжу']::text[], NULL, 'За водопадом Сельяландсфосс можно пройти по тропе.'),
  ('iceland-aurora', 4, 'Ледниковая лагуна', ARRAY['Скафтафетль','Йёкюльсаурлоун','Алмазный пляж']::text[], 'Переезд вдоль южного побережья к ледниковой лагуне и пляжу, усыпанному льдинами.', ARRAY['Съёмка льдин при закате']::text[], 'Вечер — свободное время.', 'Прозрачные льдины на чёрном песке.'),
  ('iceland-aurora', 5, 'Ледяная пещера', ARRAY['Ватнайёкюдль','Йёкюльсаурлоун']::text[], 'Экскурсия в ледяную пещеру с местным проводником. Выезд зависит от погоды и состояния ледника.', ARRAY['Пещера 2–3 часа','Возвращение в Рейкьявик или ночёвка у побережья']::text[], NULL, 'Голубой лёд, свет, пробивающийся сквозь стены.'),
  ('iceland-aurora', 6, 'Отъезд', ARRAY['Рейкьявик','Кефлавик']::text[], 'Завтрак, трансфер в аэропорт Кефлавик.', ARRAY[]::text[], 'Если рейс вечером, можно посетить термальный бассейн.', NULL),
  ('iceland-ring', 1, 'Рейкьявик: прибытие', ARRAY['Рейкьявик','Хатльгримскиркья','Харпа']::text[], 'Встреча группы, заселение и прогулка по центру: церковь Хатльгримскиркья, набережная и Харпа. Знакомство с гидом и обзор маршрута на карте.', ARRAY['Прогулка 2 часа']::text[], 'Вечер свободен.', 'Белая ночь над заливом летом.'),
  ('iceland-ring', 2, 'Золотое кольцо и юг', ARRAY['Тингветлир','Гейсир','Гюдльфосс','Сельяландсфосс']::text[], 'Национальный парк Тингветлир с разломом между плитами, гейзерная зона Гейсир, мощный водопад Гюдльфосс и вечером — Сельяландсфосс, за которым можно пройти по тропе.', ARRAY['Прогулки 3–4 часа']::text[], NULL, 'Гейзер Строккур выбрасывает воду каждые несколько минут.'),
  ('iceland-ring', 3, 'Скоугафосс, Вик и Дирхоулей', ARRAY['Скоугафосс','Рейнисфьяра','Дирхоулей']::text[], 'Водопад Скоугафосс высотой около 60 м, чёрный пляж Рейнисфьяра с базальтовыми колоннами и мыс Дирхоулей с птицами (в сезон — тупики).', ARRAY['Прогулка 3 часа']::text[], 'Вечер в Вике.', 'Базальтовые колонны у океана.'),
  ('iceland-ring', 4, 'Скафтафетль и ледниковая лагуна', ARRAY['Скафтафетль','Свартифосс','Йёкюльсаурлоун','Алмазный пляж']::text[], 'Тропа к водопаду Свартифосс в национальном парке Скафтафетль и вечер у ледниковой лагуны, где льдины плывут к океану.', ARRAY['Прогулка 2–3 часа']::text[], 'Вечер свободен.', 'Льдины на чёрном песке.'),
  ('iceland-ring', 5, 'Восточные фьорды', ARRAY['Хёфн','Сейдисфьордюр','Восточные фьорды']::text[], 'Дорога вдоль фьордов с остановками в рыбацких деревнях. Перевал Фьярдархейди ведёт в Сейдисфьордюр — яркий городок с радужной дорогой к церкви.', ARRAY['Фотоостановки']::text[], NULL, 'Радужная дорога к церкви.'),
  ('iceland-ring', 6, 'Мюватн', ARRAY['Деттифосс','Намаскард','Мюватн','Купальни']::text[], 'Мощный водопад Деттифосс, геотермальная зона Намаскард с грязевыми котлами и купание в голубой воде Мюватн.', ARRAY['Купание']::text[], NULL, 'Тёплая вода при свежем воздухе.'),
  ('iceland-ring', 7, 'Хусавик и Годафосс', ARRAY['Годафосс','Хусавик']::text[], 'Водопад Годафосс («водопад богов») и выход в море на наблюдение за китами из Хусавика (около 3 часов).', ARRAY['Лодка 3 часа']::text[], 'Вечер свободен.', 'Горбатые киты у борта лодки.'),
  ('iceland-ring', 8, 'Снайфедльснес', ARRAY['Акюрейри','Снайфедльснес','Кирккьюфетль']::text[], 'Длинный переезд к западному побережью и горе Кирккьюфетль, которая фотографируется с водопадом.', ARRAY['Съёмка']::text[], NULL, 'Конусообразная гора над водопадом.'),
  ('iceland-ring', 9, 'Рейкьявик и отъезд', ARRAY['Рейкьявик','Кефлавик']::text[], 'Возвращение в столицу, свободное время для купания в термальном бассейне и трансфер в аэропорт.', ARRAY[]::text[], 'Свободное время.', NULL),
  ('jordan-petra-wadi-rum', 1, 'Амман: прибытие', ARRAY['Аэропорт Королевы Алии','Амман']::text[], 'Встреча и трансфер (около 40 минут) в отель. Вечером — прогулка по центру и ужин с мезе, хумусом и свежим хлебом.', ARRAY['Ужин']::text[], 'Вечер свободен.', NULL),
  ('jordan-petra-wadi-rum', 2, 'Джераш и Амман', ARRAY['Джераш','Цитадель','Римский театр']::text[], 'Один из лучших сохранившихся римских городов Ближнего Востока: арка Адриана, колоннады и ипподром. После обеда — цитадель и римский театр в Аммане.', ARRAY['Экскурсия 6 часов']::text[], 'Свободное время.', 'Улица, по которой ходили римляне.'),
  ('jordan-petra-wadi-rum', 3, 'Мадаба и Мёртвое море', ARRAY['Мадаба','Гора Нево','Мёртвое море']::text[], 'Мозаичная карта Святой земли в Мадабе и гора Нево с видом на долину Иордана. Вечером — купание в Мёртвом море.', ARRAY['Купание 1 час']::text[], 'Вечер у отеля.', 'Лёжа на воде, можно читать газету.'),
  ('jordan-petra-wadi-rum', 4, 'Каньон Вади-Муджиб', ARRAY['Вади-Муджиб']::text[], 'Поход по руслу реки между красными стенами каньона. Нужны вода и обувь, которую не жалко, на тропе есть участки по воде и канатам.', ARRAY['Поход 3–4 часа']::text[], NULL, 'Холодная вода под жарким солнцем.'),
  ('jordan-petra-wadi-rum', 5, 'Дорога царей и Петра', ARRAY['Дорога царей','Маленькая Петра','Петра']::text[], 'Переезд в Петру по древнему торговому пути. Вечерняя прогулка по Малой Петре и ужин у отеля.', ARRAY['Переезд 4 часа']::text[], 'Вечер свободен.', NULL),
  ('jordan-petra-wadi-rum', 6, 'Петра: Сокровищница', ARRAY['Ущелье Сик','Аль-Хазне','Дорога фасадов']::text[], 'Раннее утро в узком ущелье Сик, вход в Сокровищницу и Королевские гробницы. Вечером — Петра при свечах (по расписанию).', ARRAY['Прогулка 5–6 часов']::text[], NULL, 'Цвет скал меняется в течение дня.'),
  ('jordan-petra-wadi-rum', 7, 'Петра: Монастырь и Вади-Рам', ARRAY['Монастырь Ад-Дейр','Вади-Рам']::text[], 'Подъём по примерно 800 ступеням к Монастырю, самая тихая часть Петры. Вечером — джип в Вади-Рам и ночь в бедуинском лагере.', ARRAY['Подъём 2–3 часа']::text[], 'Ужин у костра.', 'Чай с шалфеем у костра.'),
  ('jordan-petra-wadi-rum', 8, 'Вади-Рам и отъезд', ARRAY['Вади-Рам','Акаба']::text[], 'Рассвет в пустыне, утренняя поездка на джипе к аркам и дюнам, затем переезд в Акабу или Амман для вылета.', ARRAY['Джип 3 часа']::text[], NULL, 'Скалы цвета ржавчины.'),
  ('kamchatka-volcanoes', 1, 'Петропавловск-Камчатский', ARRAY['Петропавловск-Камчатский','Авачинская бухта']::text[], 'Встреча группы, заселение, инструктаж по безопасности в медвежьем крае. Прогулка по набережной и ужин с красной рыбой и крабом.', ARRAY['Инструктаж по безопасности','Проверка снаряжения']::text[], 'Свободный вечер.', 'Вид на два вулкана прямо из города.'),
  ('kamchatka-volcanoes', 2, 'Тихоокеанское побережье', ARRAY['Халактырский пляж','Авачинская бухта']::text[], 'Выезд на пляж с чёрным вулканическим песком, где океан часто грохочет даже в тихую погоду. После обеда — прогулка вдоль берега и подготовка к подъёму.', ARRAY['Прогулка 3 часа']::text[], 'Отдых.', 'Чёрный песок и прибой Тихого океана.'),
  ('kamchatka-volcanoes', 3, 'Авачинский вулкан', ARRAY['Авачинский вулкан','Перевал']::text[], 'Подъём по склону к кратеру (около 2 751 м). На высоте идём по осыпи и снегу, у кратера слышны фумаролы. Спуск по тому же маршруту.', ARRAY['Подъём 5–6 часов','Спуск 3–4 часа']::text[], NULL, 'Вид с кратера на Петропавловск и океан при ясной погоде.'),
  ('kamchatka-volcanoes', 4, 'Мутновский вулкан', ARRAY['Мутновская сопка','Фумарольные поля']::text[], 'Дорога на внедорожнике к Мутновскому вулкану и прогулка по зоне фумарол с паром, серой и красками минералов.', ARRAY['Прогулка 3–4 часа']::text[], NULL, 'Горячий пар выходит прямо из земли.'),
  ('kamchatka-volcanoes', 5, 'Налычевская долина', ARRAY['Налычево','Горячие источники']::text[], 'Переезд в долину, прогулка среди сопок и купание в горячих источниках. Возможна встреча с медведями, поэтому гид идёт с группой.', ARRAY['Купание']::text[], NULL, NULL),
  ('kamchatka-volcanoes', 6, 'Долина гейзеров', ARRAY['Долина гейзеров','Вертолёт']::text[], 'Перелёт на вертолёте к одной из самых известных гейзерных зон мира. Возможность полёта зависит от погоды и разрешений.', ARRAY['Экскурсия 3–4 часа']::text[], NULL, 'Паровые столбы над рекой Гейзерной.'),
  ('kamchatka-volcanoes', 7, 'Запасной день', ARRAY['Петропавловск-Камчатский']::text[], 'Резервный день на случай переноса вертолёта или других изменений. Если всё прошло по плану, остаётся свободное время и экскурсия по городу.', ARRAY['Экскурсия по городу']::text[], 'Свободный день.', NULL),
  ('kamchatka-volcanoes', 8, 'Паратунка', ARRAY['Паратунка','Горячие источники']::text[], 'Отдых в термальных бассейнах Паратунки и прогулка по лесу. Вечером — прощальный ужин с рыбой, икрой и камчатским крабом.', ARRAY['Купание']::text[], NULL, NULL),
  ('kamchatka-volcanoes', 9, 'Отъезд', ARRAY['Петропавловск-Камчатский','Аэропорт Елизово']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('korea-seoul-jeju', 1, 'Сеул: прибытие', ARRAY['Аэропорт Инчхон','Мёндон']::text[], 'Встреча, поездка на экспрессе в центр и заселение. Вечером — ужин в ресторане корейского барбекю и прогулка по оживлённому району Мёндон.', ARRAY['Ужин с самгёпсаль']::text[], 'Свободный вечер.', 'Столики с мангалом прямо на улице.'),
  ('korea-seoul-jeju', 2, 'Сеул: дворцы и ханоки', ARRAY['Кёнбоккун','Букчон','Инсадон']::text[], 'Утром — смена караула у ворот дворца Кёнбоккун и осмотр залов. Затем деревня ханок Букчон и улица Инсадон с чайными домами и лавками каллиграфии.', ARRAY['Экскурсия 5–6 часов']::text[], 'Свободное время.', 'Чай из цветов в старом доме.'),
  ('korea-seoul-jeju', 3, 'Сеул: рынки и кухня', ARRAY['Рынок Кванчжан','Тондэмун','Река Чхонгечхон']::text[], 'Рынок с закусками (биндэток, кимбап, тток-покки), мастер-класс по кимчи и прогулка по набережной Чхонгечхон.', ARRAY['Мастер-класс 3 часа']::text[], 'Свободное время.', 'Своё кимчи, которое мы забираем с собой.'),
  ('korea-seoul-jeju', 4, 'Поезд в Сокчхо и Сораксан', ARRAY['Сокчхо','Сораксан']::text[], 'Поезд или автобус в Сокчхо (около 2,5 часа), затем подъём в национальном парке по тропе к водопаду Йукдам. Лёгкий вариант — канатная дорога к руинам крепости.', ARRAY['Треккинг 3–4 часа']::text[], NULL, 'Скалы, похожие на каменные зубья.'),
  ('korea-seoul-jeju', 5, 'Храм Синхынса и Ульсанбавви', ARRAY['Синхынса','Ульсанбавви']::text[], 'Утро в храме Синхынса с большой бронзовой статуей Будды. Затем подъём на скалу Ульсанбавви по металлическим лестницам — самый известный вид парка.', ARRAY['Треккинг 3–4 часа']::text[], 'Вечер в Сокчхо.', 'Вид на океан и горы одновременно.'),
  ('korea-seoul-jeju', 6, 'Перелёт на Чеджу', ARRAY['Сеул','Чеджу']::text[], 'Возвращение в Сеул и перелёт на остров вулканического происхождения. Вечером — рынок Тонмун и ужин из чёрной свинины и морепродуктов.', ARRAY['Перелёт']::text[], 'Свободный вечер.', NULL),
  ('korea-seoul-jeju', 7, 'Сонсан Ильчульбон и хэнё', ARRAY['Сонсан Ильчульбон','Деревня хэнё']::text[], 'Рассвет на кратере Сонсан Ильчульбон и встреча с хэнё — женщинами-ныряльщицами, которые ловят морских ежей и ракушек без акваланга.', ARRAY['Подъём 40 минут','Беседа с хэнё']::text[], NULL, 'Свежие морепродукты, добытые утром.'),
  ('korea-seoul-jeju', 8, 'Остров Удо и побережье', ARRAY['Удо','Побережье Чеджу']::text[], 'Паром на маленький остров Удо, прогулка по полям с арахисом и белым песком. Вечерний закат на западном берегу.', ARRAY['Прогулка 3 часа']::text[], NULL, 'Пляж с коралловым песком.'),
  ('korea-seoul-jeju', 9, 'Отъезд', ARRAY['Чеджу','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт Чеджу.', ARRAY[]::text[], 'Время для кофе у моря.', NULL),
  ('kyoto-tea', 1, 'Прилёт и вечерний Гион', ARRAY['Аэропорт Кансай','Гион','Хаманатё']::text[], 'Встреча в аэропорту, переезд в Киото на поезде (около 80 минут). Заселение и прогулка по кварталу Гион.', ARRAY['Ужин в небольшом заведении']::text[], 'Свободный вечер.', NULL),
  ('kyoto-tea', 2, 'Хигасияма: храмы и чай', ARRAY['Киёмидзу-дэра','Саннендзака','Нинэндзака','Чайный дом']::text[], 'Утром — Киёмидзу-дэра, пока не пришли основные группы. После — узкие улицы с лавками и чайная церемония в доме XIX века.', ARRAY['Чайная церемония около часа','Прогулка по старым кварталам']::text[], 'Время для покупок сувениров.', 'Чайный мастер объясняет значение каждого движения.'),
  ('kyoto-tea', 3, 'Фусими Инари на рассвете', ARRAY['Фусими Инари','Тофуку-дзи']::text[], 'Подъём по тысячам ворот тории рано утром. Дальше — сад мхов и каменных композиций в храме Тофуку-дзи.', ARRAY['Подъём 1,5–2 часа','Завтрак в кафе у станции']::text[], 'После обеда — свободное время.', 'В утренние часы тропа тихая, слышно только птиц.'),
  ('kyoto-tea', 4, 'Ремесленники Киото', ARRAY['Нисидзин','Мастерская ножей','Гончарная мастерская']::text[], 'Встречи с мастерами в районе Нисидзин: ткачи, кузнецы, керамисты. Мастер-класс по росписи керамики.', ARRAY['Керамика: роспись чашки','Знакомство с кузнечным ремеслом']::text[], 'Свободное время вечером.', 'Чашка обжигается и отправляется вам почтой (за ваш счёт).'),
  ('kyoto-tea', 5, 'Нара и олени', ARRAY['Нара','Тодай-дзи','Касуга Тайся']::text[], 'Поезд в Нару, прогулка по парку с оленями. Тодай-дзи с гигантским бронзовым Буддой и каменные фонари храма Касуга.', ARRAY['Прогулка по парку 3–4 часа','Обед в местной лапшичной']::text[], 'После обеда — свободное время.', 'Олени кланяются за печенье сэмбэй.'),
  ('kyoto-tea', 6, 'Рёкан в Курама', ARRAY['Курама','Кибунэ','Онсэн']::text[], 'Переезд в горную деревню, прогулка по тропе Курама–Кибунэ среди кедров, затем онсэн и ужин кайсэки в рёкане.', ARRAY['Пеший переход 2–3 часа','Онсэн','Кайсэки']::text[], 'Вечером — чай на татами.', 'Ночь на футоне и завтрак в японском стиле.'),
  ('kyoto-tea', 7, 'Арасияма и свободный день', ARRAY['Арасияма','Тэнрю-дзи','Бамбуковая роща']::text[], 'Утром — бамбуковая роща и сад Тэнрю-дзи, пока нет толпы. После обеда свободное время или посещение музея по желанию.', ARRAY['Прогулка по роще','Лодка по реке Кацура (по желанию)']::text[], 'Вторая половина дня — свободна.', 'В тихие часы бамбук шелестит от ветра.'),
  ('kyoto-tea', 8, 'Отъезд', ARRAY['Киото','Аэропорт Кансай']::text[], 'Свободное утро для покупок или повторного визита в любимое место. Затем трансфер на вокзал и поезд до аэропорта Кансай (около 80 минут).', ARRAY[]::text[], 'Если рейс вечером, можно оставить багаж в отеле.', NULL),
  ('maldives-snorkel', 1, 'Мале и переезд на остров', ARRAY['Аэропорт Мале','Южный Ари']::text[], 'Встреча в аэропорту и переезд на остров (на паромном рейсе или катере, время зависит от расписания). Заселение в гестхаус, знакомство с хозяевами и ужин из морепродуктов.', ARRAY['Заселение','Ужин']::text[], 'Остаток дня — пляж.', 'Песок цвета сахара и тёплая вода.'),
  ('maldives-snorkel', 2, 'Первый выход на риф', ARRAY['Домашний риф','Южный Ари']::text[], 'Знакомство со снорклингом: выдача снаряжения, инструктаж и выход на лодке на ближайший риф. Рядом можно увидеть рыб-клоунов, мурен и морских черепах.', ARRAY['Снорклинг 2 часа']::text[], 'После обеда — отдых.', 'Стаи рыб над коралловыми садами.'),
  ('maldives-snorkel', 3, 'Китовые акулы', ARRAY['Южный Ари','Открытый океан']::text[], 'Весь день на лодке в поисках китовых акул. Мы заходим в воду только при разрешении гида и держим дистанцию. Встреча возможна, но не гарантирована.', ARRAY['Снорклинг по ситуации']::text[], NULL, 'Огромная рыба спокойно проплывает рядом.'),
  ('maldives-snorkel', 4, 'День на острове рыбаков', ARRAY['Остров','Рыбацкая пристань']::text[], 'Прогулка по деревне, знакомство с жизнью островитян и рыбалка на закате с местными. Ужин из пойманной рыбы с рисом и кокосовым чатни.', ARRAY['Рыбалка','Ужин']::text[], NULL, 'Лодки на закате.'),
  ('maldives-snorkel', 5, 'Пляжный день', ARRAY['Пляж для туристов','Лагуна']::text[], 'Свободный день для отдыха, каяков и купания. Гид организует короткую поездку на песчаную отмель для фотографий.', ARRAY['Каяки (по желанию)']::text[], 'Свободный день.', NULL),
  ('maldives-snorkel', 6, 'Скаты манта и закат на отмели', ARRAY['Манта-пойнт','Песчаная отмель']::text[], 'Выход к месту, где собираются манты. После снорклинга — закат на песчаной отмели, где можно поесть фруктов и сделать фотографии.', ARRAY['Снорклинг 2 часа']::text[], NULL, 'Широкие крылья мант скользят под водой.'),
  ('maldives-snorkel', 7, 'Возвращение в Мале', ARRAY['Мале','Хулумале']::text[], 'Утренний переезд в Мале и прогулка по рынку и набережной. Ночь в отеле рядом с аэропортом.', ARRAY['Прогулка 3 часа']::text[], 'Вечер свободен.', NULL),
  ('maldives-snorkel', 8, 'Отъезд', ARRAY['Мале','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('mongolia-nomads-gobi', 1, 'Улан-Батор: прибытие и город', ARRAY['Аэропорт Чингисхана','Монастырь Гандан','Площадь Сухэ-Батора']::text[], 'Встреча группы, заселение и первый обед с монгольскими пельменями бууз. Днём — монастырь Гандан с большой статуей Мигжид Жанрайсэг и площадь Сухэ-Батора.', ARRAY['Экскурсия 4 часа','Закупка тёплых вещей и воды']::text[], 'Вечер свободен.', 'Монахи читают мантры во дворе монастыря.'),
  ('mongolia-nomads-gobi', 2, 'Национальный парк Хустай', ARRAY['Хустайн-Нуруу','Степь Тола']::text[], 'Переезд на джипах (около 2 часов) в парк, где вернули в дикую природу лошадей Пржевальского. Прогулка вечером, когда табуны выходят на водопой, ночёвка в юрте.', ARRAY['Наблюдение за табунами','Прогулка 2 часа']::text[], 'Закат в степи.', 'Лошади, которых считали исчезнувшими, пасутся в нескольких сотнях метров.'),
  ('mongolia-nomads-gobi', 3, 'Дорога в Хархорин', ARRAY['Эрдэнэ-Дзу','Хархорин']::text[], 'Длинный день в пути через степи и холмы с остановками у семей кочевников. К вечеру — монастырь Эрдэнэ-Дзу, один из старейших в Монголии, построенный рядом с руинами древней столицы.', ARRAY['Переезд 6–7 часов','Экскурсия по монастырю']::text[], 'Ужин в юрте.', 'Белые ступы по периметру монастыря.'),
  ('mongolia-nomads-gobi', 4, 'Долина Орхон', ARRAY['Улаан-Цутгалан','Долина реки Орхон']::text[], 'Переезд к водопаду Улаан-Цутгалан высотой около 20 метров. Спуск к воде по тропе, пикник и прогулка по каньону.', ARRAY['Пеший спуск 1 час','Пикник']::text[], 'Свободное время у реки.', 'Водопад падает в каньон среди лавовых пород.'),
  ('mongolia-nomads-gobi', 5, 'Горячие источники Цэнхэр', ARRAY['Цэнхэр','Купальни']::text[], 'Дорога по горной долине к термальным источникам с температурой около 85 °C. Купание в бассейнах под открытым небом и чай в юрте у семьи скотоводов.', ARRAY['Купание','Знакомство с семьёй']::text[], 'Вечер свободен.', 'Помогаем хозяевам доить кобылиц (по желанию).'),
  ('mongolia-nomads-gobi', 6, 'Перелёт в Южную Гоби', ARRAY['Улан-Батор','Даланзадгад']::text[], 'Возврат в столицу и перелёт в Даланзадгад — центр Южной Гоби. Расположение в лагере из юрт у подножия гор.', ARRAY['Перелёт 1,5 часа','Заселение']::text[], 'Вечер свободен.', NULL),
  ('mongolia-nomads-gobi', 7, 'Ущелье Ёлын-Ам', ARRAY['Ёлын-Ам','Гурван-Сайхан']::text[], 'Прогулка по узкому ущелью между скал, где даже летом лежит лёд. Далее — возможность увидеть горных козлов и грифов.', ARRAY['Прогулка 3–4 часа']::text[], NULL, 'Холод ущелья после жаркой равнины.'),
  ('mongolia-nomads-gobi', 8, 'Дюны Хонгорын-Элс', ARRAY['Хонгорын-Элс','Лагерь у дюн']::text[], 'Длинный переезд к «поющим дюнам» длиной около 180 км. Вечером — подъём на гребень, когда спадает жара.', ARRAY['Подъём на дюну 1–1,5 часа']::text[], 'Закат на гребне.', 'Ветер заставляет песок звучать низким гудением.'),
  ('mongolia-nomads-gobi', 9, 'Дюны: верблюды и свободный день', ARRAY['Хонгорын-Элс','Семья верблюдоводов']::text[], 'Утро на верблюдах вдоль подножия дюн, обед в семье верблюдоводов. Остаток дня — свободное время на фото, чтение или прогулку к реке.', ARRAY['Верблюды 1,5 часа']::text[], 'Свободное время.', 'Звёздное небо без засветки.'),
  ('mongolia-nomads-gobi', 10, 'Пылающие скалы Баянзаг', ARRAY['Баянзаг','Саксаульная роща']::text[], 'Красные обрывы, где нашли первые в мире гнёзда динозавров. Саксауловая роща и вечерний свет на скалах.', ARRAY['Прогулка 2 часа']::text[], NULL, 'Скалы окрашиваются в красный на закате.'),
  ('mongolia-nomads-gobi', 11, 'Возвращение в Улан-Батор', ARRAY['Даланзадгад','Улан-Батор']::text[], 'Утренний рейс в столицу. Вторая половина дня — рынок, сувениры и прощальный ужин с национальным шоу.', ARRAY['Прощальный ужин']::text[], 'Свободное время на рынке.', NULL),
  ('mongolia-nomads-gobi', 12, 'Отъезд', ARRAY['Улан-Батор','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], 'Если рейс вечером, можно посетить музей.', NULL),
  ('morocco-sahara-medina', 1, 'Марракеш: прибытие', ARRAY['Марракеш','Джемаа-эль-Фна','Риад']::text[], 'Встреча, трансфер в медину пешком и на тележках, заселение в риад. Вечером — площадь Джемаа-эль-Фна с музыкантами, рассказчиками и лотками.', ARRAY['Ужин на площади']::text[], 'Свободный вечер.', 'Дым от грилей над площадью.'),
  ('morocco-sahara-medina', 2, 'Марракеш: сады и дворцы', ARRAY['Сады Мажорель','Дворец Бахия','Медина']::text[], 'Синий сад Мажорель, дворец Бахия с расписными потолками и прогулка по сукам. После обеда — мастерские кожевников и ткачей.', ARRAY['Экскурсия 5 часов']::text[], 'Вечер на крыше риада.', 'Мятный чай в маленькой лавке.'),
  ('morocco-sahara-medina', 3, 'Через Атлас к Айт-Бен-Хадду', ARRAY['Тизи-н-Тичка','Айт-Бен-Хадду','Уарзазат']::text[], 'Переезд по перевалу высотой около 2 260 м, остановки на смотровых. Крепость Айт-Бен-Хадду — глинобитное поселение, которое сохранилось почти нетронутым.', ARRAY['Переезд 6 часов','Прогулка по крепости']::text[], NULL, 'Крепость, знакомая по кино.'),
  ('morocco-sahara-medina', 4, 'Ущелья Дадес и Тодра', ARRAY['Ущелье Дадес','Ущелье Тодра','Оазис Тинехир']::text[], 'Каменные стены высотой до 300 м и ручей в долине. Прогулка по ущелью, обед у местной семьи и дорога к Мерзуге.', ARRAY['Прогулка 2–3 часа']::text[], NULL, 'Прохлада в тени вертикальных скал.'),
  ('morocco-sahara-medina', 5, 'Мерзуга: ночь в пустыне', ARRAY['Мерзуга','Эрг-Шебби']::text[], 'Караван верблюдов уходит к лагерю среди дюн на закате. Вечером — ужин, барабаны и звёздное небо.', ARRAY['Верблюды 1,5 часа']::text[], 'Вечер у костра.', 'Рассвет на гребне дюны.'),
  ('morocco-sahara-medina', 6, 'Из пустыни в Фес', ARRAY['Эрфуд','Мидельт','Ифран','Фес']::text[], 'Длинный переезд (около 8 часов) через кедровый лес в Среднем Атласе. Остановка в Ифране, где обезьяны-маготы просят орешки.', ARRAY['Переезд 8 часов']::text[], 'Вечер отдыха.', NULL),
  ('morocco-sahara-medina', 7, 'Фес: медина', ARRAY['Медина Феса','Медресе Бу-Инания','Кожевенные мастерские']::text[], 'Прогулка по крупнейшему пешеходному кварталу мира: фонтан Неджарин, медресе и мастерские. Кожевенные чаны смотрим с террас.', ARRAY['Экскурсия 5–6 часов']::text[], NULL, 'Запах кожи и красок.'),
  ('morocco-sahara-medina', 8, 'Шефшауэн', ARRAY['Шефшауэн','Площадь Утта-эль-Хаммам']::text[], 'Дорога в горы Риф (около 4 часов) и прогулка по голубым переулкам. Вечер — на крыше с видом на город.', ARRAY['Прогулка 3 часа']::text[], NULL, 'Тысячи оттенков синего.'),
  ('morocco-sahara-medina', 9, 'Шефшауэн: свободный день', ARRAY['Водопады Акчур','Шефшауэн']::text[], 'Свободный день: утренняя прогулка к водопадам Акчур или покупки в лавках ремесленников. Прощальный ужин на террасе.', ARRAY['Прогулка 3 часа']::text[], 'Свободное время.', NULL),
  ('morocco-sahara-medina', 10, 'Отъезд', ARRAY['Шефшауэн','Танжер','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт Танжера или Феса (время зависит от рейса).', ARRAY[]::text[], NULL, NULL),
  ('nepal-annapurna-base-camp', 1, 'Катманду: прибытие', ARRAY['Аэропорт Трибхуван','Тамель']::text[], 'Встреча в аэропорту, переезд в отель в районе Тамель. Знакомство с гидом и разбор снаряжения.', ARRAY['Проверка снаряжения']::text[], 'Вечер свободен.', NULL),
  ('nepal-annapurna-base-camp', 2, 'Катманду: Бодхнатх и Пашупатинатх', ARRAY['Ступа Бодхнатх','Пашупатинатх','Сваямбунатх']::text[], 'Утро в одной из самых больших буддийских ступ в мире и индуистском храмовом комплексе на берегу реки Багмати.', ARRAY['Экскурсия 5–6 часов','Подготовка к треккингу']::text[], 'Вторая половина дня — свободна.', 'Монахи и паломники вращают молитвенные барабаны.'),
  ('nepal-annapurna-base-camp', 3, 'Покхара', ARRAY['Покхара','Озеро Фева']::text[], 'Перелёт или переезд в Покхару. Прогулка вдоль озера Фева, вечером — общий ужин.', ARRAY['Лодка по озеру (по желанию)']::text[], 'Свободное время вечером.', 'Отражение Мачапучаре в озере (если ясно).'),
  ('nepal-annapurna-base-camp', 4, 'Начало треккинга: Улери', ARRAY['Найапул','Тиркхедхунга','Улери']::text[], 'Дорога к Найапулу и первый подъём по каменным ступеням. Ночёвка в чайном домике.', ARRAY['Треккинг 5–6 часов']::text[], NULL, 'Ступени, вырубленные в склоне, ведут через террасные поля.'),
  ('nepal-annapurna-base-camp', 5, 'Горепани', ARRAY['Улери','Банталанти','Горепани']::text[], 'Переход через рододендроновый лес (весной он цветёт) к деревне Горепани на высоте около 2 870 м.', ARRAY['Треккинг 5–6 часов']::text[], NULL, NULL),
  ('nepal-annapurna-base-camp', 6, 'Пун-Хилл и Тадапани', ARRAY['Пун-Хилл','Горепани','Тадапани']::text[], 'Выход в темноте на Пун-Хилл, рассвет над Дхаулагири и Аннапурной, затем спуск и переход в Тадапани.', ARRAY['Рассвет на 3 210 м','Треккинг 6–7 часов']::text[], NULL, 'Первые лучи освещают одну вершину за другой.'),
  ('nepal-annapurna-base-camp', 7, 'Чхомронг', ARRAY['Ганджунг','Чхомронг']::text[], 'Спуск по каменным ступеням через лес к реке и подъём к деревне Чхомронг на высоте около 2 170 м. Из окна чайного домика видна Мачапучаре и пик Аннапурна Юг.', ARRAY['Треккинг 5–6 часов']::text[], NULL, 'Каменные дома гурунгов, террасы.'),
  ('nepal-annapurna-base-camp', 8, 'Долина Модхи', ARRAY['Сихинг','Бамбу','Дованг']::text[], 'Спуск к реке по лесной тропе и подъём в долину Модхи, где рододендроны сменяются бамбуком. Ночёвка в Дованге у подножия скал, вечером разбор состояния участников.', ARRAY['Треккинг 5–6 часов']::text[], NULL, NULL),
  ('nepal-annapurna-base-camp', 9, 'Мачапучаре Бейс-Кэмп', ARRAY['Хималаи','Деурали','Мачапучаре Бейс-Кэмп']::text[], 'Подъём над границей леса. Высота около 3 700 м, вечером — холод и ранний отбой.', ARRAY['Треккинг 5 часов']::text[], 'Отдых в чайном домике.', 'Вечером Мачапучаре светится розовым.'),
  ('nepal-annapurna-base-camp', 10, 'Базовый лагерь Аннапурны', ARRAY['Аннапурна Бейс-Кэмп','Ледник Аннапурны']::text[], 'Подъём к базовому лагерю на высоте 4 130 м, рассвет на ледниковом цирке и спуск к Бамбу.', ARRAY['Подъём 2–3 часа','Спуск 5–6 часов']::text[], NULL, 'Кольцо вершин вокруг ледника.'),
  ('nepal-annapurna-base-camp', 11, 'Спуск и Сьяули Базар', ARRAY['Бамбу','Сьяули Базар','Чомронг']::text[], 'Длинный спуск по той же долине, но с видом на вершины, которые теперь остались за спиной. К вечеру группа выходит в зелёные леса и деревни, ночёвка в Сьяули Базаре.', ARRAY['Треккинг 6–7 часов']::text[], NULL, NULL),
  ('nepal-annapurna-base-camp', 12, 'Джину и Найапул', ARRAY['Джину','Горячие источники','Найапул','Покхара']::text[], 'Утренний заход в горячие источники, спуск к Найапулу и возвращение в Покхару.', ARRAY['Купание в горячих источниках']::text[], 'Вечер свободен.', 'Горячие источники у реки.'),
  ('nepal-annapurna-base-camp', 13, 'Возвращение в Катманду', ARRAY['Покхара','Катманду']::text[], 'Перелёт или переезд в Катманду (около 25–30 минут рейсом, 6–8 часов по дороге). Вечером — прощальный ужин с гидом и командой носильщиков.', ARRAY['Прощальный ужин']::text[], 'Свободное время для покупок.', NULL),
  ('nepal-annapurna-base-camp', 14, 'Отъезд', ARRAY['Катманду','Аэропорт Трибхуван']::text[], 'Трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('newzealand-south-island', 1, 'Крайстчерч', ARRAY['Крайстчерч','Ботанический сад','Река Эйвон']::text[], 'Встреча, получение автомобиля, закупка продуктов. Прогулка по ботаническому саду и лодка по реке Эйвон (по желанию).', ARRAY['Закупка продуктов']::text[], 'Вечер свободен.', NULL),
  ('newzealand-south-island', 2, 'Крайстчерч — Текапо', ARRAY['Аннавил','Озеро Текапо','Церковь Доброго Пастыря']::text[], 'Дорога через равнины Кентербери к озеру молочно-бирюзового цвета. Вечером — обсерватория с наблюдением за звёздами (по желанию).', ARRAY['Прогулка у озера']::text[], 'Вечер свободен.', 'Звёзды в одном из заповедников тёмного неба.'),
  ('newzealand-south-island', 3, 'Аораки (Маунт-Кук)', ARRAY['Пукаки','Долина Хукер','Аораки']::text[], 'Прогулка по долине Хукер через три висячих моста к ледниковому озеру под вершиной Кука (около 10 км туда и обратно).', ARRAY['Прогулка 3 часа']::text[], NULL, 'Ледяные глыбы в озере.'),
  ('newzealand-south-island', 4, 'Квинстаун', ARRAY['Омарама','Вануака','Квинстаун']::text[], 'Дорога через перевал Кромвелл, виноградники и озеро Данстан. Вечером — гондола и ужин с видом на озеро Вакатипу.', ARRAY['Гондола']::text[], 'Свободный вечер.', NULL),
  ('newzealand-south-island', 5, 'Квинстаун: свободный день', ARRAY['Квинстаун','Глиноркей']::text[], 'Свободное время для активностей: джет-боат, парапланы, прогулка в Глиноркей или дегустация в винодельнях.', ARRAY['Активности (по желанию)']::text[], 'Свободный день.', NULL),
  ('newzealand-south-island', 6, 'Те-Анау', ARRAY['Те-Анау','Озеро Те-Анау']::text[], 'Дорога к фьордам. Посещение пещер светлячков в Те-Анау (по желанию) и вечер на берегу озера.', ARRAY['Прогулка']::text[], 'Вечер свободен.', 'Светлячки под сводами пещеры.'),
  ('newzealand-south-island', 7, 'Милфорд-Саунд', ARRAY['Хомер-Туннель','Милфорд-Саунд']::text[], 'Путь по одной из самых красивых дорог мира и круиз по фьорду с водопадами и тюленями.', ARRAY['Круиз 2 часа']::text[], NULL, 'Вершина Митре-Пик над водой.'),
  ('newzealand-south-island', 8, 'Ванака', ARRAY['Квинстаун','Ванака','Озеро Ванака']::text[], 'Возвращение и переезд к озеру Ванака, фотография знаменитого одинокого дерева.', ARRAY['Прогулка у озера']::text[], 'Свободный вечер.', 'Дерево в воде на закате.'),
  ('newzealand-south-island', 9, 'Перевал Хаас', ARRAY['Перевал Хаас','Водопады Блю-Пулс','Фокс']::text[], 'Дорога по перевалу Хаас с короткими прогулками к водопадам и голубым бассейнам. Ночёвка у ледника Фокс.', ARRAY['Прогулка 2 часа']::text[], NULL, NULL),
  ('newzealand-south-island', 10, 'Ледник Фокс', ARRAY['Фокс','Ледник']::text[], 'Прогулка к краю ледника по долине и свободное время. Вертолётные экскурсии (по желанию).', ARRAY['Прогулка 3 часа']::text[], NULL, 'Лёд над долиной.'),
  ('newzealand-south-island', 11, 'Франц-Йозеф и Хокитика', ARRAY['Франц-Йозеф','Хокитика']::text[], 'Тропа к леднику и переезд на побережье Хокитики, где в воде лежат плавуны из лесов.', ARRAY['Прогулка 2 часа']::text[], 'Вечер свободен.', NULL),
  ('newzealand-south-island', 12, 'Перевал Артура', ARRAY['Арторс-Пасс','Кэсл-Хилл']::text[], 'Горный перевал и огромные валуны Кэсл-Хилл. Остановка у кафе с попугаями кеа.', ARRAY['Прогулка 2 часа']::text[], NULL, 'Кеа очень любопытны.'),
  ('newzealand-south-island', 13, 'Возвращение', ARRAY['Крайстчерч']::text[], 'Возвращение в Крайстчерч через равнины Кентербери. Остановка в Аркадии для обеда и прощальный ужин в городе.', ARRAY['Ужин']::text[], 'Свободный вечер.', NULL),
  ('newzealand-south-island', 14, 'Отъезд', ARRAY['Крайстчерч']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('norway-lofoten', 1, 'Лофотены: прибытие', ARRAY['Аэропорт Евенес или Свольвер','Свольвер']::text[], 'Встреча группы, переезд в Свольвер и заселение. Вечерняя прогулка по набережной и первый ужин с треской.', ARRAY['Обзор маршрута и прогноза погоды']::text[], 'Свободное время.', 'Горы поднимаются прямо из воды.'),
  ('norway-lofoten', 2, 'Рейне и Хамнёй', ARRAY['Хамнёй','Рейне','Рейнебринген']::text[], 'Подъём на Рейнебринген (около 448 м) по каменным ступеням. Сверху видно Рейне, острова и фьорд. После спуска — съёмка Хамнёя на закате.', ARRAY['Подъём 1,5–2 часа','Съёмка Хамнёя']::text[], 'После обеда — свободное время.', 'Один из самых известных видов Норвегии.'),
  ('norway-lofoten', 3, 'Квалвика и Рюттен', ARRAY['Квалвика','Рюттен']::text[], 'Тропа через болото и холм к пляжу Квалвика, затем подъём на Рюттен. Вид на два фьорда сразу.', ARRAY['Треккинг 4–6 часов']::text[], NULL, 'Пляж с песком, окружённый горами.'),
  ('norway-lofoten', 4, 'Нусфьорд и Ленекнес', ARRAY['Нусфьорд','Ленекнес','Ленекнес-Лофотен']::text[], 'Одна из самых старых рыбацких деревень архипелага. Дорога по береговой линии с остановками.', ARRAY['Прогулка по деревне']::text[], 'Свободное время.', 'Сушилки для трески — типичная картина Лофотенов.'),
  ('norway-lofoten', 5, 'Пляжи Уттакляйв и Хауклянд', ARRAY['Хауклянд','Уттакляйв','Вестфьорд']::text[], 'Белые песчаные пляжи на западном берегу архипелага. Прогулка по пляжу, купание для смелых (вода холодная) и съёмка при низком солнце над океаном.', ARRAY['Съёмка на закате']::text[], NULL, 'Закат над открытым океаном.'),
  ('norway-lofoten', 6, 'Хеннингсвер и музей викингов', ARRAY['Хеннингсвер','Музей викингов в Бурге']::text[], 'Рыбацкая деревня на мелких островах, знаменитое футбольное поле и реконструированный длинный дом вождя.', ARRAY['Осмотр музея']::text[], NULL, NULL),
  ('norway-lofoten', 7, 'Тролльфьорд', ARRAY['Свольвер','Тролльфьорд']::text[], 'Морская прогулка по узкому Тролльфьорду, возможна встреча с морскими орлами.', ARRAY['Лодка 3 часа']::text[], NULL, 'Орлы берут рыбу прямо из воды.'),
  ('norway-lofoten', 8, 'Отъезд', ARRAY['Свольвер','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('peru-salkantay', 1, 'Куско: прибытие', ARRAY['Аэропорт Куско','Площадь Оружия']::text[], 'Встреча, заселение и спокойный день для акклиматизации на высоте около 3 400 м. Чай из листьев коки и лёгкая прогулка по площади.', ARRAY['Отдых']::text[], 'Вечер свободен.', 'Колокола собора над площадью.'),
  ('peru-salkantay', 2, 'Куско: крепость и храмы', ARRAY['Саксайуаман','Кориканча','Собор']::text[], 'Прогулка по историческому центру: храм Кориканча, собор и крепость Саксайуаман со стенами из огромных блоков.', ARRAY['Экскурсия 5 часов']::text[], 'Свободное время.', 'Стены, подогнанные без раствора.'),
  ('peru-salkantay', 3, 'Священная долина', ARRAY['Писак','Ольянтайтамбо','Морай']::text[], 'Рынок в Писаке, круглые террасы Морай и крепость Ольянтайтамбо. Ночёвка ниже Куско для лучшей акклиматизации.', ARRAY['Экскурсия 7 часов']::text[], NULL, 'Террасы, которые инки использовали как лабораторию.'),
  ('peru-salkantay', 4, 'Умантай', ARRAY['Мольепата','Сорапампа','Озеро Умантай']::text[], 'Дорога к началу тропы и подъём к бирюзовому озеру Умантай на 4 200 м у подножия ледника. Ночь в палатках.', ARRAY['Треккинг 4–5 часов']::text[], NULL, 'Озеро под ледником.'),
  ('peru-salkantay', 5, 'Перевал Салкантай', ARRAY['Перевал Салкантай','Чуллау']::text[], 'Самый трудный день: подъём на 4 630 м, спуск в долину и ночь в палатках среди облачного леса.', ARRAY['Треккинг 8–9 часов']::text[], NULL, 'Вершина Салкантай (6 271 м) рядом.'),
  ('peru-salkantay', 6, 'Лес и кофе', ARRAY['Лукмабамба','Кофейная ферма']::text[], 'Спуск в тёплую долину, остановка на кофейной ферме и ночь в палатках в тропическом лесу.', ARRAY['Треккинг 6–7 часов','Дегустация кофе']::text[], NULL, 'Свежеобжаренные зёрна.'),
  ('peru-salkantay', 7, 'Ллактапата', ARRAY['Ллактапата','Гидроэлектрика','Агуас-Кальентес']::text[], 'Подъём к руинам Ллактапата с первым видом на Мачу-Пикчу. Затем спуск и ночь в Агуас-Кальентес.', ARRAY['Треккинг 5–6 часов']::text[], NULL, 'Первый вид на цитадель.'),
  ('peru-salkantay', 8, 'Мачу-Пикчу', ARRAY['Мачу-Пикчу','Храм Солнца']::text[], 'Ранний автобус к воротам и обход цитадели с гидом. Вход по билетам со временем и маршрутом, у каждого группового допуска — своя схема.', ARRAY['Экскурсия 3 часа']::text[], 'Свободное время.', 'Туман над руинами.'),
  ('peru-salkantay', 9, 'Возвращение в Куско', ARRAY['Ольянтайтамбо','Куско']::text[], 'Утренний поезд из Агуас-Кальентес до Ольянтайтамбо и трансфер в Куско (общее время около 4–5 часов). Вечером — прощальный ужин с блюдами региона.', ARRAY['Ужин']::text[], 'Свободный вечер.', NULL),
  ('peru-salkantay', 10, 'Отъезд', ARRAY['Куско','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('portugal-lisbon-douro', 1, 'Лиссабон: прибытие и Алфама', ARRAY['Аэропорт Лиссабона','Алфама','Мирадору-да-Граса']::text[], 'Встреча, заселение и вечерняя прогулка по старейшему кварталу Алфама с остановкой на смотровой площадке. Ужин в маленьком ресторане с вечерним фаду.', ARRAY['Ужин с фаду']::text[], 'Свободный вечер.', 'Звуки гитары из узких переулков.'),
  ('portugal-lisbon-douro', 2, 'Лиссабон: рынок и Белен', ARRAY['Рынок Рибейра','Белен','Башня Белен']::text[], 'Утром — рынок с морепродуктами и сырами, затем пастеш де Белен прямо из печи. Монастырь Жеронимуш и башня на берегу Тежу.', ARRAY['Рынок','Мастер-класс по тортам']::text[], 'Вторая половина дня — свободна.', 'Рецепт паштейш хранится в секрете почти двести лет.'),
  ('portugal-lisbon-douro', 3, 'Синтра и Кашкайш', ARRAY['Синтра','Дворец Пена','Кабо-да-Рока']::text[], 'Поездка в Синтру: яркий дворец Пена и тропа через парк. Заезд на мыс Кабо-да-Рока — самую западную точку континентальной Европы.', ARRAY['Прогулка 3–4 часа']::text[], 'Ужин в Кашкайше.', 'Закат над Атлантикой.'),
  ('portugal-lisbon-douro', 4, 'Из Лиссабона в Порту через Коимбру', ARRAY['Коимбра','Университет Коимбры','Порту']::text[], 'Поезд на север с остановкой в Коимбре: библиотека университета и узкие улицы. Вечером — Порту, прогулка по набережной.', ARRAY['Поезд 3 часа','Осмотр библиотеки']::text[], 'Вечер свободен.', 'Студенты в чёрных мантиях.'),
  ('portugal-lisbon-douro', 5, 'Порту: портвейн и Рибейра', ARRAY['Рибейра','Мост Дона Луиша','Вила-Нова-ди-Гая']::text[], 'Утро в районе Рибейра и подъём к мосту Дона Луиша. Днём — погреба портвейна в Вила-Нова-ди-Гая с дегустацией и ужин из блюд региона.', ARRAY['Дегустация 2 часа']::text[], 'Свободный вечер.', 'Бочки, в которых вино выдерживается десятилетиями.'),
  ('portugal-lisbon-douro', 6, 'Долина Дору: поезд и лодка', ARRAY['Пиньян','Река Дору']::text[], 'Утренний поезд вдоль реки в Пиньян. Затем лодка по Дору между террасами виноградников, обед на квинте.', ARRAY['Поезд 2,5 часа','Лодка 1,5 часа']::text[], NULL, 'Виноградные террасы спускаются к реке.'),
  ('portugal-lisbon-douro', 7, 'Квинта: день среди лоз', ARRAY['Квинта-ду-Верзеа','Виноградники']::text[], 'Прогулка среди лоз с хозяином, мастер-класс по купажу и обед за общим столом. Осенью — участие в сборе винограда (по сезону).', ARRAY['Прогулка 2 часа','Мастер-класс по купажу']::text[], 'Свободное время.', 'Дегустация с бочки.'),
  ('portugal-lisbon-douro', 8, 'Отъезд из Порту', ARRAY['Порту','Аэропорт']::text[], 'Завтрак, возвращение в Порту и трансфер в аэропорт.', ARRAY[]::text[], 'Время для сувениров.', NULL),
  ('rajasthan-spice', 1, 'Дели: прибытие', ARRAY['Аэропорт Дели','Старый Дели','Чандни-Чоук']::text[], 'Встреча и трансфер в отель. Вечером — прогулка по Чандни-Чоук с уличной едой: чаат, парантхи и сладости.', ARRAY['Дегустация street food']::text[], 'Свободный вечер.', 'Запах жареных специй.'),
  ('rajasthan-spice', 2, 'Дели — Агра', ARRAY['Агра','Агра-форт']::text[], 'Утренний поезд или трансфер в Агру (около 3 часов). Красный форт Агры, вечерний чай и подготовка к рассвету.', ARRAY['Форт Агры']::text[], NULL, 'Вид на Тадж-Махал из форта.'),
  ('rajasthan-spice', 3, 'Тадж-Махал и дорога в Джайпур', ARRAY['Тадж-Махал','Фатехпур-Сикри','Джайпур']::text[], 'Рассвет у Тадж-Махала (в пятницу закрыт), затем Фатехпур-Сикри и дорога в Джайпур (около 4 часов).', ARRAY['Экскурсия']::text[], NULL, 'Мрамор меняет цвет с первыми лучами.'),
  ('rajasthan-spice', 4, 'Джайпур: рынки и специи', ARRAY['Джохари-базар','Кулинарная студия']::text[], 'Утренний рынок, выбор специй и мастер-класс по масалам, лепёшкам и дхалу. Вечерняя прогулка.', ARRAY['Мастер-класс 3 часа']::text[], 'Вечер свободен.', 'Масала по вашему вкусу.'),
  ('rajasthan-spice', 5, 'Амбер-форт и ремёсла', ARRAY['Амбер-форт','Санганер']::text[], 'Форт на холме, ступенчатый колодец Панна Мина ка Кунд и мастер-класс по ручной печати на ткани в Санганере.', ARRAY['Прогулка 3 часа','Мастер-класс']::text[], NULL, 'Рисунок на ткани по вашему эскизу.'),
  ('rajasthan-spice', 6, 'Пушкар', ARRAY['Пушкар','Озеро Пушкар']::text[], 'Дорога в Пушкар (около 3 часов), вечерняя церемония у озера и прогулка по рынку.', ARRAY['Вечерняя церемония']::text[], NULL, 'Лепестки роз на воде.'),
  ('rajasthan-spice', 7, 'Удайпур', ARRAY['Удайпур','Озеро Пичола']::text[], 'Дорога из Пушкара в Удайпур (около 5 часов) через Аравалли. Вечером — прогулка на лодке по озеру Пичола и ужин на крыше с видом на Городской дворец.', ARRAY['Лодка 1 час']::text[], 'Ужин на крыше.', 'Дворец, отражающийся в воде.'),
  ('rajasthan-spice', 8, 'Семейная кухня', ARRAY['Удайпур','Деревня гончаров']::text[], 'Утро в мастерской гончаров, обед в семье и мастер-класс по раджастханской кухне: дал-баати-чурма.', ARRAY['Мастер-класс']::text[], NULL, 'Обед за общим столом.'),
  ('rajasthan-spice', 9, 'Отъезд', ARRAY['Удайпур','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('srilanka-tea-ayurveda', 1, 'Коломбо и Негомбо', ARRAY['Аэропорт Коломбо','Негомбо']::text[], 'Встреча в аэропорту и трансфер на берег океана в Негомбо. Вечером — рыбный рынок и ужин из морепродуктов на пляже.', ARRAY['Прогулка по рынку']::text[], 'Отдых после перелёта.', 'Рыбаки возвращаются с уловом.'),
  ('srilanka-tea-ayurveda', 2, 'Дамбулла и Сигирия', ARRAY['Дамбулла','Сигирия','Пещерные храмы']::text[], 'Золотой храм и пещеры Дамбуллы с росписями. Затем — подъём на скалу Сигирия по лестницам к древним фрескам и садам на вершине.', ARRAY['Подъём 1,5 часа']::text[], 'Вечер свободен.', 'Сады на вершине скалы, построенные в V веке.'),
  ('srilanka-tea-ayurveda', 3, 'Полоннарува на велосипедах', ARRAY['Полоннарува','Гал Вихара','Деревня']::text[], 'Руины средневековой столицы на велосипедах: статуи Будды, дворец и ступы. Обед в семье, где готовят на дровах.', ARRAY['Велопрогулка 3 часа']::text[], NULL, 'Лежащий Будда, высеченный в скале.'),
  ('srilanka-tea-ayurveda', 4, 'Канди: храм Зуба', ARRAY['Канди','Храм Зуба Будды','Озеро Канди']::text[], 'Переезд в Канди (около 3 часов). Вечером — церемония пуджи в храме, где хранится реликвия. Концерт традиционных танцев.', ARRAY['Церемония пуджи']::text[], 'Вечер свободен.', 'Барабаны и звон храмовых колоколов.'),
  ('srilanka-tea-ayurveda', 5, 'Нувара-Элия и чайные холмы', ARRAY['Нувара-Элия','Чайная фабрика']::text[], 'Переезд в горы (около 4 часов) через водопады и плантации. Экскурсия на фабрику и дегустация чая в саду.', ARRAY['Дегустация']::text[], NULL, 'Работницы собирают листья вручную.'),
  ('srilanka-tea-ayurveda', 6, 'Поезд в Эллу', ARRAY['Нану-Оя','Элла','Мост Девяти арок']::text[], 'Утренний поезд из Нану-Оя в Эллу по холмам. Прогулка до моста Девяти арок и вид на долину.', ARRAY['Поезд 3 часа','Прогулка 1 час']::text[], 'Вечер свободен.', 'Поезд проходит по каменному мосту.'),
  ('srilanka-tea-ayurveda', 7, 'Сафари в Яла', ARRAY['Яла','Национальный парк Яла']::text[], 'Ранний выезд в парк. Слоны, крокодилы, павлины и (по удаче) леопард. Возвращение на обед и отдых.', ARRAY['Сафари 4 часа']::text[], 'Вечер свободен.', 'Слоны у водопоя.'),
  ('srilanka-tea-ayurveda', 8, 'Побережье и форт Галле', ARRAY['Мириса','Галле']::text[], 'Переезд на юг и закат в форте Галле, голландском городе XVII века.', ARRAY['Прогулка 2 часа']::text[], 'Свободное время.', 'Маяк и стены над океаном.'),
  ('srilanka-tea-ayurveda', 9, 'Аюрведа', ARRAY['Хиккадува','Центр аюрведы']::text[], 'Консультация врача, масляный массаж и лёгкий ужин по рекомендациям. Утро — йога на пляже.', ARRAY['Сеанс аюрведы','Йога']::text[], NULL, 'Тёплое масло и травы.'),
  ('srilanka-tea-ayurveda', 10, 'Свободный день', ARRAY['Мириса','Пляж']::text[], 'Свободный день: пляж, йога или наблюдение за китами (с ноября по апрель). Прощальный ужин.', ARRAY['Наблюдение за китами (по желанию)']::text[], 'Свободный день.', NULL),
  ('srilanka-tea-ayurveda', 11, 'Отъезд', ARRAY['Коломбо','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('tanzania-serengeti', 1, 'Аруша: прибытие и инструктаж', ARRAY['Аэропорт Килиманджаро','Аруша']::text[], 'Встреча, трансфер (около часа) в лодж на склонах горы Меру. Инструктаж гида по правилам безопасности, распределение по машинам, проверка снаряжения и бинокля.', ARRAY['Инструктаж']::text[], 'Вечер свободен.', 'Силуэт горы Меру в закатном свете.'),
  ('tanzania-serengeti', 2, 'Национальный парк Тарангире', ARRAY['Тарангире','Река Тарангире']::text[], 'Сафари среди баобабов. Сухой сезон собирает слонов и антилоп у русла реки, а под деревьями отдыхают львы. Между выездами — обед и отдых в лагере.', ARRAY['Сафари утром и вечером']::text[], 'Послеобеденный отдых.', 'Стада слонов на фоне баобабов.'),
  ('tanzania-serengeti', 3, 'Озеро Маньяра и переезд к Нгоронгоро', ARRAY['Озеро Маньяра','Кратер Нгоронгоро']::text[], 'Короткое сафари вдоль озера с павианами и розовыми фламинго, затем подъём на край кратера. Вечер в лодже с видом на кальдеру.', ARRAY['Сафари 3–4 часа']::text[], 'Вечер свободен.', 'Туман над краем кратера.'),
  ('tanzania-serengeti', 4, 'Кратер Нгоронгоро', ARRAY['Нгоронгоро','Озеро Маго']::text[], 'Спуск на дно кратера утром, когда животные активны. Львы, гиены, шакалы и чёрные носороги (по удаче) на открытой равнине. Пикник у озера с гиппопотамами.', ARRAY['Сафари 6 часов']::text[], NULL, 'Одна из самых плотных концентраций крупных животных в Африке.'),
  ('tanzania-serengeti', 5, 'Олдувайское ущелье и дорога в Серенгети', ARRAY['Олдувайское ущелье','Серенгети']::text[], 'Остановка у ущелья, где находили останки ранних гоминид. Затем переезд на север через равнины Серенгети. По пути встречаем жираф и зебр.', ARRAY['Экскурсия в музее']::text[], NULL, 'Бескрайняя равнина до горизонта.'),
  ('tanzania-serengeti', 6, 'Центральная Серенгети', ARRAY['Серонера','Река Серонера']::text[], 'Целый день на сафари в самом богатом животными районе. Гид отслеживает недавние встречи львов и леопардов, обед проходит на пикнике.', ARRAY['Сафари 8 часов']::text[], NULL, 'Леопарды отдыхают на ветвях акаций.'),
  ('tanzania-serengeti', 7, 'Северная Серенгети и река Мара', ARRAY['Северная Серенгети','Река Мара']::text[], 'В период миграции гну и зебр наблюдаем за переправами через реку Мара. Время переправы непредсказуемо, поэтому мы терпеливо ждём.', ARRAY['Сафари 8 часов']::text[], NULL, 'Крокодилы поджидают стада у брода.'),
  ('tanzania-serengeti', 8, 'Перелёт в Арушу', ARRAY['Взлётная полоса Кограту','Аруша']::text[], 'Утреннее сафари и перелёт на лёгком самолёте в Арушу (около часа). Отдых в лодже и общий прощальный ужин.', ARRAY['Перелёт']::text[], 'Вечер свободен.', 'Вид на Серенгети с высоты.'),
  ('tanzania-serengeti', 9, 'Отъезд', ARRAY['Аэропорт Килиманджаро']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('thailand-krabi-chiang-mai', 1, 'Чиангмай: прибытие и ночной рынок', ARRAY['Чиангмай','Старый город','Ночной базар']::text[], 'Встреча, заселение. Вечером — ночной рынок, где пробуем северные блюда: кхао-сой, сайуа и манго с рисом.', ARRAY['Ужин из уличной еды']::text[], 'Свободный вечер.', 'Красные тайские фонари над рынком.'),
  ('thailand-krabi-chiang-mai', 2, 'Храмы старого города', ARRAY['Ват Чеди Луанг','Ват Пхра Сингх']::text[], 'Утром идём по храмам старого города. Монахи рассказывают о жизни монастырей, можно поучаствовать в благословении.', ARRAY['Экскурсия 4 часа','Беседа с монахом']::text[], 'Свободное время.', 'Утренняя молитва.'),
  ('thailand-krabi-chiang-mai', 3, 'Дой Сутхеп', ARRAY['Дой Сутхеп','Ват Пхра Тхат']::text[], 'Подъём к золотому храму на горе (306 ступеней) и вид на город. Днём — деревня ремесленников.', ARRAY['Подъём 40 минут']::text[], 'Свободное время.', 'Золотая ступа сияет на закате.'),
  ('thailand-krabi-chiang-mai', 4, 'Этичный слоновий приют', ARRAY['Горы Чиангмая','Приют']::text[], 'День в приюте, где слонов не используют для катания: кормление, купание и прогулка по лесу. Обед из блюд, приготовленных деревенскими жителями.', ARRAY['Прогулка 2–3 часа']::text[], NULL, 'Слоны подходят к людям сами.'),
  ('thailand-krabi-chiang-mai', 5, 'Мастер-класс по тайской кухне', ARRAY['Местный рынок','Кулинарная школа']::text[], 'Рынок, выбор продуктов и приготовление пяти блюд: том ям, пад тай, зелёное карри, ларб и десерт.', ARRAY['Мастер-класс 4 часа']::text[], 'Вечер свободен.', 'Мы съедаем всё, что приготовили.'),
  ('thailand-krabi-chiang-mai', 6, 'Дой Интанон', ARRAY['Дой Интанон','Водопад Вачирафан','Королевские ступы']::text[], 'Высшая точка Таиланда (около 2 565 м) и тропа через мшистый лес. Водопад Вачирафан и ступы с садами.', ARRAY['Прогулка 2–3 часа']::text[], NULL, 'Туман над горными склонами.'),
  ('thailand-krabi-chiang-mai', 7, 'Перелёт в Краби', ARRAY['Краби','Ао Нанг']::text[], 'Перелёт в Краби и трансфер в Ао Нанг. Закат на пляже Ао Нанг и ужин из морепродуктов.', ARRAY['Перелёт 2 часа']::text[], 'Свободный вечер.', NULL),
  ('thailand-krabi-chiang-mai', 8, 'Рейли и скалы', ARRAY['Рейли','Пхра Нанг']::text[], 'На лодке к полуострову Рейли, доступному только по воде. Купание на пляже Пхра Нанг и прогулка к лагуне.', ARRAY['Каяки 1 час']::text[], 'Свободное время.', 'Известняковые скалы над бирюзовой водой.'),
  ('thailand-krabi-chiang-mai', 9, 'Четыре острова', ARRAY['Ко Пода','Ко Тап','Остров Курица']::text[], 'Выход на лодке на острова с белыми отмелями. Снорклинг на рифах и купание на песчаной косе.', ARRAY['Снорклинг 2 часа']::text[], NULL, 'Песчаная коса между островами.'),
  ('thailand-krabi-chiang-mai', 10, 'Остров Ко Ланта', ARRAY['Ко Ланта','Старый город']::text[], 'Переезд на паромах на остров, где сохранились деревни морских цыган. Вечер на пляже.', ARRAY['Паром 2 часа']::text[], 'Свободное время.', NULL),
  ('thailand-krabi-chiang-mai', 11, 'Свободный день на Ко Ланта', ARRAY['Ко Ланта','Национальный парк Му Ко Ланта']::text[], 'Свободный день: пляж, массаж, поездка на мотоцикле или прогулка в национальном парке на южной оконечности острова.', ARRAY[]::text[], 'Свободный день.', NULL),
  ('thailand-krabi-chiang-mai', 12, 'Отъезд', ARRAY['Краби','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('turkey-cappadocia-aegean', 1, 'Стамбул: прибытие', ARRAY['Аэропорт Стамбула','Султанахмет']::text[], 'Встреча в аэропорту, трансфер в отель в районе Султанахмет. Вечером — прогулка к набережной и ужин с видом на Мраморное море.', ARRAY['Прогулка по старому городу']::text[], 'Свободный вечер.', 'Вечерний призыв к молитве над крышами.'),
  ('turkey-cappadocia-aegean', 2, 'Стамбул: старый город и Босфор', ARRAY['Айя-София','Голубая мечеть','Цистерна Базилика','Гранд-базар']::text[], 'Утром — ранний вход в Айя-Софию, затем Голубая мечеть и подземная цистерна. После обеда — Гранд-базар и прогулка на пароме по Босфору.', ARRAY['Экскурсия 6 часов','Паром по Босфору']::text[], 'Вечер свободен.', 'Закат с борта парома между Европой и Азией.'),
  ('turkey-cappadocia-aegean', 3, 'Перелёт в Каппадокию', ARRAY['Невшехир','Гёреме','Учхисар']::text[], 'Утренний перелёт в Каппадокию. После обеда — музей под открытым небом в Гёреме с пещерными церквями и закат в Учхисаре.', ARRAY['Музей под открытым небом','Закат на смотровой']::text[], 'Заселение в пещерный отель.', 'Ночёвка в комнате, вырубленной в скале.'),
  ('turkey-cappadocia-aegean', 4, 'Долина Роз и Красная долина', ARRAY['Долина Роз','Красная долина','Чавушин']::text[], 'Прогулка по тропам между скал розового цвета. Остановка в заброшенной пещерной деревне Чавушин.', ARRAY['Треккинг 3–4 часа']::text[], 'После обеда — свободное время.', 'Закат окрашивает скалы в розовый цвет.'),
  ('turkey-cappadocia-aegean', 5, 'Деринкую и долина Ихлара', ARRAY['Деринкую','Долина Ихлара']::text[], 'Спуск в подземный город на несколько уровней, затем прогулка по каньону реки Мелендиз вдоль пещерных церквей.', ARRAY['Подземный город 1,5 часа','Прогулка по каньону 2 часа']::text[], NULL, 'Тоннели, где жили тысячи людей.'),
  ('turkey-cappadocia-aegean', 6, 'Перелёт в Измир и Эфес', ARRAY['Кайсери','Измир','Сельчук','Эфес']::text[], 'Перелёт через Стамбул или напрямую в Измир, переезд в Сельчук и осмотр Эфеса: Библиотека Цельса, большой театр, улица Куретов.', ARRAY['Осмотр Эфеса 3 часа']::text[], 'Вечерняя прогулка по Сельчуку.', 'Мраморная улица, по которой ходили римляне.'),
  ('turkey-cappadocia-aegean', 7, 'Памуккале и Иераполис', ARRAY['Памуккале','Иераполис','Бассейн Клеопатры']::text[], 'Белые травертины, термальные бассейны и руины античного города Иераполис. Купание в бассейне с римскими колоннами (по желанию).', ARRAY['Прогулка по террасам босиком','Купание в термальной воде']::text[], NULL, 'Закат на белых террасах.'),
  ('turkey-cappadocia-aegean', 8, 'Возвращение и прощальный ужин', ARRAY['Денизли','Измир']::text[], 'Переезд в Измир, прогулка по набережной и прощальный ужин с эгейскими закусками мезе.', ARRAY['Прощальный ужин']::text[], 'Свободное время.', NULL),
  ('turkey-cappadocia-aegean', 9, 'Отъезд', ARRAY['Измир','Аэропорт']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('tuscany-private-friends', 1, 'Прибытие на виллу', ARRAY['Аэропорт Флоренции','Сиена']::text[], 'Встреча в аэропорту и трансфер (около 1,5 часа) на виллу в окрестностях Сиены. Знакомство с хозяйкой, осмотр сада и ужин из местных продуктов.', ARRAY['Ужин на террасе']::text[], 'Свободный вечер.', 'Ужин при свечах на террасе.'),
  ('tuscany-private-friends', 2, 'Сиена', ARRAY['Сиена','Пьяцца дель Кампо','Дуомо']::text[], 'Центральная площадь в форме раковины, полосатый собор и переулки контрад. Подъём на башню Торре дель Манджа (по желанию).', ARRAY['Прогулка 3–4 часа']::text[], 'Свободное время на кофе и покупки.', 'Площадь, где проходит скачка Палио.'),
  ('tuscany-private-friends', 3, 'Кьянти', ARRAY['Кастеллина-ин-Кьянти','Греве','Радда']::text[], 'Дорога по Кьянти среди виноградников, остановки в деревнях и дегустация в семейной винодельне с обедом.', ARRAY['Дегустация']::text[], NULL, 'Чёрный петух на бутылках Кьянти Классико.'),
  ('tuscany-private-friends', 4, 'Валь-д’Орча', ARRAY['Пьенца','Бальо-Виньони','Монтальчино']::text[], 'Холмы с кипарисами, сыр пекорино в Пьенце и дегустация Брунелло в Монтальчино.', ARRAY['Прогулка 2 часа','Дегустация']::text[], NULL, 'Кипарисы на вершине холма.'),
  ('tuscany-private-friends', 5, 'День на вилле', ARRAY['Вилла','Местный рынок']::text[], 'Рынок, мастер-класс по ручной пасте и обед с хозяевами. Остаток дня — бассейн и отдых.', ARRAY['Мастер-класс']::text[], 'Свободное время.', 'Паста, приготовленная своими руками.'),
  ('tuscany-private-friends', 6, 'Сан-Джиминьяно и Вольтерра', ARRAY['Сан-Джиминьяно','Вольтерра']::text[], 'Башни Сан-Джиминьяно, мороженое чемпиона мира и вечерний свет в Вольтерре.', ARRAY['Прогулка 3 часа']::text[], NULL, 'Лабиринты средневековых улиц.'),
  ('tuscany-private-friends', 7, 'Отъезд', ARRAY['Сиена','Аэропорт Флоренции']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL),
  ('usa-route66', 1, 'Чикаго: старт трассы', ARRAY['Чикаго','Cloud Gate (Миллениум-парк)','Знак начала Route 66 на Адамс-стрит']::text[], 'Знакомство с группой, получение автомобиля, прогулка по центру Чикаго и фотография у знака начала трассы.', ARRAY['Прогулка по Миллениум-парку','Вечерний ужин с пиццей в стиле Чикаго']::text[], 'Вечер свободен.', 'Начало маршрута, который называют «главной улицей Америки».'),
  ('usa-route66', 2, 'Чикаго — Спрингфилд', ARRAY['Джолиет','Вильмингтон','Понтиак','Спрингфилд (Иллинойс)']::text[], 'Выезд из Чикаго, остановка в Понтиаке с музеем Route 66 и росписями на стенах. В Спрингфилде осматриваем центр и улицы, связанные с Авраамом Линкольном.', ARRAY['Музей Route 66 в Понтиаке','Короткая прогулка по центру']::text[], 'Свободное время вечером.', 'Старая заправка Gemini Giant — огромный фибергласовый космонавт.'),
  ('usa-route66', 3, 'Сент-Луис', ARRAY['Сент-Луис','Арка Гейтвей','Старый город']::text[], 'Переезд в Сент-Луис, подъём на арку Гейтвей и прогулка по набережной. Вечером — блюз или джаз в небольшом клубе.', ARRAY['Арка Гейтвей','Клуб с живой музыкой']::text[], 'Время для ужина по желанию.', 'Вид на Миссисипи с высоты 192 м.'),
  ('usa-route66', 4, 'Миссури: придорожные городки', ARRAY['Стэнтон','Куба (Миссури)','Спрингфилд (Миссури)']::text[], 'Дорога через холмы Миссури. Остановка в Кубе с настенной росписью по истории городка и в старой закусочной.', ARRAY['Фотоостановки','Ужин в ретро-кафе']::text[], NULL, 'Городки, где время идёт медленнее.'),
  ('usa-route66', 5, 'Талса и Блю-Уэйл', ARRAY['Джоплин','Каталу','Талса']::text[], 'Дорога через границу Оклахомы к Голубому киту — старому пруду с гигантской скульптурой. В Талсе — районы в стиле ар-деко и вечерний ужин.', ARRAY['Остановка у Blue Whale of Catoosa','Прогулка по Талсе']::text[], NULL, 'Скульптура кита в пруду, построенная в 1970-х как семейный проект.'),
  ('usa-route66', 6, 'Оклахома-Сити и Западная Оклахома', ARRAY['Оклахома-Сити','Эль-Рино','Клинтон']::text[], 'Остановка у мемориала, обед в Эль-Рино (фирменные луковые бургеры) и музей Route 66 в Клинтоне.', ARRAY['Музей Route 66','Обед в ретро-закусочной']::text[], NULL, NULL),
  ('usa-route66', 7, 'Амарилло: Кадиллак-ранчо', ARRAY['Шемрок','Амарилло','Cadillac Ranch']::text[], 'Старые заправки в Шемроке, затем Амарилло и Кадиллак-ранчо — десять автомобилей, вкопанных в землю. Баллончик для граффити — по желанию.', ARRAY['Съёмка на закате']::text[], NULL, 'Любой посетитель может оставить свой рисунок на автомобиле.'),
  ('usa-route66', 8, 'Тукумкари и Санта-Рози', ARRAY['Тукумкари','Санта-Рози','Голубая дыра']::text[], 'Тукумкари известен неоновыми вывесками мотелей, а Санта-Рози — «голубой дырой», где можно искупаться.', ARRAY['Вечерняя съёмка неоновых вывесок','Купание (по желанию)']::text[], NULL, 'Ночная прогулка по улице неонов.'),
  ('usa-route66', 9, 'Альбукерке и Санта-Фе', ARRAY['Санта-Фе','Альбукерке','Старый город']::text[], 'Утром — плаза Санта-Фе и глинобитная архитектура, затем Альбукерке с историческим центром и вывесками 50-х.', ARRAY['Прогулка по Санта-Фе','Ужин с мексиканской кухней']::text[], 'Вечер свободен.', 'Вкус зелёного чили — местного фирменного перца.'),
  ('usa-route66', 10, 'Окаменелый лес', ARRAY['Гэллап','Холбрук','Национальный парк Окаменелый лес','Раскрашенная пустыня']::text[], 'Дорога через индейскую территорию, национальный парк с окаменелыми деревьями и ночёвка в мотеле Wigwam с бетонными «типи».', ARRAY['Прогулки по парку 2–3 часа','Ночь в мотеле Wigwam']::text[], NULL, 'Деревья, которым около 200 миллионов лет, превратились в камень.'),
  ('usa-route66', 11, 'Флагстафф и Селигман', ARRAY['Уинслоу','Флагстафф','Селигман']::text[], 'Остановка в Уинслоу, где стоит памятник песне «Take It Easy», затем горный Флагстафф и старая деревня Селигман с шутливыми ретро-кафе.', ARRAY['Прогулка по Флагстаффу','Обед в Селигмане']::text[], NULL, NULL),
  ('usa-route66', 12, 'Оутман и Мохаве', ARRAY['Кингмен','Оутман','Нидлс','Мохаве']::text[], 'Шахтёрский городок Оутман, где по улицам бродят дикие ослы, затем переход через пустыню Мохаве.', ARRAY['Прогулка по Оутману','Фотоостановки в пустыне']::text[], NULL, 'Ослы — потомки животных, которых использовали шахтёры.'),
  ('usa-route66', 13, 'Калифорния', ARRAY['Барстоу','Сан-Бернардино','Пасадена']::text[], 'Переезд через южную Калифорнию к Лос-Анджелесу: музей Route 66 в Барстоу и ретро-кафе в Пасадене.', ARRAY['Музей Route 66']::text[], 'Вечер свободен.', NULL),
  ('usa-route66', 14, 'Санта-Моника: финиш', ARRAY['Санта-Моника','Пирс Санта-Моники']::text[], 'Последний отрезок до океана, фото у знака конца трассы, закат на пирсе и прощальный ужин.', ARRAY['Ужин на океанском берегу']::text[], 'Прощание и свободное время.', 'Финиш на тихоокеанском побережье.'),
  ('usa-southwest', 1, 'Лас-Вегас: старт', ARRAY['Лас-Вегас','Фремонт-стрит']::text[], 'Знакомство с группой, получение автомобиля и закупка продуктов на неделю. Вечером — прогулка по Стрипу.', ARRAY['Закупка продуктов']::text[], 'Вечер свободен.', 'Фонтаны Белладжио ночью.'),
  ('usa-southwest', 2, 'Зайон', ARRAY['Национальный парк Зайон','Каньон Зайон']::text[], 'Дорога в Юту (около 2,5 часа). Прогулка по тропе Riverside к Узким ущельям и вечер у кемпинга.', ARRAY['Прогулка 3 часа']::text[], NULL, 'Красные стены каньона.'),
  ('usa-southwest', 3, 'Брайс-Каньон', ARRAY['Брайс-Каньон','Тропа Навахо']::text[], 'Спуск между худу по тропе Navajo Loop и прогулка по Queen’s Garden. Закат на смотровой Sunset Point.', ARRAY['Прогулка 3 часа']::text[], NULL, 'Столбы худу светятся на закате.'),
  ('usa-southwest', 4, 'Scenic Byway 12', ARRAY['Эскаланте','Калф-Крик','Капитол-Риф']::text[], 'Одна из самых красивых дорог в США. Остановка у водопада Калф-Крик и ночёвка рядом с парком Капитол-Риф.', ARRAY['Прогулка 3–4 часа']::text[], NULL, 'Дорога вдоль гребня хребта.'),
  ('usa-southwest', 5, 'Моаб', ARRAY['Капитол-Риф','Моаб']::text[], 'Пейзажи Капитол-Риф утром и переезд в Моаб. Вечером — прогулка по городку и ужин в пивоварне.', ARRAY['Переезд 3 часа']::text[], 'Вечер свободен.', NULL),
  ('usa-southwest', 6, 'Арчес', ARRAY['Национальный парк Арчес','Делика-Арч']::text[], 'Прогулка к Делика-Арч (около 5 км туда и обратно) и закат под аркой. Сложный подъём по каменной плите.', ARRAY['Прогулка 3 часа']::text[], NULL, 'Арка на фоне гор Ла-Саль.'),
  ('usa-southwest', 7, 'Каньонлендс и Монумент-Вэлли', ARRAY['Каньонлендс','Дед-Хорс-Пойнт','Монумент-Вэлли']::text[], 'Утром — смотровые Island in the Sky, затем переезд в Монумент-Вэлли и закат у Нейми-Баттс.', ARRAY['Закат']::text[], NULL, 'Силуэты скал на закате.'),
  ('usa-southwest', 8, 'Антилоп-каньон и Хорсшу-Бенд', ARRAY['Пейдж','Антилоп-каньон','Хорсшу-Бенд']::text[], 'Экскурсия по узкому каньону с проводником навахо и закат у излучины реки Колорадо.', ARRAY['Каньон 1,5 часа','Смотровая']::text[], NULL, 'Лучи света внутри каньона.'),
  ('usa-southwest', 9, 'Гранд-Каньон', ARRAY['Гранд-Каньон','Южная кромка']::text[], 'Прогулка по краю каньона по тропе Rim Trail и закат на смотровой Hopi Point.', ARRAY['Прогулка 3–4 часа']::text[], NULL, 'Цвета меняются на закате.'),
  ('usa-southwest', 10, 'Седона', ARRAY['Седона','Беллрок','Каньон Оук-Крик']::text[], 'Красные скалы вокруг Седоны и короткие тропы. Вечером — смотровая на закат.', ARRAY['Прогулка 3 часа']::text[], 'Свободный вечер.', 'Скалы, окрашенные оксидом железа.'),
  ('usa-southwest', 11, 'Route 66 и возвращение', ARRAY['Селигман','Оутман','Лас-Вегас']::text[], 'Участок исторической трассы Route 66 через Селигман и Оутман с дикими ослами и ретро-кафе. Вечером — возврат в Лас-Вегас.', ARRAY['Остановки']::text[], NULL, 'Ослы гуляют по улицам.'),
  ('usa-southwest', 12, 'Сдача автомобиля', ARRAY['Лас-Вегас']::text[], 'Сдача автомобиля, прощальный завтрак и обмен фотографиями. Для тех, у кого поздний рейс, — свободное время в Лас-Вегасе.', ARRAY[]::text[], 'Свободный день до вылета.', NULL),
  ('vietnam-ha-giang-hoi-an', 1, 'Ханой: прибытие', ARRAY['Аэропорт Нойбай','Старый квартал','Озеро Хоанкьем']::text[], 'Встреча, трансфер и заселение. Вечером — прогулка по Старому кварталу и озеру Хоанкьем, ужин с булочками бань ми и яичным кофе.', ARRAY['Ужин из уличной еды']::text[], 'Свободный вечер.', 'Яичный кофе в узком кафе.'),
  ('vietnam-ha-giang-hoi-an', 2, 'Ханой: храмы и мастер-класс', ARRAY['Храм литературы','Старый квартал','Кулинарная школа']::text[], 'Храм литературы — старейший университет Вьетнама. Затем рынок и мастер-класс по ханойской лапше фо и рулетам.', ARRAY['Мастер-класс 3 часа']::text[], 'Вечер свободен.', 'Бульон варится восемь часов.'),
  ('vietnam-ha-giang-hoi-an', 3, 'Дорога в Ха Занг', ARRAY['Ха Занг','Куан Ба','Небесные ворота']::text[], 'Переезд в Ха Занг (около 6–7 часов). Остановка на перевале Небесные ворота и вид на два холма в долине.', ARRAY['Остановки по дороге']::text[], 'Вечер отдыха.', 'Облака ниже уровня дороги.'),
  ('vietnam-ha-giang-hoi-an', 4, 'Плато Донг Ван', ARRAY['Йен Минь','Донг Ван','Мео Вак']::text[], 'День на каменном плато среди деревень народов хмонг и яо. Воскресный рынок (если день совпал) и остановка у дворца хмонгского короля.', ARRAY['Мотоцикл или микроавтобус']::text[], NULL, 'Карстовые скалы вдоль дороги.'),
  ('vietnam-ha-giang-hoi-an', 5, 'Перевал Ма Пи Ленг', ARRAY['Ма Пи Ленг','Ньо Кэ']::text[], 'Самый известный перевал страны с серпантином вдоль обрыва и лодка по ущелью реки Ньо Кэ, где вода зелёного цвета.', ARRAY['Лодка 1,5 часа']::text[], NULL, 'Обрыв глубиной около 800 м.'),
  ('vietnam-ha-giang-hoi-an', 6, 'Возвращение в Ханой', ARRAY['Ха Занг','Ханой']::text[], 'Длинный день в дороге (около 7 часов). Вечер в Ханое с ужином и отдыхом.', ARRAY['Переезд 7 часов']::text[], 'Вечер свободен.', NULL),
  ('vietnam-ha-giang-hoi-an', 7, 'Бухта Лан Ха', ARRAY['Хайфон','Бухта Лан Ха']::text[], 'Переезд к бухте и посадка на лодку. Каяки среди скал, купание и ужин на борту. Ночь на воде.', ARRAY['Каяки','Купание']::text[], 'Вечер на палубе.', 'Карстовые острова в тумане.'),
  ('vietnam-ha-giang-hoi-an', 8, 'Хойан: прибытие', ARRAY['Бухта Лан Ха','Дананг','Хойан']::text[], 'Утро на воде, затем возвращение в Ханой и перелёт в Дананг. Заселение в Хойане и прогулка по старому городу с фонарями.', ARRAY['Перелёт 1,5 часа']::text[], 'Вечер свободен.', 'Фонарики на реке Тхубон.'),
  ('vietnam-ha-giang-hoi-an', 9, 'Хойан: кухня и деревня', ARRAY['Хойан','Деревня Чабуэ','Рисовые поля']::text[], 'Рынок, мастер-класс по кухне Хойана (као лау, бань сео) и велопрогулка по деревне овощеводов.', ARRAY['Мастер-класс 3–4 часа','Велопрогулка']::text[], NULL, 'Свежая зелень, собранная утром.'),
  ('vietnam-ha-giang-hoi-an', 10, 'Мишон и свободный день', ARRAY['Мишон','Хойан']::text[], 'Утренняя поездка в святилища чамов Мишон, затем свободное время в Хойане: тайлор-ателье, лавки, пляж.', ARRAY['Экскурсия 3 часа']::text[], 'Свободное время.', NULL),
  ('vietnam-ha-giang-hoi-an', 11, 'Перевал Хайван и Хюэ', ARRAY['Перевал Хайван','Хюэ','Императорская цитадель']::text[], 'Дорога по перевалу Хайван с видом на море, затем Хюэ и Императорская цитадель династии Нгуен.', ARRAY['Осмотр цитадели']::text[], 'Вечер свободен.', NULL),
  ('vietnam-ha-giang-hoi-an', 12, 'Хюэ — Хошимин', ARRAY['Хюэ','Хошимин','Рынок Бенхань']::text[], 'Перелёт на юг и вечерняя прогулка по Хошимину: собор Нотр-Дам, почтамт и рынок Бенхань.', ARRAY['Перелёт 1,5 часа']::text[], 'Свободный вечер.', NULL),
  ('vietnam-ha-giang-hoi-an', 13, 'Дельта Меконга', ARRAY['Меконг','Бенче']::text[], 'Выезд на лодке между рукавами реки, остановки в мастерских кокосовых конфет и плантациях тропических фруктов.', ARRAY['Лодка 2 часа']::text[], 'Вечер свободен.', NULL),
  ('vietnam-ha-giang-hoi-an', 14, 'Отъезд', ARRAY['Хошимин','Аэропорт Таншоннят']::text[], 'Завтрак и трансфер в аэропорт.', ARRAY[]::text[], NULL, NULL);
INSERT INTO tour_faq (tour_id, position, question, answer) VALUES
  ('bali-retreat', 1, 'Нужна ли подготовка?', 'Нет, практика адаптируется под новичков, сложные упражнения предлагаются по желанию.'),
  ('bali-retreat', 2, 'Можно ли не участвовать в йоге?', 'Да. Занятия не обязательны, у вас остаётся свободное время.'),
  ('bali-retreat', 3, 'Как с питанием для вегетарианцев?', 'Меню легко адаптируется. Сообщите нам при бронировании.'),
  ('bernese-oberland-traverse', 1, 'Нужен ли опыт?', 'Да, нужны регулярные многочасовые походы.'),
  ('bernese-oberland-traverse', 2, 'Можно ли пройти не весь маршрут?', 'Да, можно сократить участки по канатным дорогам.'),
  ('bernese-oberland-traverse', 3, 'Что с погодой?', 'Гид корректирует маршрут по прогнозу.'),
  ('dolomites-lakes', 1, 'Нужен ли опыт горных походов?', 'Нужен базовый опыт: 5–6 часов ходьбы с небольшим набором высоты. Техническое лазание не требуется.'),
  ('dolomites-lakes', 2, 'Что делать, если пойдёт дождь?', 'Гид меняет порядок дней или выбирает более короткий маршрут. Если выход небезопасен, мы остаёмся в Кортине и предлагаем экскурсию в долине.'),
  ('dolomites-lakes', 3, 'Можно ли оставить лишние вещи в отеле?', 'Да. На ночь в приюте берём только небольшой рюкзак, основной багаж остаётся в отеле.'),
  ('dubai-desert', 1, 'Это подойдёт семьям с детьми?', 'Да, маршрут лёгкий.'),
  ('dubai-desert', 2, 'Нужна ли виза?', 'Проверяется менеджером.'),
  ('dubai-desert', 3, 'Можно ли продлить поездку?', 'Да, можно добавить дни на побережье.'),
  ('egypt-ancient', 1, 'Безопасно ли ехать в Египет?', 'Маршрут проходит по туристическим районам. Перед бронированием менеджер проверяет рекомендации официальных ведомств по безопасности и сообщает о них.'),
  ('egypt-ancient', 2, 'Нужна ли виза?', 'Правила въезда зависят от гражданства и меняются. Информацию подтверждает менеджер.'),
  ('egypt-ancient', 3, 'Можно ли сократить маршрут?', 'Да, мы можем предложить вариант на 6–7 дней без круиза.'),
  ('fuji-hike', 1, 'Нужна ли подготовка?', 'Да, желательно тренироваться заранее: ходьба 4–6 часов с набором высоты.'),
  ('fuji-hike', 2, 'Что если погода плохая?', 'Гид переносит подъём на запасной день или заменяет маршрутом ниже.'),
  ('fuji-hike', 3, 'Можно ли подняться в другое время?', 'Нет, вне сезона подъём закрыт.'),
  ('georgia-wine-mountains', 1, 'Можно ли не пить вино?', 'Да, есть безалкогольные варианты.'),
  ('georgia-wine-mountains', 2, 'Подойдёт ли вегетарианцам?', 'Грузинская кухня богата вегетарианскими блюдами.'),
  ('georgia-wine-mountains', 3, 'Нужна ли виза?', 'Проверяется.'),
  ('iceland-aurora', 1, 'Увидим ли мы сияние?', 'Это зависит от погоды и солнечной активности. Мы выбираем даты и выезды так, чтобы шансов было как можно больше, но гарантировать явление нельзя.'),
  ('iceland-aurora', 2, 'Подойдёт ли смартфон?', 'Да, но лучше иметь камеру с ручным режимом и штатив. Инструктор покажет, как снимать на смартфон.'),
  ('iceland-aurora', 3, 'Что если пещера будет закрыта?', 'Мы заменяем её другой экскурсией (например, лавовая пещера) или оставляем время на съёмку.'),
  ('iceland-ring', 1, 'Что если дорога закрыта?', 'Гид меняет маршрут.'),
  ('iceland-ring', 2, 'Нужна ли виза?', 'Проверяется.'),
  ('iceland-ring', 3, 'Можно ли купаться?', 'Да, в термальных бассейнах.'),
  ('jordan-petra-wadi-rum', 1, 'Что такое Jordan Pass?', 'Единый пропуск для въезда и входов. Информацию уточняет менеджер.'),
  ('jordan-petra-wadi-rum', 2, 'Нужна ли виза?', 'Проверяется.'),
  ('jordan-petra-wadi-rum', 3, 'Безопасно ли в Иордании?', 'Менеджер сообщает официальные рекомендации.'),
  ('kamchatka-volcanoes', 1, 'Это безопасно из-за медведей?', 'Мы идём с гидом, соблюдаем правила и держим дистанцию.'),
  ('kamchatka-volcanoes', 2, 'Нужны ли документы?', 'Часть районов требует разрешений.'),
  ('kamchatka-volcanoes', 3, 'Что если вертолёт не полетит?', 'Возможна замена другим маршрутом.'),
  ('korea-seoul-jeju', 1, 'Нужна ли виза?', 'Проверяется.'),
  ('korea-seoul-jeju', 2, 'Это дорого?', 'Цены демонстрационные.'),
  ('korea-seoul-jeju', 3, 'Подойдёт ли вегетарианцам?', 'Да, но нужно предупредить заранее.'),
  ('kyoto-tea', 1, 'Нужно ли знать японский?', 'Нет. Гид переводит, а мастера привыкли работать с иностранцами.'),
  ('kyoto-tea', 2, 'Можно ли поехать зимой?', 'Зимой Киото тише и дешевле, но программа меняется: сады без листвы, меньше уличных точек. Такой вариант обсуждается отдельно.'),
  ('kyoto-tea', 3, 'Как с питанием для вегетарианцев?', 'Возможен вариант, но кайсэки в рёкане нужно заказывать заранее. Сообщите при бронировании.'),
  ('maldives-snorkel', 1, 'Что с алкоголем?', 'На местных островах его нет.'),
  ('maldives-snorkel', 2, 'Можно ли загорать в купальнике?', 'Да, на специально отведённом пляже для туристов.'),
  ('maldives-snorkel', 3, 'Нужно ли уметь плавать?', 'Да, при снорклинге необходим жилет и умение держаться на воде.'),
  ('mongolia-nomads-gobi', 1, 'Как с душем?', 'Ограничен.'),
  ('mongolia-nomads-gobi', 2, 'Нужна ли виза?', 'Проверяется.'),
  ('mongolia-nomads-gobi', 3, 'Можно ли ехать зимой?', 'Нет.'),
  ('morocco-sahara-medina', 1, 'Нужно ли знать французский?', 'Нет.'),
  ('morocco-sahara-medina', 2, 'Как с женщинами-путешественницами?', 'Одежда должна быть скромной. Гид помогает ориентироваться.'),
  ('morocco-sahara-medina', 3, 'Нужна ли виза?', 'Проверяется.'),
  ('nepal-annapurna-base-camp', 1, 'Нужна ли подготовка?', 'Да, рекомендуем тренироваться за 2–3 месяца: ходьба 4–6 часов, подъёмы по лестницам.'),
  ('nepal-annapurna-base-camp', 2, 'Что если станет плохо на высоте?', 'Гид следит за симптомами. При необходимости группа спускается, а в экстренных случаях организуется эвакуация, покрываемая страховкой.'),
  ('nepal-annapurna-base-camp', 3, 'Нужна ли виза?', 'Информацию подтверждает менеджер.'),
  ('newzealand-south-island', 1, 'Движение левостороннее?', 'Да.'),
  ('newzealand-south-island', 2, 'Нужна ли виза?', 'Проверяется.'),
  ('newzealand-south-island', 3, 'Можно ли ехать зимой?', 'Другой маршрут.'),
  ('norway-lofoten', 1, 'Увидим ли мы северное сияние?', 'В июне — июле — нет, ночи светлые. Сияние возможно с конца августа.'),
  ('norway-lofoten', 2, 'Нужна ли особая подготовка?', 'Достаточно обычной физической формы.'),
  ('norway-lofoten', 3, 'Что если погода плохая?', 'Гид переносит выходы и меняет порядок дней.'),
  ('peru-salkantay', 1, 'Чем отличается от Инка-трейл?', 'В отличие от классической Инка-трейл, на тропе Салкантай нет жёсткой квоты на разрешения. Но билеты в Мачу-Пикчу ограничены по датам и времени, их подтверждает оператор. Тропа проходит через разные природные зоны: от ледников до облачного леса.'),
  ('peru-salkantay', 2, 'Нужна ли акклиматизация?', 'Да, поэтому первые дни проходят в Куско.'),
  ('peru-salkantay', 3, 'Нужна ли виза?', 'Проверяется.'),
  ('portugal-lisbon-douro', 1, 'Подойдёт ли вегетарианцам?', 'Да.'),
  ('portugal-lisbon-douro', 2, 'Нужна ли виза?', 'Проверяется.'),
  ('portugal-lisbon-douro', 3, 'Алкоголь обязателен?', 'Нет.'),
  ('rajasthan-spice', 1, 'Подойдёт ли вегетарианцам?', 'Да, раджастханская кухня богата вегетарианскими блюдами.'),
  ('rajasthan-spice', 2, 'Нужна ли виза?', 'Информация подтверждается менеджером.'),
  ('rajasthan-spice', 3, 'Безопасно ли есть на улице?', 'Мы выбираем места, где едят местные, но желудок может реагировать, берите нужные препараты.'),
  ('srilanka-tea-ayurveda', 1, 'Подойдёт ли вегетарианцам?', 'Да.'),
  ('srilanka-tea-ayurveda', 2, 'Это не слишком остро?', 'Блюда можно сделать менее острыми.'),
  ('srilanka-tea-ayurveda', 3, 'Нужна ли виза?', 'Проверяется.'),
  ('tanzania-serengeti', 1, 'Нужны ли прививки?', 'Требования проверяются менеджером.'),
  ('tanzania-serengeti', 2, 'Увидим ли мы всех животных?', 'Нет гарантии.'),
  ('tanzania-serengeti', 3, 'Безопасно ли?', 'Да, при соблюдении правил.'),
  ('thailand-krabi-chiang-mai', 1, 'Катаетесь ли на слонах?', 'Нет.'),
  ('thailand-krabi-chiang-mai', 2, 'Подойдёт ли детям?', 'Да, подростки комфортно.'),
  ('thailand-krabi-chiang-mai', 3, 'Нужна ли виза?', 'Проверяется.'),
  ('turkey-cappadocia-aegean', 1, 'Гарантирован ли полёт на воздушном шаре?', 'Нет. Он зависит от погоды и решения операторов. Мы оставляем запасной день.'),
  ('turkey-cappadocia-aegean', 2, 'Подойдёт ли с детьми?', 'Да, подросткам комфортно.'),
  ('turkey-cappadocia-aegean', 3, 'Нужна ли виза?', 'Проверяется менеджером.'),
  ('tuscany-private-friends', 1, 'Можно ли поменять программу?', 'Да, это приватный формат.'),
  ('tuscany-private-friends', 2, 'Сколько человек нужно?', 'От 4 до 8.'),
  ('tuscany-private-friends', 3, 'Нужна ли виза?', 'Проверяется.'),
  ('usa-route66', 1, 'Нужна ли виза?', 'Правила въезда в США зависят от гражданства и меняются. Информацию подтверждает менеджер.'),
  ('usa-route66', 2, 'Нужно ли водить самому?', 'Желательно, но в группе есть несколько водителей.'),
  ('usa-route66', 3, 'Можно ли проехать только часть маршрута?', 'Да, возможны варианты с началом в Сент-Луисе.'),
  ('usa-southwest', 1, 'Нужна ли виза?', 'Правила въезда в США зависят от гражданства. Информацию подтверждает менеджер.'),
  ('usa-southwest', 2, 'Нужно ли уметь водить?', 'Нужно право на вождение. Водители в группе меняются.'),
