INSERT INTO company_faq (position, category, question, answer) VALUES
  (1, 'booking', 'Это реальная компания? Можно ли уже бронировать туры?', 'Нет. Сайт — демонстрационная основа проекта. Цены, даты выездов и места иллюстративные, сайт не принимает платежи и не оформляет бронирование. Форма запроса показывает, как будет работать приём заявок.'),
  (2, 'booking', 'Как будет проходить бронирование после запуска?', 'Вы выбираете тур и дату, оставляете запрос, менеджер или AI-консультант подтверждает наличие мест, затем вы подписываете договор и вносите предоплату. Подробнее на странице «Бронирование и оплата».'),
  (3, 'groups', 'Какой размер групп?', 'Минимальный и максимальный состав указан в каждой карточке: обычно от 4 до 12 человек. Для приватных поездок группа формируется под вас.'),
  (4, 'groups', 'Могу ли я поехать один?', 'Да. В малых группах много путешественников, которые едут без компании. Для проживания можно выбрать подселение или оплатить одноместное размещение — доплата указывается в карточке тура.'),
  (5, 'fitness', 'Как понять, подойдёт ли мне маршрут по нагрузке?', 'В каждой карточке есть уровень сложности (1–3), описание нагрузки и раздел «Кому не подойдёт». Если сомневаетесь, опишите свою подготовку консультанту, и он предложит более лёгкий вариант.'),
  (6, 'payment', 'Какая предоплата и когда нужно платить остаток?', 'В шаблоне условий: предоплата 20% при подтверждении, остаток за 30 дней до выезда. Окончательные условия будут зафиксированы в договоре.'),
  (7, 'payment', 'Что делать, если я не смогу поехать?', 'Размер возврата зависит от того, за сколько дней до выезда вы отменяете поездку. Шаблон условий — на странице «Бронирование и оплата». Рекомендуем страховку с покрытием отмены.'),
  (8, 'documents', 'Нужна ли виза?', 'Это зависит от гражданства и страны. На сайте указаны только ориентировочные сведения, менеджер проверяет актуальные требования перед бронированием.'),
  (9, 'travel', 'Входят ли в стоимость авиабилеты?', 'Как правило, нет. Мы указываем точку начала и окончания маршрута и помогаем подобрать рейсы, но билеты покупаются отдельно. Исключения указаны в карточке тура.'),
  (10, 'travel', 'Как вы работаете с особенностями питания?', 'При бронировании вы указываете ограничения: вегетарианское меню, аллергии, непереносимость. Для отдалённых маршрутов выбор может быть ограничен, об этом написано в карточке.'),
  (11, 'ai', 'Что такое NOMAD AI Sales Agent?', 'Это отдельная AI-система, которая в будущем будет помогать подбирать путешествия по бюджету, сезону и интересам и отвечать на вопросы по каталогу. Данные каталога подготовлены в структурированном виде специально для неё.');
